function Reset-TkWindowsStore {
    [CmdletBinding(SupportsShouldProcess)]
    [OutputType([bool])]
    param()

    if (-not $PSCmdlet.ShouldProcess($env:COMPUTERNAME, 'Reset the Microsoft Store cache')) {
