# Source: src/UI/Window.ps1
# ==========================================================================

<#
    Toolkit - UI / Main window

    Builds the window from XAML, registers every named control in the shared
    context and wires the navigation. Feature pages are initialised by their
    own files so this one stays about the shell only.
#>

# Set by the build script for the single file release. Empty during
# development, where the XAML is read from disk instead.
$script:TkEmbeddedXaml = ''

# Work a page wants done the first time it is opened, and the record of which
# pages have already been opened. Kept here rather than as a flag on each
# page so that adding one to a new page is a single Register call.
$script:TkFirstShowAction = @{}
$script:TkPageOpened      = @{}

# How many background actions are still running. See Enter-TkBusy.
$script:TkBusyCount = 0

# Cards still reading, with the moment each started, and the one timer that
# counts their seconds. See Start-TkLoadingClock.
$script:TkLoadingStarted = @{}
$script:TkLoadingTimer   = $null

<#
.SYNOPSIS
    Returns the main window XAML.

.DESCRIPTION
    Prefers the copy embedded at build time so a release has no external
    dependency, and falls back to the file next to the sources during
    development.

.OUTPUTS
    System.String
#>
function Get-TkMainWindowXaml {
    [CmdletBinding()]
    [OutputType([string])]
    param()

    if (-not [string]::IsNullOrWhiteSpace($script:TkEmbeddedXaml)) {
        return $script:TkEmbeddedXaml
    }

    $candidates = @()

    if ($PSScriptRoot) {
        $candidates += (Join-Path -Path $PSScriptRoot -ChildPath 'MainWindow.xaml')
        $candidates += (Join-Path -Path $PSScriptRoot -ChildPath 'UI\MainWindow.xaml')
    }

    $candidates += (Join-Path -Path (Get-Location).Path -ChildPath 'src\UI\MainWindow.xaml')

    foreach ($candidate in $candidates) {

        if (Test-Path -LiteralPath $candidate) {
            return (Get-Content -LiteralPath $candidate -Raw -Encoding UTF8)
        }
    }

    throw 'MainWindow.xaml was not found and no XAML is embedded in this build.'
}

<#
.SYNOPSIS
    Creates the window and returns it.

.DESCRIPTION
    Parses the XAML, then walks every x:Name in the markup and stores the
    matching control in the context. Doing this once means page code can say
    $ctx.Controls['BtnRefresh'] instead of calling FindName everywhere.

.OUTPUTS
    System.Windows.Window
#>
function New-TkMainWindow {
    [CmdletBinding()]
    [OutputType([System.Windows.Window])]
    param()

    $ctx  = Get-TkContext
    $xaml = Get-TkMainWindowXaml

    try {
        $reader = New-Object System.Xml.XmlNodeReader ([xml] $xaml)
        $window = [Windows.Markup.XamlReader]::Load($reader)
    }
    catch {
        throw ('The interface could not be built from XAML: {0}' -f $_.Exception.Message)
    }

    $ctx.Window   = $window
    $ctx.Controls = @{}

    foreach ($match in [regex]::Matches($xaml, 'x:Name="(?<name>[^"]+)"')) {

        $name    = $match.Groups['name'].Value
        $control = $window.FindName($name)

        if ($null -ne $control) {
            $ctx.Controls[$name] = $control
        }
    }

    Write-TkLog -Level Debug -Category 'UI' -Message (
        '{0} named controls registered.' -f $ctx.Controls.Count
    )

    return $window
}

<#
.SYNOPSIS
    Returns a registered control by name.

.DESCRIPTION
    Returns $null rather than throwing when a control is missing, so a page
    that references a control removed from the XAML degrades instead of
    taking the whole window down.

.OUTPUTS
    System.Windows.DependencyObject
#>
function Get-TkControl {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string] $Name
    )

    $ctx = Get-TkContext

    if ($ctx.Controls.ContainsKey($Name)) {
        return $ctx.Controls[$Name]
    }

    Write-TkLog -Level Debug -Category 'UI' -Message ('Unknown control "{0}".' -f $Name)

    return $null
}

<#
.SYNOPSIS
    Attaches a click handler to a button.

.DESCRIPTION
    Convenience wrapper that tolerates a missing control, which keeps page
    initialisation free of repeated null checks.
#>
function Register-TkClick {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string] $Name,

        [Parameter(Mandatory)]
        [scriptblock] $Action
    )

    $control = Get-TkControl -Name $Name

    if ($null -eq $control) {
        return
    }

    $control.Add_Click($Action)
}

<#
.SYNOPSIS
    Finds the first descendant of a given type in a control's visual tree.

.DESCRIPTION
    For reaching an element that lives inside a template, where FindName
    cannot see it: the items panel of an ItemsControl is declared in an
    ItemsPanelTemplate and is not a named part of the window.

    Breadth first, so the nearest match wins rather than whichever branch is
    deepest. Returns nothing when there is no match, and when the control has
    not been laid out yet, which is the usual reason to find nothing.

.PARAMETER Parent
    Where to start.

.PARAMETER TypeName
    Short type name, for example UniformGrid.

.OUTPUTS
    System.Windows.DependencyObject, or $null.
#>
function Find-TkVisualChild {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [AllowNull()]
        [System.Windows.DependencyObject] $Parent,

        [Parameter(Mandatory)]
        [string] $TypeName
    )

    if ($null -eq $Parent) {
        return $null
    }

    $queue = New-Object 'System.Collections.Generic.Queue[System.Windows.DependencyObject]'
    $queue.Enqueue($Parent)

    while ($queue.Count -gt 0) {

        $current = $queue.Dequeue()
        $count   = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($current)

        for ($i = 0; $i -lt $count; $i++) {

            $child = [System.Windows.Media.VisualTreeHelper]::GetChild($current, $i)

            if ($child.GetType().Name -eq $TypeName) {
                return $child
            }

            $queue.Enqueue($child)
        }
    }

    return $null
}

<#
.SYNOPSIS
    Registers work to run the first time a page is opened.

.DESCRIPTION
    Some pages are only truthful once they have read the machine. The Software
    list is the clear case: until the installed packages have been read, every
    entry looks available, including the twenty already on the disk. Making
    the operator press Refresh to find that out puts the burden the wrong way
    round.

    The work runs on first open rather than at start up, because it costs a
    winget call and a page nobody visits should not pay for it.

.PARAMETER PageName
    Page key, as passed to Show-TkPage.

.PARAMETER Action
    Script block to run once.
#>
function Register-TkFirstShow {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string] $PageName,

        [Parameter(Mandatory)]
        [scriptblock] $Action
    )

    $script:TkFirstShowAction[$PageName] = $Action
}

<#
.SYNOPSIS
    Returns the page names, in navigation order.

.DESCRIPTION
    The one list of pages. Adding a page used to mean a parameter validation
    and three copies of the same array in this file, and missing one left a
    page that could be shown but never highlighted, or a button that did
    nothing. A test checks that every name here has its navigation button and
    its panel in the markup, and that the markup has no page this list lacks.

.OUTPUTS
    System.String[]
#>
function Get-TkPageName {
    [CmdletBinding()]
    [OutputType([string[]])]
    param()

    return @(
        'Dashboard', 'System', 'Software', 'Tweaks', 'Fixes', 'Intervention',   # Workstation
        'Diagnostics', 'Network',                              # Troubleshooting
        'Security', 'SecurityTools',                           # Security
        'Knowledge', 'VendorCommands',                         # Reference
        'Settings'
    )
}

<#
.SYNOPSIS
    Shows one feature page and hides the others.

.PARAMETER Name
    Page key, one of the names Get-TkPageName returns.
#>
function Show-TkPage {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [ValidateScript({ @(Get-TkPageName) -contains $_ })]
        [string] $Name
    )

    $ctx = Get-TkContext

    foreach ($page in @(Get-TkPageName)) {

        $control = Get-TkControl -Name ('Page{0}' -f $page)

        if ($null -eq $control) {
            continue
        }

        if ($page -eq $Name) {
            $control.Visibility = [System.Windows.Visibility]::Visible
        }
        else {
            $control.Visibility = [System.Windows.Visibility]::Collapsed
        }
    }

    # Highlight the active navigation entry.
    foreach ($page in @(Get-TkPageName)) {

        $button = Get-TkControl -Name ('Nav{0}' -f $page)

        if ($null -eq $button) {
            continue
        }

        if ($page -eq $Name) {
            # By resource reference, so the active entry follows a theme change
            # by itself. A brush assigned directly keeps the palette it was
            # assigned from, which is why the theme used to show the last page
            # again to repaint it, with the consequence described below.
            $button.SetResourceReference([System.Windows.Controls.Control]::BackgroundProperty, 'Selection')
            $button.FontWeight = [System.Windows.FontWeights]::SemiBold
        }
        else {
            $button.Background = [System.Windows.Media.Brushes]::Transparent
            $button.FontWeight = [System.Windows.FontWeights]::Normal
        }
    }

    $ctx.Settings['LastPage'] = $Name

    # First open only, and only once there is something to run.
    #
    # The flag used to be set on any first visit. At start up the theme showed
    # the last page of the previous session before that page had registered
    # what to load, so the page was marked opened with nothing run, and the
    # action registered a moment later never ran: the System page then opened
    # with every card reading for ever, until Refresh. The flag is still set
    # before the action runs, so an action that throws does not queue itself
    # again on the next visit.
    if ($script:TkFirstShowAction.ContainsKey($Name) -and -not $script:TkPageOpened.ContainsKey($Name)) {

        $script:TkPageOpened[$Name] = $true

        try {
            & $script:TkFirstShowAction[$Name]
        }
        catch {
            Write-TkLog -Level Warning -Category 'Interface' -Message (
                'The {0} page could not finish its first load: {1}' -f $Name, $_.Exception.Message
            )
        }
    }
}

<#
.SYNOPSIS
    Selects a tab by its header.

.DESCRIPTION
    Matched on the header rather than the position, so a tab moved or added
    later cannot silently send a quick action to the wrong place.

.PARAMETER TabControlName
    Name of the TabControl in the markup.

.PARAMETER Header
    Header text of the tab to select.

.OUTPUTS
    System.Boolean, true when the tab was found.
#>
function Select-TkTab {
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [Parameter(Mandatory)]
        [string] $TabControlName,

        [Parameter(Mandatory)]
        [string] $Header
    )

    $tabs = Get-TkControl -Name $TabControlName

    if ($null -eq $tabs) {
        return $false
    }

    foreach ($item in $tabs.Items) {

        if ($item -is [System.Windows.Controls.TabItem] -and [string] $item.Header -eq $Header) {
            $item.IsSelected = $true
            return $true
        }
    }

    return $false
}

<#
.SYNOPSIS
    Marks one more piece of background work as running.

.DESCRIPTION
    Pages read in several parts at once. With a single on and off switch the
    first part to finish hid the busy bar and said "Ready." while the others
    were still reading, which is the page with no sign of life this exists to
    prevent. A count keeps the bar up until the last one ends.

.PARAMETER Text
    What is being done, for the status bar.
#>
function Enter-TkBusy {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string] $Text
    )

    $script:TkBusyCount++

    Set-TkStatus -Text $Text -Busy $true
}

<#
.SYNOPSIS
    Marks one piece of background work as finished.

.DESCRIPTION
    Says "Ready." only once nothing else is running. Never goes below zero, so
    one stray call cannot leave the count permanently off by one.
#>
function Exit-TkBusy {
    [CmdletBinding()]
    param()

    $script:TkBusyCount = [math]::Max(0, $script:TkBusyCount - 1)

    if ($script:TkBusyCount -eq 0) {
        Set-TkStatus -Text 'Ready.'
    }
}

<#
.SYNOPSIS
    Returns how many background actions are still running.
#>
function Get-TkBusyCount {
    [CmdletBinding()]
    [OutputType([int])]
    param()

    return [int] $script:TkBusyCount
}

<#
.SYNOPSIS
    Shows a card as reading, or as read.

.DESCRIPTION
    A card that fills in the background carries two children in the markup,
    by name: <Name>Loading, a moving bar with a line saying what is being read,
    and <Name>Content, the fields. Swapping them means a page never shows empty
    fields that look like missing data.

    On a refresh the content already shown stays in place under the moving
    bar, rather than disappearing and coming back: only a card that has never
    been filled hides its fields while it reads.

    A test checks that every Loading in the markup has its Content and its
    LoadingText.

.PARAMETER Name
    The prefix shared by the two children.

.PARAMETER Loading
    True while reading.
#>
function Set-TkCardLoading {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string] $Name,

        [Parameter(Mandatory)]
        [bool] $Loading
    )

    $indicator = Get-TkControl -Name ('{0}Loading' -f $Name)
    $content   = Get-TkControl -Name ('{0}Content' -f $Name)

    if ($indicator) {

        $indicator.Visibility = if ($Loading) { [System.Windows.Visibility]::Visible }
                                else { [System.Windows.Visibility]::Collapsed }

        if ($Loading) {
            $script:TkLoadingStarted[$Name] = Get-Date
            Start-TkLoadingClock
        }
        else {
            [void] $script:TkLoadingStarted.Remove($Name)

            # Back to the plain text, so the next read starts its count at zero.
            $label = Get-TkControl -Name ('{0}LoadingText' -f $Name)

            if ($label -and $null -ne $label.Tag) {
                $label.Text = [string] $label.Tag
            }
        }
    }

    if ($null -eq $content) {
        return
    }

    if (-not $Loading) {
        $content.Tag        = 'Filled'
        $content.Visibility = [System.Windows.Visibility]::Visible
        return
    }

    if ([string] $content.Tag -ne 'Filled') {
        $content.Visibility = [System.Windows.Visibility]::Collapsed
    }
}

<#
.SYNOPSIS
    Counts the seconds on every card that is still reading.

.DESCRIPTION
    A moving bar alone cannot tell slow from stuck. Some readings really are
    slow on some machines, platform security above all, and past a few seconds
    the operator should see that time is being counted rather than wonder
    whether anything is still happening. One timer serves every card, and it
    stops itself when no card is reading.
#>
function Start-TkLoadingClock {
    [CmdletBinding()]
    param()

    if ($null -eq $script:TkLoadingTimer) {

        $timer = New-Object System.Windows.Threading.DispatcherTimer
        $timer.Interval = [TimeSpan]::FromSeconds(1)
        $timer.Add_Tick({ Update-TkLoadingClock })

        $script:TkLoadingTimer = $timer
    }

    if (-not $script:TkLoadingTimer.IsEnabled) {
        $script:TkLoadingTimer.Start()
    }
}

<#
.SYNOPSIS
    Adds the elapsed seconds to the text of each card still reading.

.DESCRIPTION
    Shown from three seconds on: before that the count is noise. The original
    text is kept in the label's Tag the first time, so the count is appended
    to it rather than to the previous count.
#>
function Update-TkLoadingClock {
    [CmdletBinding()]
    param()

    if ($script:TkLoadingStarted.Count -eq 0) {

        if ($script:TkLoadingTimer) {
            $script:TkLoadingTimer.Stop()
        }

        return
    }

    foreach ($name in @($script:TkLoadingStarted.Keys)) {

        $label = Get-TkControl -Name ('{0}LoadingText' -f $name)

        if ($null -eq $label) {
            continue
        }

        if ($null -eq $label.Tag) {
            $label.Tag = $label.Text
        }

        $seconds = [int] ((Get-Date) - $script:TkLoadingStarted[$name]).TotalSeconds

        $label.Text = if ($seconds -lt 3) { [string] $label.Tag }
                      else { '{0} {1} s' -f $label.Tag, $seconds }
    }
}

<#
.SYNOPSIS
    Writes text into named controls.

.PARAMETER Field
    Control name to value. A control missing from the markup is skipped.
#>
function Set-TkFieldText {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [hashtable] $Field
    )

    foreach ($name in $Field.Keys) {

        $control = Get-TkControl -Name $name

        if ($control) {
            $control.Text = [string] $Field[$name]
        }
    }
}

<#
.SYNOPSIS
    Returns the title of an entry in a chooser list.

.DESCRIPTION
    The first text found in the entry, which in every chooser of this window
    is its title: a ListBoxItem holding a TextBlock, or a panel whose first
    TextBlock is the title.

.PARAMETER Item
    A list entry, or any element inside one.
#>
function Get-TkItemTitle {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter()]
        $Item
    )

    if ($null -eq $Item) {
        return ''
    }

    $content = if ($Item -is [System.Windows.Controls.ContentControl]) { $Item.Content } else { $Item }

    if ($content -is [string]) {
        return $content
    }

    if ($content -is [System.Windows.Controls.TextBlock]) {
        return [string] $content.Text
    }

    if ($content -is [System.Windows.DependencyObject]) {

        foreach ($child in [System.Windows.LogicalTreeHelper]::GetChildren($content)) {

            $title = Get-TkItemTitle -Item $child

            if ($title) {
                return $title
            }
        }
    }

    return ''
}

<#
.SYNOPSIS
    Selects an entry in a chooser list by its title.

.DESCRIPTION
    Matched on the title rather than the position, so a reordered list cannot
    send the battery tile to the sound test.

    The selection is cleared first. Selecting the entry that is already
    selected raises no event, and every chooser in this window acts on that
    event: without the clear, a second click on the same tile would change
    nothing.

.PARAMETER ListName
    Name of the ListBox in the markup.

.PARAMETER Title
    Title of the entry to select.

.OUTPUTS
    System.Boolean, true when the entry was found.
#>
function Select-TkListChoice {
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [Parameter(Mandatory)]
        [string] $ListName,

        [Parameter(Mandatory)]
        [string] $Title
    )

    $list = Get-TkControl -Name $ListName

    if ($null -eq $list) {
        return $false
    }

    for ($index = 0; $index -lt $list.Items.Count; $index++) {

        if ((Get-TkItemTitle -Item $list.Items[$index]) -eq $Title) {

            $list.SelectedIndex = -1
            $list.SelectedIndex = $index

            return $true
        }
    }

    return $false
}

<#
.SYNOPSIS
    Updates the status bar.

.PARAMETER Text
    Message to show.

.PARAMETER Busy
    Shows the indeterminate progress bar while an operation runs.
#>
function Set-TkStatus {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string] $Text,

        [Parameter()]
        [bool] $Busy = $false
    )

    $status = Get-TkControl -Name 'StatusText'
    $bar    = Get-TkControl -Name 'BusyBar'

    if ($status) {
        $status.Text = $Text
    }

    if ($bar) {
        # Kept up while any background work is still running, whatever this
        # particular call says. A page reading in several parts would otherwise
        # lose its busy bar the moment the first part finished.
        $bar.Visibility = if ($Busy -or $script:TkBusyCount -gt 0) { [System.Windows.Visibility]::Visible }
                          else { [System.Windows.Visibility]::Hidden }
    }
}

<#
.SYNOPSIS
    Runs work off the UI thread and re-enables the interface when it returns.

.DESCRIPTION
    The single entry point every page uses for anything slow. It sets the
    busy state, queues the work, and restores the interface from the
    completion callback, which the task pump runs on the UI thread.

.PARAMETER ScriptBlock
    Work to run in the background runspace. Receives $ArgumentList.

.PARAMETER ArgumentList
    Positional values, scalars only. WPF objects must not cross the thread
    boundary.

.PARAMETER ParameterList
    Named parameters as a hashtable. The only safe way to pass a collection:
    a positional array is flattened by PowerShell before the call is made.

.PARAMETER OnComplete
    Runs on the UI thread with the task result.

.PARAMETER StatusText
    Message shown while the work runs.
#>
function Invoke-TkBackgroundAction {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [scriptblock] $ScriptBlock,

        [Parameter()]
        [object[]] $ArgumentList = @(),

        [Parameter()]
        [hashtable] $ParameterList,

        [Parameter()]
        [scriptblock] $OnComplete,

        [Parameter()]
        [string] $StatusText = 'Working...'
    )

    Enter-TkBusy -Text $StatusText

    $wrapper = {
        param($result)

        Exit-TkBusy

        if ($OnComplete) {
            & $OnComplete $result
        }
    }.GetNewClosure()

    $taskParameters = @{
        ScriptBlock  = $ScriptBlock
        ArgumentList = $ArgumentList
        OnComplete   = $wrapper
        Name         = $StatusText
    }

    if ($ParameterList) {
        $taskParameters['ParameterList'] = $ParameterList
    }

    Start-TkTask @taskParameters | Out-Null
}

<#
.SYNOPSIS
    Writes text into one of the page output boxes.

.PARAMETER ControlName
    Name of the target TextBox.

.PARAMETER Text
    Content to write.

.PARAMETER Append
    Adds to the existing content instead of replacing it.
#>
function Set-TkOutput {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string] $ControlName,

        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string] $Text,

        [Parameter()]
        [switch] $Append
    )

    $control = Get-TkControl -Name $ControlName

    if ($null -eq $control) {
        return
    }

    if ($Append) {
        $control.AppendText($Text + [Environment]::NewLine)
        $control.ScrollToEnd()
    }
    else {
        $control.Text = $Text
    }
}

<#
.SYNOPSIS
    Renders objects as an aligned text table.

.DESCRIPTION
    Format-Table through Out-String, with a width wide enough that columns
    are not truncated the way they are at the default console width.

.OUTPUTS
    System.String
#>
function Format-TkTableText {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)]
        [AllowNull()]
        $InputObject
    )

    if ($null -eq $InputObject) {
        return '(no result)'
    }

    $items = @($InputObject)

    if ($items.Count -eq 0) {
        return '(no result)'
    }

    return ($items | Format-Table -AutoSize | Out-String -Width 400).Trim()
}

<#
.SYNOPSIS
    Copies text to the clipboard.

.OUTPUTS
    System.Boolean
#>
function Set-TkClipboard {
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string] $Text
    )

    if ([string]::IsNullOrEmpty($Text)) {
        return $false
    }

    try {
        [System.Windows.Clipboard]::SetText($Text)
        return $true
    }
    catch {
        # The clipboard can be locked by another process for a moment.
        Write-TkLog -Level Warning -Category 'UI' -Message (
            'Clipboard unavailable: {0}' -f $_.Exception.Message
        )

        return $false
    }
}

<#
.SYNOPSIS
    Shows a confirmation dialog for an operation that changes the system.

.OUTPUTS
    System.Boolean
#>
function Confirm-TkAction {
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [Parameter(Mandatory)]
        [string] $Message,

        [Parameter()]
        [string] $Title = 'Confirm'
    )

    return (Show-TkDialog -Title $Title -Message $Message -Kind 'Warning' `
                          -AcceptText 'Yes, do it' -RejectText 'Cancel')
}

<#
.SYNOPSIS
    Returns the icon character for a dialog of a given kind.

.OUTPUTS
    System.String
#>
function Get-TkDialogGlyph {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)]
        [string] $Kind
    )

    $glyphs = @{
        'Question'    = 0xE9CE  # question in a circle
        'Warning'     = 0xE7BA  # warning triangle
        'Information' = 0xE946  # information
        'Danger'      = 0xE783  # error
    }

    $point = if ($glyphs.ContainsKey($Kind)) { $glyphs[$Kind] } else { $glyphs['Information'] }

    return [string] [char] $point
}

<#
.SYNOPSIS
    Shows a modal dialog drawn in the application's own palette.

.DESCRIPTION
    Replaces the system message box. Three reasons it was worth replacing.

    It ignored the theme: a white box with black text in front of the dark
    window, every time. It could not be read from, because its text cannot be
    selected, and these dialogs list the exact tweaks or the exact adapter
    about to be changed. And its buttons said Yes and No, which say nothing
    about what is about to happen.

    Built in code rather than in MainWindow.xaml because it is a separate
    window: it borrows the main window's resource dictionary rather than
    copying it, which is what makes a theme change repaint it as well.

    Falls back to the system message box when there is no main window, so the
    function stays callable from a console session and from the tests.

.PARAMETER Title
    Shown in the title bar and as the heading.

.PARAMETER Message
    The body. Line breaks are kept, and the text can be selected and copied.

.PARAMETER Kind
    Question, Warning, Information or Danger. Sets the icon and its colour.

.PARAMETER AcceptText
    The affirmative button. Name the action rather than saying Yes.

.PARAMETER RejectText
    The dismissive button. Omitted entirely for a notice.

.PARAMETER NoticeOnly
    One button that dismisses. Always returns true.

.OUTPUTS
    System.Boolean. True when the accept button was pressed.
#>
function Show-TkDialog {
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [Parameter(Mandatory)]
        [string] $Title,

        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string] $Message,

        [Parameter()]
        [ValidateSet('Question', 'Warning', 'Information', 'Danger')]
        [string] $Kind = 'Question',

        [Parameter()]
        [string] $AcceptText = 'Continue',

        [Parameter()]
        [string] $RejectText = 'Cancel',

        [Parameter()]
        [switch] $NoticeOnly
    )

    $ctx = Get-TkContext

    if ($null -eq $ctx.Window) {

        # No window to borrow a palette from, and nothing to own the dialog.
        $buttons = if ($NoticeOnly) { [System.Windows.MessageBoxButton]::OK }
                   else { [System.Windows.MessageBoxButton]::YesNo }

        $answer = [System.Windows.MessageBox]::Show($Message, $Title, $buttons)

        return ($answer -in @([System.Windows.MessageBoxResult]::Yes,
                              [System.Windows.MessageBoxResult]::OK))
    }

    $accepted = $false

    # --- Shell -----------------------------------------------------------
    $window = New-Object System.Windows.Window

    $window.Title  = $Title
    $window.Width  = 560
    $window.Owner  = $ctx.Window
    $window.SizeToContent         = [System.Windows.SizeToContent]::Height
    $window.ResizeMode            = [System.Windows.ResizeMode]::NoResize
    $window.WindowStartupLocation = [System.Windows.WindowStartupLocation]::CenterOwner
    $window.ShowInTaskbar         = $false

    # The same dictionary instance, so a theme change reaches this too.
    $window.Resources = $ctx.Window.Resources
    $window.SetResourceReference([System.Windows.Window]::BackgroundProperty, 'AppBackground')

    $layout = New-Object System.Windows.Controls.Grid
    $layout.Margin = New-Object System.Windows.Thickness(22, 20, 22, 18)

    foreach ($height in @('Auto', 'Auto')) {

        $row = New-Object System.Windows.Controls.RowDefinition
        $row.Height = [System.Windows.GridLength]::Auto

        $layout.RowDefinitions.Add($row)
    }

    # --- Icon and text ----------------------------------------------------
    $body = New-Object System.Windows.Controls.Grid

    foreach ($width in @('Auto', 'Star')) {

        $column = New-Object System.Windows.Controls.ColumnDefinition

        $column.Width = if ($width -eq 'Auto') { [System.Windows.GridLength]::Auto }
                        else { [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star) }

        $body.ColumnDefinitions.Add($column)
    }

    $icon = New-Object System.Windows.Controls.TextBlock
    $icon.Text              = Get-TkDialogGlyph -Kind $Kind
    $icon.FontSize          = 26
    $icon.Margin            = New-Object System.Windows.Thickness(0, 1, 16, 0)
    $icon.VerticalAlignment = [System.Windows.VerticalAlignment]::Top

    $icon.SetResourceReference([System.Windows.Controls.TextBlock]::FontFamilyProperty, 'IconFont')

    $iconKey = switch ($Kind) {
        'Warning'     { 'Warning' }
        'Danger'      { 'Danger' }
        'Question'    { 'Accent' }
        default       { 'Accent' }
    }

    $icon.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, $iconKey)

    [System.Windows.Controls.Grid]::SetColumn($icon, 0)
    [void] $body.Children.Add($icon)

    $stack = New-Object System.Windows.Controls.StackPanel
    [System.Windows.Controls.Grid]::SetColumn($stack, 1)

    $heading = New-Object System.Windows.Controls.TextBlock
    $heading.Text         = $Title
    $heading.FontSize     = 15
    $heading.FontWeight   = [System.Windows.FontWeights]::SemiBold
    $heading.TextWrapping = [System.Windows.TextWrapping]::Wrap
    $heading.Margin       = New-Object System.Windows.Thickness(0, 0, 0, 8)

    $heading.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, 'TextPrimary')

    [void] $stack.Children.Add($heading)

    # Selectable, because these dialogs list the exact names about to change
    # and an operator writing a change record has to be able to copy them.
    $text = New-TkSelectableText -Value $Message
    $text.FontSize       = 13
    $text.AcceptsReturn  = $true
    $text.MaxHeight      = 320
    $text.VerticalScrollBarVisibility = [System.Windows.Controls.ScrollBarVisibility]::Auto

    [void] $stack.Children.Add($text)
    [void] $body.Children.Add($stack)

    [System.Windows.Controls.Grid]::SetRow($body, 0)
    [void] $layout.Children.Add($body)

    # --- Buttons ----------------------------------------------------------
    $bar = New-Object System.Windows.Controls.StackPanel
    $bar.Orientation         = [System.Windows.Controls.Orientation]::Horizontal
    $bar.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Right
    $bar.Margin              = New-Object System.Windows.Thickness(0, 20, 0, 0)

    if (-not $NoticeOnly) {

        $reject = New-Object System.Windows.Controls.Button
        $reject.Content   = $RejectText
        $reject.MinWidth  = 104
        $reject.IsCancel  = $true
        $reject.Margin    = New-Object System.Windows.Thickness(0, 0, 10, 0)

        $reject.Add_Click({
            param($clicked, $clickArgs)
            $clicked.Tag.DialogResult = $false
        })

        $reject.Tag = $window

        [void] $bar.Children.Add($reject)
    }

    $accept = New-Object System.Windows.Controls.Button
    $accept.Content   = if ($NoticeOnly) { 'Close' } else { $AcceptText }
    $accept.MinWidth  = 104
    $accept.IsDefault = $true
    $accept.Margin    = New-Object System.Windows.Thickness(0)
    $accept.Tag       = $window

    $accept.SetResourceReference([System.Windows.Controls.Button]::StyleProperty, 'PrimaryButton')

    $accept.Add_Click({
        param($clicked, $clickArgs)
        $clicked.Tag.DialogResult = $true
    })

    [void] $bar.Children.Add($accept)

    [System.Windows.Controls.Grid]::SetRow($bar, 1)
    [void] $layout.Children.Add($bar)

    $window.Content = $layout

    # Focus the safe choice: Enter on a confirmation should not be the way a
    # destructive action gets run by someone who was typing.
    $window.Add_ContentRendered({
        param($shown, $renderArgs)
        $shown.MoveFocus((New-Object System.Windows.Input.TraversalRequest(
            [System.Windows.Input.FocusNavigationDirection]::First))) | Out-Null
    })

    $result = $window.ShowDialog()

    $accepted = ($result -eq $true)

    Write-TkLog -Level Debug -Category 'UI' -Message (
        'Dialog "{0}" answered {1}.' -f $Title, $(if ($accepted) { 'yes' } else { 'no' })
    )

    return $accepted
}

<#
.SYNOPSIS
    Shows a set of objects as a table in a window of its own.

.DESCRIPTION
    For answers that are a list rather than a value: the listening sockets,
    the routing table, the forwarding rules. Three things were wrong with
    where those used to go.

    Writing them to the console at the foot of the window hides them, because
    the console is collapsed by default. Writing them into another tab's
    output box moves the operator away from what they were doing, which is
    what the listening ports button did: it jumped to Diagnostics and left
    Adapters behind. And neither can be kept open beside the thing it
    explains.

    A window can. It is modeless on purpose, so several can be compared side
    by side, and it borrows the main window's resource dictionary rather than
    copying it, which is what makes a theme change repaint it too.

.PARAMETER Title
    Window title and heading.

.PARAMETER InputObject
    Rows. Any object with properties.

.PARAMETER Column
    Property names to show, in order. Taken from the first row when omitted.

.PARAMETER Description
    One line under the heading explaining what is being shown.

.PARAMETER EmptyText
    Shown instead of the table when there is nothing to list.
#>
function Show-TkTableWindow {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string] $Title,

        [Parameter(Mandatory)]
        [AllowNull()]
        [AllowEmptyCollection()]
        $InputObject,

        [Parameter()]
        [string[]] $Column = @(),

        [Parameter()]
        [AllowEmptyString()]
        [string] $Description = '',

        [Parameter()]
        [string] $EmptyText = 'Nothing to show.'
    )

    $ctx = Get-TkContext

    if ($null -eq $ctx.Window) {
        return
    }

    $rows = ConvertTo-TkArray $InputObject

    # Take the shape from the data when the caller did not state it.
    if ($Column.Count -eq 0 -and $rows.Count -gt 0) {

        $Column = @(
            $rows[0].PSObject.Properties |
            Where-Object { $_.MemberType -eq 'NoteProperty' -or $_.MemberType -eq 'Property' } |
            Select-Object -ExpandProperty Name
        )
    }

    $document = New-TkFlowDocument

    Add-TkHeading -Document $document -Text $Title -Level 1

    if ($Description) {
        Add-TkParagraph -Document $document -Text $Description -Muted
    }

    if ($rows.Count -eq 0 -or $Column.Count -eq 0) {
        Add-TkParagraph -Document $document -Text $EmptyText -Muted
    }
    else {
        Add-TkTable -Document $document -Column $Column -Row (ConvertTo-TkTableRow $rows $Column)
    }

    $viewer = New-Object System.Windows.Controls.RichTextBox
    $viewer.Document        = $document
    $viewer.IsReadOnly      = $true
    $viewer.BorderThickness = New-Object System.Windows.Thickness(0)
    $viewer.Padding         = New-Object System.Windows.Thickness(18, 14, 18, 14)
    $viewer.VerticalScrollBarVisibility   = [System.Windows.Controls.ScrollBarVisibility]::Auto
    $viewer.HorizontalScrollBarVisibility = [System.Windows.Controls.ScrollBarVisibility]::Disabled

    $viewer.SetResourceReference([System.Windows.Controls.RichTextBox]::BackgroundProperty, 'AppBackground')
    $viewer.SetResourceReference([System.Windows.Controls.RichTextBox]::ForegroundProperty, 'TextPrimary')
    $viewer.SetResourceReference([System.Windows.Controls.Primitives.TextBoxBase]::SelectionBrushProperty, 'Accent')

    $window = New-Object System.Windows.Window

    $window.Title  = '{0} - {1}' -f $ctx.AppName, $Title
    $window.Width  = 940
    $window.Height = 620
    $window.Owner  = $ctx.Window
    $window.WindowStartupLocation = [System.Windows.WindowStartupLocation]::CenterOwner
    $window.Content = $viewer

    # The same dictionary instance, not a copy: Set-TkTheme replaces the brush
    # objects inside it, so sharing it is what makes this window follow.
    $window.Resources = $ctx.Window.Resources

    $window.SetResourceReference([System.Windows.Window]::BackgroundProperty, 'AppBackground')

    # Modeless, so two of these can be compared and the main window stays
    # usable behind them.
    $window.Show()

    Write-TkLog -Level Debug -Category 'Interface' -Message (
        'Opened the "{0}" table window with {1} row(s).' -f $Title, $rows.Count
    )
}

<#
.SYNOPSIS
    Wires the shell: header, navigation and window lifetime.
#>
function Initialize-TkShell {
    [CmdletBinding()]
    param()

    $ctx = Get-TkContext

    # --- Header -----------------------------------------------------------
    $version = Get-TkControl -Name 'HeaderVersion'

    if ($version) {
        $version.Text = 'v{0} ({1})' -f $ctx.Version, $ctx.Commit
    }

    $hostLabel = Get-TkControl -Name 'HeaderHost'

    if ($hostLabel) {
        $hostLabel.Text = '{0} - {1} - PowerShell {2}' -f $env:COMPUTERNAME, $ctx.OSCaption, $ctx.PSVersion
    }

    Initialize-TkThemeSelector
    Update-TkElevationBadge
    Initialize-TkSearch

    # --- Navigation -------------------------------------------------------
    foreach ($page in @(Get-TkPageName)) {

        $name = 'Nav{0}' -f $page

        # Capture the page name in a closure; without GetNewClosure every
        # handler would see the last value of the loop variable.
        $handler = {
            Show-TkPage -Name $page
        }.GetNewClosure()

        Register-TkClick -Name $name -Action $handler
    }

    # --- Shell buttons ----------------------------------------------------
    Register-TkClick -Name 'BtnElevate' -Action {

        if (Test-TkIsElevated) {
            Set-TkStatus -Text 'Already running as administrator.'
            return
        }

        $context = Get-TkContext

        if (Invoke-TkElevation -SourceUri $context.SourceUri -Confirm:$false) {
            $context.Window.Close()
        }
    }

    Register-TkClick -Name 'BtnOpenLogs' -Action {
        Start-Process -FilePath 'explorer.exe' -ArgumentList (Get-TkContext).LogRoot
    }

    Register-TkClick -Name 'BtnAbout' -Action {

        $ctx = Get-TkContext

        $message = @(
            '{0} {1} ({2})' -f $ctx.AppName, $ctx.Version, $ctx.Commit,
            '',
            'A toolkit for daily system, network and security work on Windows.',
            '',
            'Repository: {0}' -f $ctx.Repository,
            'Data folder: {0}' -f $ctx.DataRoot,
            '',
            'Read only features work as a standard user. Anything that changes',
            'the machine requires an elevated instance and is written to the log.'
        ) -join [Environment]::NewLine

        Show-TkDialog -Title 'About' -Message $message -Kind 'Information' -NoticeOnly | Out-Null
    }

    # --- Window lifetime --------------------------------------------------
    $ctx.Window.Add_Closing({

        Write-TkLog -Level Information -Category 'UI' -Message 'Closing.'

        Save-TkSettings -Confirm:$false
        Stop-TkThreading
    })
}

<#
.SYNOPSIS
    Disables the controls whose action cannot work without administrator
    rights, and says why.

.DESCRIPTION
    A button that looks available and then reports a refusal is worse than one
    that is plainly unavailable. Everything named here is disabled when the
    instance is not elevated, with the reason in its tooltip and the way out
    named: the restart button sits in the header.

    Only actions that strictly need elevation are listed. Applying tweaks is
    not, because several of them write to the current user hive and work
    perfectly well without it.
#>
function Update-TkPrivilegedControls {
    [CmdletBinding()]
    param()

    $elevated = Test-TkIsElevated

    # Software installation is deliberately absent from this list.
    #
    # winget is designed to run as the signed in user: Windows prompts for
    # rights per installer that needs them, and a package that installs into
    # the user profile needs none at all. Running winget from an elevated
    # toolkit is worse, not better. It suppresses those prompts, and when the
    # elevation used a different administrator account winget reads its
    # sources from that other profile, finds none, and reports every package
    # as not found. That is what "nothing installs at all" turned out to be.
    $controls = @{
        'BtnVendorTool'        = 'Installing the vendor firmware utility'
        'BtnRestorePoint'      = 'Creating a system restore point'
        'BtnAutoLogon'         = 'Configuring automatic logon'
        'BtnApplyProfile'      = 'Changing an adapter configuration'
        'BtnAddRoute'          = 'Adding a persistent route'
        'BtnRemoveRoute'       = 'Removing a route'
        'BtnAddProxy'          = 'Publishing a port'
        'BtnRemoveProxy'       = 'Removing a port proxy rule'
        'BtnSwitchPort'        = 'Listening for the switch announcement with Packet Monitor'
    }

    foreach ($name in $controls.Keys) {

        $control = Get-TkControl -Name $name

        if ($null -eq $control) {
            continue
        }

        $control.IsEnabled = $elevated

        $control.ToolTip = if ($elevated) { $controls[$name] }
                           else {
                               '{0} needs administrator rights. Use "Restart as administrator" at the top right.' -f $controls[$name]
                           }
    }

    Write-TkLog -Level Debug -Category 'UI' -Message (
        'Privileged controls {0}.' -f $(if ($elevated) { 'enabled' } else { 'disabled' })
    )
}

<#
.SYNOPSIS
    Updates the elevation badge in the header.

.DESCRIPTION
    The badge is the honest answer to "why is that button doing nothing":
    privileged features are disabled, not hidden, and the badge says why.
#>
function Update-TkElevationBadge {
    [CmdletBinding()]
    param()

    $ctx    = Get-TkContext
    $badge  = Get-TkControl -Name 'ElevationBadge'
    $text   = Get-TkControl -Name 'ElevationText'
    $button = Get-TkControl -Name 'BtnElevate'

    if (-not $text) {
        return
    }

    if ($ctx.IsElevated) {

        $text.Text = 'Administrator'

        if ($badge) {
            $badge.BorderBrush = $ctx.Window.Resources['Success']
        }

        if ($button) {
            $button.Visibility = [System.Windows.Visibility]::Collapsed
        }
    }
    else {
        $text.Text = 'Standard user - system changes disabled'

        if ($badge) {
            $badge.BorderBrush = $ctx.Window.Resources['Warning']
        }
    }
}


# ==========================================================================
# Source: src/UI/RichText.ps1
# ==========================================================================

<#
    Toolkit - UI / Rich text rendering

    Builds FlowDocuments for the knowledge base and the vendor command
    reference.

    Why not a text box. The reference content is structured: headings, prose,
    bullet lists and, for things like the port list, genuine tables. Flattened
    into one monospaced block it becomes unreadable exactly where it matters
    most, which is when you are looking for one row among fifty. A
    FlowDocument renders each of those as what it is, and it is also the only
    control here that can highlight a search term inside the text.

    Every colour is read from the window resources at build time, so a
    document follows the current theme. A document is rebuilt on a theme
    change rather than repainted, which is why Set-TkTheme re-renders the
    selected topic.
#>

<#
.SYNOPSIS
    Returns a theme brush by resource key.

.DESCRIPTION
    Falls back to a readable grey when the window is not up, so the rendering
    functions stay callable from a console session and from the tests.

.OUTPUTS
    System.Windows.Media.Brush
#>
function Get-TkBrush {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string] $Key
    )

    $ctx = Get-TkContext

    if ($ctx.Window -and $ctx.Window.Resources[$Key]) {
        return $ctx.Window.Resources[$Key]
    }

    return [System.Windows.Media.Brushes]::Gray
}

<#
.SYNOPSIS
    Creates an empty document styled for the current theme.

.OUTPUTS
    System.Windows.Documents.FlowDocument
#>
function New-TkFlowDocument {
    [CmdletBinding()]
    [OutputType([System.Windows.Documents.FlowDocument])]
    param()

    $document = New-Object System.Windows.Documents.FlowDocument

    $document.FontFamily      = New-Object System.Windows.Media.FontFamily('Segoe UI')
    $document.FontSize        = 13
    $document.SetResourceReference([System.Windows.Documents.FlowDocument]::ForegroundProperty, 'TextPrimary')
    $document.Background      = [System.Windows.Media.Brushes]::Transparent
    $document.PagePadding     = New-Object System.Windows.Thickness(4)
    $document.TextAlignment   = [System.Windows.TextAlignment]::Left

    return $document
}

<#
.SYNOPSIS
    Builds the inline runs for a piece of text, highlighting a search term.

.DESCRIPTION
    Splits the text on every case insensitive occurrence of the term and
    returns alternating plain and highlighted runs. With no term, a single
    run. This is what makes a search result readable: finding the topic is
    only half of it, you still have to find the line.

.PARAMETER Text
    Text to render.

.PARAMETER Highlight
    Term to mark, or empty for none.

.OUTPUTS
    System.Windows.Documents.Run[]
#>
function New-TkTextRuns {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string] $Text,

        [Parameter()]
        [AllowEmptyString()]
        [string] $Highlight = ''
    )

    if ([string]::IsNullOrWhiteSpace($Highlight) -or [string]::IsNullOrEmpty($Text)) {
        return @((New-Object System.Windows.Documents.Run($Text)))
    }

    $runs     = @()
    $position = 0

    while ($true) {

        $found = $Text.IndexOf($Highlight, $position, [System.StringComparison]::OrdinalIgnoreCase)

        if ($found -lt 0) {
            break
        }

        if ($found -gt $position) {
            $runs += New-Object System.Windows.Documents.Run($Text.Substring($position, $found - $position))
        }

        $match = New-Object System.Windows.Documents.Run($Text.Substring($found, $Highlight.Length))
        $match.Background = Get-TkBrush -Key 'Warning'
        $match.Foreground = [System.Windows.Media.Brushes]::Black
        $match.FontWeight = [System.Windows.FontWeights]::SemiBold

        $runs += $match

        $position = $found + $Highlight.Length
    }

    if ($position -lt $Text.Length) {
        $runs += New-Object System.Windows.Documents.Run($Text.Substring($position))
    }

    return $runs
}

<#
.SYNOPSIS
    Appends a heading to a document.

.PARAMETER Level
    1 for the topic title, 2 for a section.
#>
function Add-TkHeading {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [System.Windows.Documents.FlowDocument] $Document,

        [Parameter(Mandatory)]
        [string] $Text,

        [Parameter()]
        [ValidateRange(1, 3)]
        [int] $Level = 2,

        [Parameter()]
        [AllowEmptyString()]
        [string] $Highlight = ''
    )

    $paragraph = New-Object System.Windows.Documents.Paragraph

    $paragraph.FontSize   = @(20, 15, 13)[$Level - 1]
    $paragraph.FontWeight = [System.Windows.FontWeights]::SemiBold
    $paragraph.Foreground = Get-TkBrush -Key $(if ($Level -eq 1) { 'TextPrimary' } else { 'Accent' })
    $paragraph.Margin     = New-Object System.Windows.Thickness(0, $(if ($Level -eq 1) { 0 } else { 18 }), 0, 6)

    foreach ($run in (New-TkTextRuns -Text $Text -Highlight $Highlight)) {
        $paragraph.Inlines.Add($run)
    }

    $Document.Blocks.Add($paragraph)
}

<#
.SYNOPSIS
    Appends a paragraph of prose to a document.
#>
function Add-TkParagraph {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [System.Windows.Documents.FlowDocument] $Document,

        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string] $Text,

        [Parameter()]
        [AllowEmptyString()]
        [string] $Highlight = '',

        [Parameter()]
        [switch] $Muted
    )

    if ([string]::IsNullOrWhiteSpace($Text)) {
        return
    }

    $paragraph = New-Object System.Windows.Documents.Paragraph
    $paragraph.Margin     = New-Object System.Windows.Thickness(0, 0, 0, 10)
    $paragraph.LineHeight = 19

    if ($Muted) {
        $paragraph.Foreground = Get-TkBrush -Key 'TextMuted'
        $paragraph.FontSize   = 12
    }

    foreach ($run in (New-TkTextRuns -Text $Text -Highlight $Highlight)) {
        $paragraph.Inlines.Add($run)
    }

    $Document.Blocks.Add($paragraph)
}

<#
.SYNOPSIS
    Appends a bullet list to a document.
#>
function Add-TkBulletList {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [System.Windows.Documents.FlowDocument] $Document,

        [Parameter(Mandatory)]
        [AllowEmptyCollection()]
        [string[]] $Item,

        [Parameter()]
        [AllowEmptyString()]
        [string] $Highlight = ''
    )

    if ($Item.Count -eq 0) {
        return
    }

    $list = New-Object System.Windows.Documents.List
    $list.MarkerStyle = [System.Windows.TextMarkerStyle]::Disc
    $list.Margin      = New-Object System.Windows.Thickness(18, 0, 0, 10)
    $list.Padding     = New-Object System.Windows.Thickness(0)

    foreach ($text in $Item) {

        $paragraph = New-Object System.Windows.Documents.Paragraph
        $paragraph.Margin     = New-Object System.Windows.Thickness(0, 0, 0, 5)
        $paragraph.LineHeight = 19

        foreach ($run in (New-TkTextRuns -Text $text -Highlight $Highlight)) {
            $paragraph.Inlines.Add($run)
        }

        $listItem = New-Object System.Windows.Documents.ListItem($paragraph)
        $list.ListItems.Add($listItem)
    }

    $Document.Blocks.Add($list)
}

<#
.SYNOPSIS
    Appends a table to a document, with proportional and resizable columns.

.DESCRIPTION
    Built as a Grid hosted in a BlockUIContainer rather than as a FlowDocument
    Table, because the FlowDocument Table accepts star widths and then ignores
    them. A Grid honours star sizing, wraps its cell text instead of
    truncating it, and takes a GridSplitter between columns.

    Two decisions worth knowing about.

    Colours are attached with SetResourceReference rather than assigned. An
    assigned brush is a snapshot: the table kept the palette it was built with
    and stayed unreadable after a theme change until the page was rebuilt.
    A resource reference is the code equivalent of DynamicResource and follows
    the swap.

    Cells are read only TextBoxes rather than TextBlocks, because a TextBlock
    cannot be selected and a table nobody can copy out of is half a table.
    The cost is that a search term cannot be marked inside the text, so a
    matching cell is tinted whole instead.

.PARAMETER Column
    Column headings.

.PARAMETER Row
    Rows, each an array of cell values matching the columns. Build them with
    the comma operator inside a pipeline, otherwise PowerShell flattens the
    inner arrays and every row arrives with one cell.

.PARAMETER Weight
    Relative column widths. Defaults to a narrow first column for the key
    being looked up and progressively wider ones after it.

.PARAMETER Highlight
    Search term. A cell containing it is tinted.

.EXAMPLE
    Add-TkTable -Document $document -Column @('Port', 'Service') -Row @(
        , @('443', 'HTTPS')
        , @('22',  'SSH')
    )
#>
function Add-TkTable {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [System.Windows.Documents.FlowDocument] $Document,

        [Parameter(Mandatory)]
        [string[]] $Column,

        [Parameter(Mandatory)]
        [AllowEmptyCollection()]
        [object[]] $Row,

        [Parameter()]
        [double[]] $Weight = @(),

        [Parameter()]
        [AllowEmptyString()]
        [string] $Highlight = ''
    )

    if ($Column.Count -eq 0) {
        return
    }

    $grid = New-Object System.Windows.Controls.Grid
    $grid.Margin = New-Object System.Windows.Thickness(0, 2, 0, 16)
    $grid.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Stretch

    # --- Column widths ----------------------------------------------------
    for ($i = 0; $i -lt $Column.Count; $i++) {

        # Not named $weight: PowerShell variable names are case insensitive,
        # so that would assign to the $Weight parameter itself.
        $columnWeight = if ($i -lt $Weight.Count) { $Weight[$i] }
                        elseif ($i -eq 0) { 0.8 }
                        elseif ($i -eq ($Column.Count - 1)) { 2.6 }
                        else { 1.4 }

        $definition = New-Object System.Windows.Controls.ColumnDefinition
        $definition.Width    = [System.Windows.GridLength]::new([double] $columnWeight, [System.Windows.GridUnitType]::Star)
        $definition.MinWidth = 48

        $grid.ColumnDefinitions.Add($definition)
    }

    $grid.RowDefinitions.Add((New-TkAutoRow))

    foreach ($ignored in $Row) {
        $grid.RowDefinitions.Add((New-TkAutoRow))
    }

    # --- Header cells -----------------------------------------------------
    for ($i = 0; $i -lt $Column.Count; $i++) {

        $text = New-Object System.Windows.Controls.TextBlock
        $text.Text         = $Column[$i]
        $text.FontSize     = 12
        $text.FontWeight   = [System.Windows.FontWeights]::SemiBold
        $text.TextWrapping = [System.Windows.TextWrapping]::Wrap

        $text.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, 'TextMuted')

        $cell = New-Object System.Windows.Controls.Border
        $cell.BorderThickness = New-Object System.Windows.Thickness(0, 0, 1, 1)
        $cell.Padding         = New-Object System.Windows.Thickness(8, 6, 8, 6)
        $cell.Child           = $text

        $cell.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, 'SurfaceRaised')
        $cell.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, 'BorderSubtle')

        [System.Windows.Controls.Grid]::SetColumn($cell, $i)
        [System.Windows.Controls.Grid]::SetRow($cell, 0)

        [void] $grid.Children.Add($cell)
    }

    # --- Body cells -------------------------------------------------------
    $rowIndex = 1

    foreach ($values in $Row) {

        $cells = @($values)

        for ($i = 0; $i -lt $Column.Count; $i++) {

            $value = if ($i -lt $cells.Count) { [string] $cells[$i] } else { '' }

            $text = New-TkSelectableText -Value $value

            $text.FontSize = 12.5

            # The lookup key is monospaced so a column of ports lines up.
            if ($i -eq 0) {
                $text.FontFamily = New-Object System.Windows.Media.FontFamily('Cascadia Mono, Consolas')
                $text.FontWeight = [System.Windows.FontWeights]::SemiBold
            }

            $cell = New-Object System.Windows.Controls.Border
            $cell.BorderThickness = New-Object System.Windows.Thickness(0, 0, 1, 1)
            $cell.Padding         = New-Object System.Windows.Thickness(6, 4, 6, 4)
            $cell.Child           = $text

            $cell.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, 'BorderSubtle')

            # Every other row carries a faint tint. Reading along a wide row
            # without one means losing the line halfway across, which is the
            # whole reason a table is hard to scan. RowAlternate is a palette
            # key, so the banding is calculated for each theme rather than
            # being a transparency that only works on one of them.
            if ($rowIndex % 2 -eq 0) {
                $cell.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, 'RowAlternate')
            }

            # A matching cell is tinted whole, over the banding. Marking the
            # term inside the text would mean giving up selection, which
            # matters more.
            if ($Highlight -and $value -and
                $value.IndexOf($Highlight, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {

                $cell.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, 'Selection')
            }

            [System.Windows.Controls.Grid]::SetColumn($cell, $i)
            [System.Windows.Controls.Grid]::SetRow($cell, $rowIndex)

            [void] $grid.Children.Add($cell)
        }

        $rowIndex++
    }

    # --- Resize handles ---------------------------------------------------
    # One splitter per boundary, spanning every row, so a column can be
    # widened by dragging its right edge when a value needs the room.
    for ($i = 0; $i -lt ($Column.Count - 1); $i++) {

        $splitter = New-Object System.Windows.Controls.GridSplitter
        $splitter.Width               = 6
        $splitter.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Right
        $splitter.VerticalAlignment   = [System.Windows.VerticalAlignment]::Stretch
        $splitter.Background          = [System.Windows.Media.Brushes]::Transparent
        $splitter.Cursor              = [System.Windows.Input.Cursors]::SizeWE
        $splitter.ResizeBehavior      = [System.Windows.Controls.GridResizeBehavior]::CurrentAndNext
        $splitter.ToolTip             = 'Drag to widen this column'

        [System.Windows.Controls.Grid]::SetColumn($splitter, $i)
        [System.Windows.Controls.Grid]::SetRow($splitter, 0)
        [System.Windows.Controls.Grid]::SetRowSpan($splitter, $grid.RowDefinitions.Count)

        [void] $grid.Children.Add($splitter)
    }

    $container = New-Object System.Windows.Documents.BlockUIContainer($grid)
    $container.Margin = New-Object System.Windows.Thickness(0)

    $Document.Blocks.Add($container)
}

<#
.SYNOPSIS
    Turns objects into the row array Add-TkTable expects.

.DESCRIPTION
    Reads the named properties from each object in order. Exists because the
    comma operator is required here and is easy to leave out: without it
    PowerShell flattens each row into the outer array and every row arrives
    holding a single cell, which renders as a column of stripes rather than a
    table. Doing it in one place means getting it right in one place.

.PARAMETER InputObject
    The objects to read.

.PARAMETER Property
    Property names, in column order.

.OUTPUTS
    System.Object[] of string arrays.
#>
function ConvertTo-TkTableRow {
    [CmdletBinding()]
    [OutputType([object[]])]
    param(
        [Parameter(Mandatory, Position = 0)]
        [AllowNull()]
        [AllowEmptyCollection()]
        $InputObject,

        [Parameter(Mandatory, Position = 1)]
        [string[]] $Property
    )

    $rows = @()

    foreach ($item in (ConvertTo-TkArray $InputObject)) {

        $cells = @()

        foreach ($name in $Property) {
            $cells += [string] $item.$name
        }

        $rows += , $cells
    }

    return , $rows
}

<#
.SYNOPSIS
    Renders objects as a table into a rich text control.

.DESCRIPTION
    The one call a page makes to show a list of things. Everything the tables
    are expected to do now lives behind it: selectable cells, banded rows,
    draggable column edges and a palette that follows a theme change.

.PARAMETER ControlName
    Name of the RichTextBox to fill.

.PARAMETER InputObject
    The objects to show.

.PARAMETER Property
    Property names, in column order.

.PARAMETER Column
    Headings. Defaults to the property names.

.PARAMETER Weight
    Relative column widths.

.PARAMETER Title
    Optional heading above the table.

.PARAMETER EmptyText
    Shown instead of the table when there is nothing to list. A table with a
    header and no rows looks like a failure; a sentence saying there is
    nothing does not.
#>
function Set-TkObjectTable {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string] $ControlName,

        [Parameter(Mandatory)]
        [AllowNull()]
        [AllowEmptyCollection()]
        $InputObject,

        [Parameter(Mandatory)]
        [string[]] $Property,

        [Parameter()]
        [string[]] $Column = @(),

        [Parameter()]
        [double[]] $Weight = @(),

        [Parameter()]
        [AllowEmptyString()]
        [string] $Title = '',

        [Parameter()]
        [string] $EmptyText = 'Nothing to show.'
    )

    $items    = ConvertTo-TkArray $InputObject
    $document = New-TkFlowDocument

    if ($Title) {
        Add-TkHeading -Document $document -Text $Title -Level 2
    }

    if ($items.Count -eq 0) {
        Add-TkParagraph -Document $document -Text $EmptyText -Muted
    }
    else {

        $headings = if ($Column.Count -gt 0) { $Column } else { $Property }

        Add-TkTable -Document $document `
            -Column $headings `
            -Row (ConvertTo-TkTableRow $items $Property) `
            -Weight $Weight
    }

    Set-TkDocument -ControlName $ControlName -Document $document
}

<#
.SYNOPSIS
    Returns a Grid row definition sized to its content.

.OUTPUTS
    System.Windows.Controls.RowDefinition
#>
function New-TkAutoRow {
    [CmdletBinding()]
    [OutputType([System.Windows.Controls.RowDefinition])]
    param()

    $definition = New-Object System.Windows.Controls.RowDefinition
    $definition.Height = [System.Windows.GridLength]::Auto

    return $definition
}

<#
.SYNOPSIS
    Builds a read only text control whose content can be selected and copied.

.DESCRIPTION
    A TextBlock cannot be selected on .NET Framework, and a report nobody can
    copy a path or a thumbprint out of is half a report. A read only TextBox
    with no chrome looks identical and behaves the way people expect.

    The chrome is removed by applying the SelectableText style, which carries
    a template of its own. Clearing Template instead removes the control's
    entire visual tree: a TextBox with no template has nowhere to render its
    text and draws nothing at all. That is what emptied every table and every
    finding card, and it is worth stating plainly because the control still
    reports a correct size while showing nothing.

    The style is attached by resource reference rather than looked up once,
    so the control follows a theme change instead of keeping the palette it
    was created with. A caller may still override any single property
    afterwards: a local value beats a style setter.

.OUTPUTS
    System.Windows.Controls.TextBox
#>
function New-TkSelectableText {
    [CmdletBinding()]
    [OutputType([System.Windows.Controls.TextBox])]
    param(
        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string] $Value
    )

    $text = New-Object System.Windows.Controls.TextBox

    $text.Text = $Value

    # Set here rather than left to the style, because a resource reference is
    # resolved only when the control joins a tree that carries the resource.
    # Until then the control has no style at all, and anything reading it in
    # between, a test or a console session, would see a plain text box.
    $text.IsReadOnly      = $true
    $text.BorderThickness = New-Object System.Windows.Thickness(0)
    $text.Background      = [System.Windows.Media.Brushes]::Transparent
    $text.Padding         = New-Object System.Windows.Thickness(0)
    $text.TextWrapping    = [System.Windows.TextWrapping]::Wrap
    $text.IsTabStop       = $false

    # The template and the theme colours come from the style. A reference
    # rather than a one time lookup, so the control follows a theme change.
    $text.SetResourceReference([System.Windows.Controls.TextBox]::StyleProperty, 'SelectableText')

    return $text
}

<#
.SYNOPSIS
    Appends a monospaced command block to a document.

.DESCRIPTION
    Used by the vendor reference, where the command has to be copied exactly
    and a proportional font hides trailing spaces and pipe characters.
#>
function Add-TkCodeBlock {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [System.Windows.Documents.FlowDocument] $Document,

        [Parameter(Mandatory)]
        [string] $Text,

        [Parameter()]
        [AllowEmptyString()]
        [string] $Highlight = ''
    )

    $paragraph = New-Object System.Windows.Documents.Paragraph

    $paragraph.FontFamily      = New-Object System.Windows.Media.FontFamily('Cascadia Mono, Consolas, Courier New')
    $paragraph.FontSize        = 12.5
    $paragraph.Background      = Get-TkBrush -Key 'InputBackground'
    $paragraph.Padding         = New-Object System.Windows.Thickness(10, 8, 10, 8)
    $paragraph.Margin          = New-Object System.Windows.Thickness(0, 0, 0, 4)
    $paragraph.BorderBrush     = Get-TkBrush -Key 'BorderSubtle'
    $paragraph.BorderThickness = New-Object System.Windows.Thickness(1)
    $paragraph.LineHeight      = 17

    foreach ($run in (New-TkTextRuns -Text $Text -Highlight $Highlight)) {
        $paragraph.Inlines.Add($run)
    }

    $Document.Blocks.Add($paragraph)
}

<#
.SYNOPSIS
    Returns the resource key a severity should be drawn in.

.DESCRIPTION
    Lives here rather than on a page, because the cards, the chips and every
    report renderer share it.

.OUTPUTS
    System.String
#>
function Get-TkSeverityBrushKey {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string] $Severity
    )

    switch ($Severity) {
        'Fail'    { return 'Danger' }
        'Warning' { return 'Warning' }
        'Pass'    { return 'Success' }
        default   { return 'TextMuted' }
    }
}

<#
.SYNOPSIS
    Returns the icon character for a severity.

.DESCRIPTION
    Colour alone carries a result badly. Roughly one man in twelve cannot
    separate the red from the green, the two that matter most here, and a
    printed or screenshotted report loses the distinction for everyone. The
    shape says the same thing a second way.

    Characters from Segoe Fluent Icons, which the IconFont resource already
    falls back correctly for on Windows 10.

.OUTPUTS
    String, one character.
#>
function Get-TkSeverityGlyph {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string] $Severity
    )

    $code = switch ($Severity) {
        'Fail'        { 0xEA39 }   # ErrorBadge
        'Warning'     { 0xE7BA }   # Warning
        'Pass'        { 0xE930 }   # Completed
        'Info'        { 0xE946 }   # Info
        'NotAssessed' { 0xE9CE }   # Unknown
        default       { 0xE946 }
    }

    return [string][char] $code
}

<#
.SYNOPSIS
    Returns a faint fill in the severity colour, for a whole card.

.DESCRIPTION
    Built from the palette's own colour at low alpha rather than from a fixed
    pair of light and dark tints, so it stays right through a theme change and
    there is still only one place where Danger is defined.

    A new brush every time: tinting the palette's shared brush would repaint
    every surface in the window.

.OUTPUTS
    System.Windows.Media.SolidColorBrush, or null when there is no window.
#>
function Get-TkSeverityTintBrush {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string] $Severity,

        [Parameter()]
        [byte] $Alpha = 38
    )

    $ctx = Get-TkContext

    if ($null -eq $ctx.Window) {
        return $null
    }

    $source = $ctx.Window.Resources[(Get-TkSeverityBrushKey -Severity $Severity)]

    if ($null -eq $source) {
        return $null
    }

    $colour = [System.Windows.Media.Color]::FromArgb(
        $Alpha, $source.Color.R, $source.Color.G, $source.Color.B)

    return New-Object System.Windows.Media.SolidColorBrush($colour)
}

<#
.SYNOPSIS
    Sets a proportional bar to a percentage and a result colour.

.DESCRIPTION
    A bar is a Grid with two star columns, the first holding the fill. The two
    columns share the width as value and remainder, so the fill stays
    proportional through any resize with nothing measured in code. A measured
    width reads zero whenever the bar has just been made visible and has not
    been laid out yet, which is how the first audit score bar drew nothing.

    The fill takes the severity colour by resource reference, so it follows a
    theme change.

.PARAMETER Bar
    The Grid with two column definitions.

.PARAMETER Fill
    The element in its first column.

.PARAMETER Percent
    Clamped to 0 to 100.

.PARAMETER Severity
    Pass, Warning, Fail, or anything else for the muted colour.
#>
function Set-TkUsageBarElement {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [System.Windows.Controls.Grid] $Bar,

        [Parameter(Mandatory)]
        [System.Windows.Controls.Border] $Fill,

        [Parameter(Mandatory)]
        [double] $Percent,

        [Parameter()]
        [AllowEmptyString()]
        [string] $Severity = 'Pass'
    )

    if ($Bar.ColumnDefinitions.Count -eq 2) {

        $filled = [math]::Max(0, [math]::Min(100, $Percent))

        $Bar.ColumnDefinitions[0].Width = New-Object System.Windows.GridLength(
            $filled, [System.Windows.GridUnitType]::Star)

        $Bar.ColumnDefinitions[1].Width = New-Object System.Windows.GridLength(
            (100 - $filled), [System.Windows.GridUnitType]::Star)
    }

    $Fill.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty,
        (Get-TkSeverityBrushKey -Severity $Severity))
}

<#
.SYNOPSIS
    Sets a bar declared in the markup, found by the names of its parts.

.PARAMETER BarName
    Name of the Grid.

.PARAMETER FillName
    Name of the Border in its first column.
#>
function Set-TkUsageBar {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string] $BarName,

        [Parameter(Mandatory)]
        [string] $FillName,

        [Parameter(Mandatory)]
        [double] $Percent,

        [Parameter()]
        [AllowEmptyString()]
        [string] $Severity = 'Pass'
    )

    $bar  = Get-TkControl -Name $BarName
    $fill = Get-TkControl -Name $FillName

    if ($bar -and $fill) {
        Set-TkUsageBarElement -Bar $bar -Fill $fill -Percent $Percent -Severity $Severity
    }
}

<#
.SYNOPSIS
    Builds a bar in code, for a tile drawn at run time.

.OUTPUTS
    System.Windows.Controls.Border, the track holding the bar.
#>
function New-TkUsageBar {
    [CmdletBinding()]
    [OutputType([System.Windows.Controls.Border])]
    param(
        [Parameter(Mandatory)]
        [double] $Percent,

        [Parameter()]
        [AllowEmptyString()]
        [string] $Severity = 'Pass',

        [Parameter()]
        [double] $Height = 6
    )

    $radius = New-Object System.Windows.CornerRadius($Height / 2)

    $track = New-Object System.Windows.Controls.Border
    $track.Height       = $Height
    $track.CornerRadius = $radius
    $track.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, 'SurfaceRaised')

    $grid = New-Object System.Windows.Controls.Grid
    $grid.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition))
    $grid.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition))

    $fill = New-Object System.Windows.Controls.Border
    $fill.CornerRadius = $radius

    [System.Windows.Controls.Grid]::SetColumn($fill, 0)
    [void] $grid.Children.Add($fill)

    $track.Child = $grid

    Set-TkUsageBarElement -Bar $grid -Fill $fill -Percent $Percent -Severity $Severity

    return $track
}

<#
.SYNOPSIS
    Appends a finding as a self contained card.

.DESCRIPTION
    Replaces the flat run of coloured words the reports used to be. A page of
    those reads as one undifferentiated block, which is exactly the complaint:
    nothing separates one finding from the next, and the eye has nowhere to
    rest.

    A card gives each finding a boundary, a severity chip that carries the
    verdict at a glance, a title line, and the explanation set apart
    underneath. Where a safe single step correction exists, the card carries
    the button for it.

    Colours are attached by resource reference so a card follows a theme
    change, and every piece of text is selectable.

.PARAMETER Severity
    Pass, Info, Warning or Fail.

.PARAMETER Title
    What the finding is about.

.PARAMETER State
    The measured value, shown to the right of the title.

.PARAMETER Detail
    The explanation. Set in muted text under the title.

.PARAMETER Action
    What to change, shown in its own band under the detail.

.PARAMETER RemediationId
    Key into the remediation allow list. When given and the correction is
    available, the card carries a button that applies it.
#>
function Add-TkFindingCard {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [System.Windows.Documents.FlowDocument] $Document,

        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string] $Severity,

        [Parameter(Mandatory)]
        [string] $Title,

        [Parameter()]
        [AllowEmptyString()]
        [string] $State = '',

        [Parameter()]
        [AllowEmptyString()]
        [string] $Detail = '',

        [Parameter()]
        [AllowEmptyString()]
        [string] $Action = '',

        [Parameter()]
        [AllowEmptyString()]
        [string] $RemediationId = '',

        # Colours the whole card by result and puts an icon in front of the
        # title. A neutral card with a coloured chip reads as a list; a page of
        # results has to be scannable without reading it, which is what an audit
        # is for.
        [Parameter()]
        [switch] $Tinted
    )

    $card = New-Object System.Windows.Controls.Border
    $card.CornerRadius = New-Object System.Windows.CornerRadius(7)
    $card.Padding      = New-Object System.Windows.Thickness(14, 11, 14, 11)
    $card.Margin       = New-Object System.Windows.Thickness(0, 0, 0, 9)

    $severityKey = Get-TkSeverityBrushKey -Severity $Severity

    if ($Tinted) {

        # A thick left edge in the full colour, and the body in the same colour
        # at low alpha. The edge is what the eye follows down a long report.
        $card.BorderThickness = New-Object System.Windows.Thickness(4, 1, 1, 1)
        $card.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, $severityKey)

        $tint = Get-TkSeverityTintBrush -Severity $Severity

        if ($tint) {
            $card.Background = $tint
        }
        else {
            $card.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, 'Surface')
        }
    }
    else {
        $card.BorderThickness = New-Object System.Windows.Thickness(1)
        $card.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, 'Surface')
        $card.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, 'BorderSubtle')
    }

    $stack = New-Object System.Windows.Controls.StackPanel
    $card.Child = $stack

    # --- Title line: chip, title, state -----------------------------------
    $header = New-Object System.Windows.Controls.Grid

    foreach ($width in @('Auto', 'Star', 'Auto')) {

        $definition = New-Object System.Windows.Controls.ColumnDefinition

        $definition.Width = if ($width -eq 'Auto') { [System.Windows.GridLength]::Auto }
                            else { [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star) }

        $header.ColumnDefinitions.Add($definition)
    }

    if ($Tinted) {

        $icon = New-Object System.Windows.Controls.TextBlock
        $icon.Text              = Get-TkSeverityGlyph -Severity $Severity
        $icon.FontSize          = 16
        $icon.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        $icon.SetResourceReference([System.Windows.Controls.TextBlock]::FontFamilyProperty, 'IconFont')
        $icon.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, $severityKey)

        [System.Windows.Controls.Grid]::SetColumn($icon, 0)
        [void] $header.Children.Add($icon)
    }
    else {
        $chip = New-TkSeverityChip -Severity $Severity
        [System.Windows.Controls.Grid]::SetColumn($chip, 0)
        [void] $header.Children.Add($chip)
    }

    $titleText = New-TkSelectableText -Value $Title
    $titleText.FontWeight        = [System.Windows.FontWeights]::SemiBold
    $titleText.FontSize          = 13.5
    $titleText.Margin            = New-Object System.Windows.Thickness(10, 0, 10, 0)
    $titleText.VerticalAlignment = [System.Windows.VerticalAlignment]::Center

    [System.Windows.Controls.Grid]::SetColumn($titleText, 1)
    [void] $header.Children.Add($titleText)

    if ($State) {

        $stateText = New-TkSelectableText -Value $State
        # A state is normally a word or a value. One that is a whole sentence,
        # such as a reason Windows wrote, wraps in a bounded column rather than
        # taking the width of the title and folding it one word per line.
        $stateText.FontSize          = 12
        $stateText.TextWrapping      = [System.Windows.TextWrapping]::Wrap
        $stateText.MaxWidth          = 340
        $stateText.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
        $stateText.SetResourceReference([System.Windows.Controls.TextBox]::ForegroundProperty, 'TextMuted')

        [System.Windows.Controls.Grid]::SetColumn($stateText, 2)
        [void] $header.Children.Add($stateText)
    }

    [void] $stack.Children.Add($header)

    # --- Explanation ------------------------------------------------------
    if ($Detail) {

        $detailText = New-TkSelectableText -Value $Detail
        $detailText.FontSize = 12
        $detailText.Margin   = New-Object System.Windows.Thickness(0, 7, 0, 0)
        $detailText.SetResourceReference([System.Windows.Controls.TextBox]::ForegroundProperty, 'TextMuted')

        [void] $stack.Children.Add($detailText)
    }

    # --- What to change, and the button that does it ----------------------
    if ($Action -or $RemediationId) {

        $band = New-Object System.Windows.Controls.Border
        $band.BorderThickness = New-Object System.Windows.Thickness(0, 1, 0, 0)
        $band.Padding         = New-Object System.Windows.Thickness(0, 9, 0, 0)
        $band.Margin          = New-Object System.Windows.Thickness(0, 9, 0, 0)
        $band.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, 'BorderSubtle')

        $bandGrid = New-Object System.Windows.Controls.Grid

        foreach ($width in @('Star', 'Auto')) {

            $definition = New-Object System.Windows.Controls.ColumnDefinition

            $definition.Width = if ($width -eq 'Auto') { [System.Windows.GridLength]::Auto }
                                else { [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star) }

            $bandGrid.ColumnDefinitions.Add($definition)
        }

        if ($Action) {

            $actionText = New-TkSelectableText -Value $Action
            $actionText.FontSize          = 12
            $actionText.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
            $actionText.SetResourceReference([System.Windows.Controls.TextBox]::ForegroundProperty, 'TextPrimary')

            [System.Windows.Controls.Grid]::SetColumn($actionText, 0)
            [void] $bandGrid.Children.Add($actionText)
        }

        $button = New-TkRemediationButton -RemediationId $RemediationId

        if ($button) {
            [System.Windows.Controls.Grid]::SetColumn($button, 1)
            [void] $bandGrid.Children.Add($button)
        }

        $band.Child = $bandGrid
        [void] $stack.Children.Add($band)
    }

    $container = New-Object System.Windows.Documents.BlockUIContainer($card)
    $container.Margin = New-Object System.Windows.Thickness(0)

    $Document.Blocks.Add($container)
}

<#
.SYNOPSIS
    Builds the coloured severity chip shown on a finding card.

.OUTPUTS
    System.Windows.Controls.Border
#>
function New-TkSeverityChip {
    [CmdletBinding()]
    [OutputType([System.Windows.Controls.Border])]
    param(
        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string] $Severity
    )

    $label = if ($Severity) { $Severity.ToUpperInvariant() } else { 'INFO' }

    $text = New-Object System.Windows.Controls.TextBlock
    $text.Text       = $label
    $text.FontSize   = 10
    $text.FontWeight = [System.Windows.FontWeights]::Bold
    $text.FontFamily = New-Object System.Windows.Media.FontFamily('Cascadia Mono, Consolas')
    $text.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center

    $text.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty,
                               (Get-TkSeverityBrushKey -Severity $Severity))

    $chip = New-Object System.Windows.Controls.Border
    $chip.CornerRadius      = New-Object System.Windows.CornerRadius(4)
    $chip.BorderThickness   = New-Object System.Windows.Thickness(1)
    $chip.Padding           = New-Object System.Windows.Thickness(7, 3, 7, 3)
    $chip.MinWidth          = 66
    $chip.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $chip.Child             = $text

    $chip.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty,
                               (Get-TkSeverityBrushKey -Severity $Severity))
    $chip.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, 'SurfaceRaised')

    return $chip
}

<#
.SYNOPSIS
    Builds the button that applies a correction, or nothing when there is none.

.DESCRIPTION
    Returns $null when the identifier is empty or is not in the allow list, so
    a finding with no safe single step fix simply has no button rather than a
    button that does something approximate.

    The button is disabled, with the reason in its tooltip, when the
    correction needs rights this instance does not have.

.OUTPUTS
    System.Windows.Controls.Button, or $null.
#>
function New-TkRemediationButton {
    [CmdletBinding()]
    param(
        [Parameter()]
        [AllowEmptyString()]
        [string] $RemediationId
    )

    if ([string]::IsNullOrWhiteSpace($RemediationId)) {
        return $null
    }

    $table = Get-TkRemediationTable

    if (-not $table.ContainsKey($RemediationId)) {
        return $null
    }

    $entry = $table[$RemediationId]

    $button = New-Object System.Windows.Controls.Button
    # The label says which of the two things happens: a correction, or a page
    # opening. An entry can name its own when neither fits, such as a guide.
    $button.Content = if ($entry.ContainsKey('Button')) { [string] $entry.Button }
                      elseif ([string] $entry.Kind -eq 'Open') { 'Open settings' }
                      else { 'Fix this' }

    $button.Tag        = $RemediationId
    $button.Margin     = New-Object System.Windows.Thickness(12, 0, 0, 0)
    $button.MinWidth   = 90
    $button.Cursor     = [System.Windows.Input.Cursors]::Hand
    $button.VerticalAlignment = [System.Windows.VerticalAlignment]::Center

    $button.SetResourceReference([System.Windows.Controls.Button]::StyleProperty, 'PrimaryButton')

    if ($entry.Elevated -and -not (Test-TkIsElevated)) {

        $button.IsEnabled = $false
        $button.ToolTip   = 'Needs administrator rights. Use "Restart as administrator" in the header.'
    }
    else {
        $button.ToolTip = $entry.Explanation
    }

    $button.Add_Click({
        # Not named $sender or $eventArgs: both are automatic variables.
        param($clicked, $clickArgs)

        $id = [string] $clicked.Tag

        if ($id) {
            Invoke-TkRemediationFromUi -RemediationId $id
        }
    })

    return $button
}

<#
.SYNOPSIS
    Puts a document into a rich text control.

.DESCRIPTION
    Tolerates a missing control so a page that lost its box degrades instead
    of throwing.
#>
function Set-TkDocument {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string] $ControlName,

        [Parameter(Mandatory)]
        [System.Windows.Documents.FlowDocument] $Document
    )

    $control = Get-TkControl -Name $ControlName

    if ($null -eq $control) {
        return
    }

    $control.Document = $Document
    $control.ScrollToHome()
}


