<#
    Toolkit - UI / Dashboard page

    The page the toolkit opens on. It answers the first questions of a support
    call, which machine is this, how is it connected, is anything wrong, and
    hands every problem to the page that deals with it.

    Each card reads on its own, at the same time as the others, and shows that
    it is reading until its answer arrives. A page that opens empty and stays
    empty for ten seconds reads as broken, however correct it is once it fills.

    The quick actions are declared as data by Get-TkQuickAction: a page, an
    optional tab, and the function that starts the work. That keeps them
    checkable by a test, and lets the System page show the same set without a
    second copy to drift.
#>

<#
.SYNOPSIS
    Wires the Dashboard page.
#>
function Initialize-TkDashboardPage {
    [CmdletBinding()]
    param()

    Register-TkClick -Name 'BtnRefreshDashboard' -Action { Update-TkDashboard }
    Register-TkClick -Name 'BtnDashPublicIp'     -Action { Show-TkDashboardPublicIp }

    Add-TkQuickActionPanel -PanelName 'DashQuickActions'
}

<#
.SYNOPSIS
    Reads the machine in three parallel parts and fills each card as it lands.
#>
function Update-TkDashboard {
    [CmdletBinding()]
    param()

    foreach ($card in @('DashWorkstation', 'DashNetwork', 'DashHealthCard')) {
        Set-TkCardLoading -Name $card -Loading $true
    }

    Invoke-TkBackgroundAction -StatusText 'Reading the workstation...' `
        -ScriptBlock { Get-TkDashboardWorkstation } `
        -OnComplete {
            param($result)

            Write-TkDashboardWorkstation -Part (@($result.Output) | Select-Object -First 1)
            Set-TkCardLoading -Name 'DashWorkstation' -Loading $false
        }

    Invoke-TkBackgroundAction -StatusText 'Reading the network adapters and routes...' `
        -ScriptBlock { Get-TkDashboardNetwork } `
        -OnComplete {
            param($result)

            Write-TkDashboardNetwork -Part (@($result.Output) | Select-Object -First 1)
            Set-TkCardLoading -Name 'DashNetwork' -Loading $false
        }

    Invoke-TkBackgroundAction -StatusText 'Reading restart state, updates, disks and battery...' `
        -ScriptBlock { Get-TkDashboardHealthData } `
        -OnComplete {
            param($result)

            Write-TkDashboardHealth -Part (@($result.Output) | Select-Object -First 1)
            Set-TkCardLoading -Name 'DashHealthCard' -Loading $false
        }
}

<#
.SYNOPSIS
    Writes a whole snapshot at once, for a console session or a render.

.PARAMETER Snapshot
    Output of Get-TkDashboardSnapshot.
#>
function Write-TkDashboardFields {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        $Snapshot
    )

    Write-TkDashboardWorkstation -Part $Snapshot
    Write-TkDashboardNetwork     -Part $Snapshot
    Write-TkDashboardHealth      -Part $Snapshot

    foreach ($card in @('DashWorkstation', 'DashNetwork', 'DashHealthCard')) {
        Set-TkCardLoading -Name $card -Loading $false
    }
}

<#
.SYNOPSIS
    Fills the Workstation card.

.PARAMETER Part
    Anything with Identity and OS. Null when the part could not be read.
#>
function Write-TkDashboardWorkstation {
    [CmdletBinding()]
    param(
        [Parameter()]
        $Part
    )

    $identity = if ($Part) { $Part.Identity } else { $null }
    $os       = if ($Part) { $Part.OS } else { $null }

    $unknown = 'Not available'

    $domain = if (-not $identity) { $unknown }
              elseif ($identity.PartOfDomain) { '{0} (joined)' -f $identity.Domain }
              else { '{0} (workgroup)' -f $identity.Domain }

    Set-TkFieldText -Field @{
        'DashComputerName' = $env:COMPUTERNAME
        'DashModel'        = if ($identity) { '{0} {1}' -f $identity.Manufacturer, $identity.Model } else { $unknown }
        'DashOs'           = if ($os) { '{0} {1}, build {2}' -f $os.Caption, $os.DisplayVersion, $os.Build } else { $unknown }
        'DashUptime'       = if ($os) { $os.UptimeText } else { $unknown }
        'DashUser'         = if ($identity) { $identity.LoggedOnUser } else { $unknown }
        'DashDomain'       = $domain
        'DashSerial'       = if ($identity) { $identity.SerialNumber } else { $unknown }
        'DashActivation'   = if ($os) { $os.Activation } else { $unknown }
    }
}

<#
.SYNOPSIS
    Fills the Network card.

.PARAMETER Part
    Anything with Adapter and Adapters. Null when the part could not be read.
#>
function Write-TkDashboardNetwork {
    [CmdletBinding()]
    param(
        [Parameter()]
        $Part
    )

    $adapter  = if ($Part) { $Part.Adapter } else { $null }
    # @() around the if, not inside it. An if statement whose branch yields an
    # empty array yields nothing at all, so the variable became null, and
    # passed on as the adapter list that null failed the completion handler:
    # the log recorded it, and the card was left half written.
    $adapters = @(if ($Part) { $Part.Adapters | Where-Object { $null -ne $_ } })

    $unknown    = 'Not available'
    $hasAddress = ($null -ne $adapter -and $adapter.IPv4Address -and $adapter.IPv4Address -ne 'None')

    $addressing = if (-not $adapter) { $unknown }
                  elseif ([string] $adapter.Dhcp -eq 'Enabled') { 'DHCP' }
                  elseif ([string] $adapter.Dhcp -eq 'Disabled') { 'Static' }
                  else { [string] $adapter.Dhcp }

    $adapterLine = if (-not $adapter) { 'No adapter has a usable IPv4 address' }
                   elseif ($adapter.Gateway -eq 'None') { '{0}, {1}, no default gateway' -f $adapter.Name, $adapter.LinkSpeed }
                   else { '{0}, {1}' -f $adapter.Name, $adapter.LinkSpeed }

    Set-TkFieldText -Field @{
        'DashIpv4'    = if ($hasAddress) { '{0}/{1}' -f $adapter.IPv4Address, $adapter.PrefixLength } else { 'Not connected' }
        'DashAdapter' = $adapterLine
        'DashGateway' = if ($adapter) { $adapter.Gateway } else { $unknown }
        'DashDns'     = if ($adapter -and $adapter.DnsServers) { $adapter.DnsServers } else { 'None' }
        'DashDhcp'    = $addressing
        'DashMac'     = if ($adapter) { $adapter.MacAddress } else { $unknown }
    }

    # The other adapters in one line, and no line at all when there are none.
    $others = Get-TkSecondaryAdapterSummary -Adapter $adapters -Primary $adapter
    $label  = Get-TkControl -Name 'DashOtherAdapters'

    if ($label) {
        $label.Text       = $others
        $label.Visibility = if ($others) { [System.Windows.Visibility]::Visible }
                            else { [System.Windows.Visibility]::Collapsed }
    }
}

<#
.SYNOPSIS
    Draws the health tiles.

.PARAMETER Part
    Anything with Reboot, LastHotFix, Volumes, Disks and Battery. Null when the
    part could not be read.
#>
function Write-TkDashboardHealth {
    [CmdletBinding()]
    param(
        [Parameter()]
        $Part
    )

    $panel = Get-TkControl -Name 'DashHealth'
    $note  = Get-TkControl -Name 'DashHealthNote'

    if ($panel) {
        $panel.Children.Clear()
    }

    if ($null -eq $Part) {

        if ($note) {
            $note.Text = 'The health of this machine could not be read. The log has the reason.'
        }

        return
    }

    if ($panel) {
        foreach ($tile in (ConvertTo-TkDashboardHealth -Snapshot $Part)) {
            [void] $panel.Children.Add((New-TkHealthTile -Tile $tile))
        }
    }

    if ($note) {
        $note.Text = 'Read at {0}. Click a tile to open the entry that deals with it.' -f (Get-Date -Format 'HH:mm')
    }
}

<#
.SYNOPSIS
    Draws one health tile.

.DESCRIPTION
    Tinted and edged by result with an icon, like an audit card, so the row
    reads at a glance and colour is never the only signal. The whole tile is
    the link to the entry behind it: a small "details" link would be one more
    thing to find.

.PARAMETER Tile
    Output of New-TkHealthTileData.
#>
function New-TkHealthTile {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [pscustomobject] $Tile
    )

    $severityKey = Get-TkSeverityBrushKey -Severity $Tile.Severity

    $border = New-Object System.Windows.Controls.Border
    $border.CornerRadius    = New-Object System.Windows.CornerRadius(7)
    $border.Padding         = New-Object System.Windows.Thickness(12, 10, 12, 10)
    # The same gap below as to the right: the tiles wrap onto a second row.
    $border.Margin          = New-Object System.Windows.Thickness(0, 0, 8, 8)
    $border.BorderThickness = New-Object System.Windows.Thickness(3, 1, 1, 1)
    $border.Cursor          = [System.Windows.Input.Cursors]::Hand
    $border.Tag             = $Tile

    $border.ToolTip = if ($Tile.Choice) { 'Open {0} on the {1} page' -f $Tile.Choice, $Tile.Page }
                      else { 'Open the {0} page' -f $Tile.Page }

    $border.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, $severityKey)

    $tint = Get-TkSeverityTintBrush -Severity $Tile.Severity

    if ($tint) {
        $border.Background = $tint
    }
    else {
        $border.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, 'SurfaceRaised')
    }

    $stack = New-Object System.Windows.Controls.StackPanel

    # --- Icon and title ---------------------------------------------------
    $header = New-Object System.Windows.Controls.StackPanel
    $header.Orientation = [System.Windows.Controls.Orientation]::Horizontal

    $icon = New-Object System.Windows.Controls.TextBlock
    $icon.Text              = Get-TkSeverityGlyph -Severity $Tile.Severity
    $icon.FontSize          = 13
    $icon.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $icon.SetResourceReference([System.Windows.Controls.TextBlock]::FontFamilyProperty, 'IconFont')
    $icon.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, $severityKey)

    $title = New-Object System.Windows.Controls.TextBlock
    $title.Text              = $Tile.Title
    $title.FontSize          = 11
    $title.Margin            = New-Object System.Windows.Thickness(6, 0, 0, 0)
    $title.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $title.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, 'TextMuted')

    [void] $header.Children.Add($icon)
    [void] $header.Children.Add($title)
    [void] $stack.Children.Add($header)

    # --- Value ------------------------------------------------------------
    $value = New-Object System.Windows.Controls.TextBlock
    $value.Text         = $Tile.Value
    $value.FontSize     = 16
    $value.FontWeight   = [System.Windows.FontWeights]::SemiBold
    $value.TextWrapping = [System.Windows.TextWrapping]::Wrap
    $value.Margin       = New-Object System.Windows.Thickness(0, 6, 0, 0)
    $value.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, 'TextPrimary')

    [void] $stack.Children.Add($value)

    if ($null -ne $Tile.Percent) {

        $bar = New-TkUsageBar -Percent ([double] $Tile.Percent) -Severity $Tile.Severity
        $bar.Margin = New-Object System.Windows.Thickness(0, 6, 0, 0)

        [void] $stack.Children.Add($bar)
    }

    # --- Detail -----------------------------------------------------------
    if ($Tile.Detail) {

        $detail = New-Object System.Windows.Controls.TextBlock
        $detail.Text         = $Tile.Detail
        $detail.FontSize     = 11
        $detail.TextWrapping = [System.Windows.TextWrapping]::Wrap
        $detail.Margin       = New-Object System.Windows.Thickness(0, 4, 0, 0)
        $detail.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, 'TextMuted')

        [void] $stack.Children.Add($detail)
    }

    $border.Child = $stack

    $border.Add_MouseLeftButtonUp({
        # Not named $sender or $eventArgs: both are automatic variables.
        param($clicked, $clickArgs)

        if ($clicked.Tag) {
            Open-TkHealthTileDestination -Tile $clicked.Tag
        }
    })

    return $border
}

<#
.SYNOPSIS
    Opens the page a tile is about, and the entry on it.

.DESCRIPTION
    The page alone was not enough: the battery tile landed on the Hardware page
    with the keyboard test selected, and the reader still had to find the
    battery. Selecting the entry also runs it, the way clicking it would.

.PARAMETER Tile
    Output of New-TkHealthTileData.
#>
function Open-TkHealthTileDestination {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [pscustomobject] $Tile
    )

    Show-TkPage -Name $Tile.Page

    # The tab first: an entry in a tab that is not selected is selected, and
    # runs, out of sight.
    if ($Tile.TabControl -and -not (Select-TkTab -TabControlName $Tile.TabControl -Header $Tile.Tab)) {

        Write-TkLog -Level Warning -Category 'Interface' -Message (
            'Health tile "{0}": no tab titled "{1}" in {2}.' -f $Tile.Title, $Tile.Tab, $Tile.TabControl
        )
    }

    if ($Tile.List -and -not (Select-TkListChoice -ListName $Tile.List -Title $Tile.Choice)) {

        Write-TkLog -Level Warning -Category 'Interface' -Message (
            'Health tile "{0}": no entry titled "{1}" in {2}.' -f $Tile.Title, $Tile.Choice, $Tile.List
        )
    }
}

<#
.SYNOPSIS
    Returns the quick actions: where each one goes and what it starts.

.DESCRIPTION
    Data rather than handlers, so a test can check that every page, tab and
    function named here exists. A quick action pointing at a renamed tab would
    otherwise open the right page and quietly start nothing.

    Start is the function that begins the work, called with Arguments. Page
    and Tab are where the operator is taken first, so the result appears in
    front of them; an empty Page stays where it is.

.OUTPUTS
    PSCustomObject[]
#>
function Get-TkQuickAction {
    [CmdletBinding()]
    [OutputType([pscustomobject[]])]
    param()

    return @(
        [pscustomobject] @{
            Id         = 'security-audit'
            Name       = 'Run the security audit'
            Hint       = 'Scores this machine against the CIS and ANSSI controls, with an action on every warning.'
            Glyph      = [string] [char] 0xEA18
            Page       = 'Security'
            TabControl = 'SecurityTabs'
            Tab        = 'Security audit'
            Start      = 'Invoke-TkAuditFromUi'
            Arguments  = @{}
        }
        [pscustomobject] @{
            Id         = 'full-check'
            Name       = 'Run the full diagnostic'
            Hint       = 'Restart state, storage, stability, updates, printing and profiles, in one report.'
            Glyph      = [string] [char] 0xE95E
            Page       = 'Diagnostics'
            TabControl = 'DiagnosticsTabs'
            Tab        = 'Reports'
            Start      = 'Start-TkFullDiagnostic'
            Arguments  = @{}
        }
        [pscustomobject] @{
            Id         = 'support-bundle'
            Name       = 'Collect a support bundle'
            Hint       = 'Everything a ticket needs in one ZIP. Nothing leaves the machine until you send it.'
            Glyph      = [string] [char] 0xE74E
            Page       = 'Diagnostics'
            TabControl = 'DiagnosticsTabs'
            Tab        = 'Reports'
            Start      = 'Invoke-TkSupportBundleFromUi'
            Arguments  = @{}
        }
        [pscustomobject] @{
            Id         = 'windows-update'
            Name       = 'Open Windows Update'
            Hint       = 'Check for updates, resume a pause, or see what waits for a restart.'
            Glyph      = [string] [char] 0xE895
            Page       = ''
            TabControl = ''
            Tab        = ''
            Start      = 'Invoke-TkRemediationFromUi'
            Arguments  = @{ RemediationId = 'open-windows-update' }
        }
    )
}

<#
.SYNOPSIS
    Takes the operator to where a quick action happens, and starts it.

.PARAMETER Id
    Identifier from Get-TkQuickAction.
#>
function Invoke-TkQuickAction {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string] $Id
    )

    $action = @(Get-TkQuickAction) | Where-Object { $_.Id -eq $Id } | Select-Object -First 1

    if ($null -eq $action) {
        Set-TkStatus -Text ('Unknown quick action: {0}' -f $Id)
        return
    }

    if ($action.Page) {
        Show-TkPage -Name $action.Page
    }

    if ($action.TabControl -and -not (Select-TkTab -TabControlName $action.TabControl -Header $action.Tab)) {

        Write-TkLog -Level Warning -Category 'Interface' -Message (
            'Quick action "{0}": the tab "{1}" was not found.' -f $Id, $action.Tab
        )
    }

    $arguments = $action.Arguments

    & $action.Start @arguments
}

<#
.SYNOPSIS
    Fills a panel with one card per quick action.

.PARAMETER PanelName
    Name of the panel in the markup, a UniformGrid or any other panel.
#>
function Add-TkQuickActionPanel {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string] $PanelName
    )

    $panel = Get-TkControl -Name $PanelName

    if ($null -eq $panel) {
        return
    }

    $panel.Children.Clear()

    foreach ($action in (Get-TkQuickAction)) {

        $button = New-Object System.Windows.Controls.Button
        $button.Tag     = $action.Id
        $button.ToolTip = $action.Hint
        $button.SetResourceReference([System.Windows.Controls.Button]::StyleProperty, 'ActionCard')

        $grid = New-Object System.Windows.Controls.Grid

        foreach ($width in @([System.Windows.GridLength]::Auto,
                             (New-Object System.Windows.GridLength(1, [System.Windows.GridUnitType]::Star)))) {

            $column = New-Object System.Windows.Controls.ColumnDefinition
            $column.Width = $width

            $grid.ColumnDefinitions.Add($column)
        }

        $tile = New-Object System.Windows.Controls.Border
        $tile.SetResourceReference([System.Windows.Controls.Border]::StyleProperty, 'ItemTile')
        $tile.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, 'Accent')

        $glyph = New-Object System.Windows.Controls.TextBlock
        $glyph.Text = $action.Glyph
        $glyph.SetResourceReference([System.Windows.Controls.TextBlock]::StyleProperty, 'TileGlyph')

        $tile.Child = $glyph

        [System.Windows.Controls.Grid]::SetColumn($tile, 0)
        [void] $grid.Children.Add($tile)

        $text = New-Object System.Windows.Controls.StackPanel
        $text.VerticalAlignment = [System.Windows.VerticalAlignment]::Center

        $name = New-Object System.Windows.Controls.TextBlock
        $name.Text = $action.Name
        $name.SetResourceReference([System.Windows.Controls.TextBlock]::StyleProperty, 'ChoiceTitle')

        $hint = New-Object System.Windows.Controls.TextBlock
        $hint.Text = $action.Hint
        $hint.SetResourceReference([System.Windows.Controls.TextBlock]::StyleProperty, 'ChoiceHint')

        [void] $text.Children.Add($name)
        [void] $text.Children.Add($hint)

        [System.Windows.Controls.Grid]::SetColumn($text, 1)
        [void] $grid.Children.Add($text)

        $button.Content = $grid

        $button.Add_Click({
            param($clicked, $clickArgs)

            Invoke-TkQuickAction -Id ([string] $clicked.Tag)
        })

        [void] $panel.Children.Add($button)
    }
}

<#
.SYNOPSIS
    Asks an outside service for the public address, on request only.

.DESCRIPTION
    Never read with the rest of the Dashboard. It is the one reading that
    leaves the machine, and a tool run on someone else's workstation does not
    contact the internet unless the operator asks it to.
#>
function Show-TkDashboardPublicIp {
    [CmdletBinding()]
    param()

    $label = Get-TkControl -Name 'DashPublicIp'

    if ($label) {
        $label.Text = 'Asking...'
    }

    Invoke-TkBackgroundAction -StatusText 'Asking for the public address...' `
        -ScriptBlock { Get-TkPublicIpAddress } `
        -OnComplete {
            param($result)

            $answer = @($result.Output) | Select-Object -First 1
            $target = Get-TkControl -Name 'DashPublicIp'

            if ($target) {
                $target.Text = if ($answer) { [string] $answer } else { 'Not available' }
            }
        }
}


# ==========================================================================
# Source: src/UI/Pages/SystemPage.ps1
# ==========================================================================

<#
    Toolkit - UI / System page

    Displays the machine inventory and drives the vendor actions. The CIM
    queries run in the background because TPM and BitLocker lookups take a
    noticeable moment on some machines and would otherwise freeze the window.
#>

# Last inventory snapshot, kept so the vendor buttons and the export do not
# have to query CIM again.
$script:TkSystemSnapshot = $null

<#
.SYNOPSIS
    Wires the System page.
#>
function Initialize-TkSystemPage {
    [CmdletBinding()]
    param()

    Register-TkClick -Name 'BtnRefreshSystem' -Action { Update-TkSystemPage }

    Register-TkClick -Name 'BtnCopySerial' -Action {

        if (-not $script:TkSystemSnapshot -or -not $script:TkSystemSnapshot.Identity) {
            Set-TkStatus -Text 'The identity is still being read.'
            return
        }

        $serial = $script:TkSystemSnapshot.Identity.SerialNumber

        if (Set-TkClipboard -Text $serial) {
            Set-TkStatus -Text ('Serial number copied: {0}' -f $serial)
        }
    }

    Register-TkClick -Name 'BtnVendorDrivers' -Action {
        Open-TkVendorSupport -Kind 'Drivers' -Identity $script:TkSystemSnapshot.Identity | Out-Null
    }

    Register-TkClick -Name 'BtnVendorWarranty' -Action {
        Open-TkVendorSupport -Kind 'Warranty' -Identity $script:TkSystemSnapshot.Identity | Out-Null
    }

    Register-TkClick -Name 'BtnVendorTool' -Action {

        if (-not (Test-TkIsElevated)) {
            Set-TkStatus -Text 'Installing the firmware utility requires an elevated instance.'
            return
        }

        $identity = $script:TkSystemSnapshot.Identity
        $vendor   = Get-TkVendorProfile -Manufacturer $identity.Manufacturer

        if (-not $vendor -or [string]::IsNullOrWhiteSpace($vendor.updateToolPackage)) {
            Set-TkStatus -Text 'No firmware utility is known for this manufacturer.'
            return
        }

        $confirmed = Confirm-TkAction -Title 'Install firmware utility' -Message (
            "Install {0} through winget?`n`nThe toolkit does not flash firmware itself: the vendor utility takes over from there." -f $vendor.updateToolName
        )

        if (-not $confirmed) {
            return
        }

        $packageId = $vendor.updateToolPackage

        Invoke-TkBackgroundAction -StatusText ('Installing {0}...' -f $vendor.updateToolName) `
            -ArgumentList @($packageId) `
            -ScriptBlock {
                param($id)
                Install-TkWingetPackage -PackageId $id -Confirm:$false
            } `
            -OnComplete {
                param($result)

                if ($result.Output -contains $true) {
                    Write-TkLog -Level Information -Category 'Vendor' -Message 'Firmware utility installed.'
                }
                else {
                    Write-TkLog -Level Warning -Category 'Vendor' -Message 'The firmware utility could not be installed.'
                }
            }
    }

    Register-TkClick -Name 'BtnExportReport' -Action { Export-TkSystemReportFromUi }

    # The inventory costs a few seconds of CIM queries, and the toolkit opens
    # on the Dashboard now, so it waits for the page to be opened.
    Register-TkFirstShow -PageName 'System' -Action { Update-TkSystemPage }
}

<#
.SYNOPSIS
    Reads the inventory in four parallel parts, each filling its own cards.

.DESCRIPTION
    One combined read left every card empty for as long as the slowest reader
    took, with nothing on screen to say anything was happening. The identity
    answers in a moment, the operating system soon after, the hardware and the
    platform security last; each card now shows that it is reading and fills
    as soon as its own part lands.

    The snapshot is filled part by part as well, so the vendor buttons and the
    volume selector have what they need as soon as their part is read.
#>
function Update-TkSystemPage {
    [CmdletBinding()]
    param()

    if ($null -eq $script:TkSystemSnapshot) {
        $script:TkSystemSnapshot = [pscustomobject] @{
            Identity = $null
            Bios     = $null
            OS       = $null
            Hardware = $null
            Volumes  = @()
            Security = $null
        }
    }

    foreach ($card in @('SystemIdentity', 'SystemFirmware', 'SystemOs', 'SystemHardware', 'SystemSecurity')) {
        Set-TkCardLoading -Name $card -Loading $true
    }

    # Runs in a background runspace: every script block returns plain data only.
    Invoke-TkBackgroundAction -StatusText 'Reading the machine identity and firmware...' `
        -ScriptBlock {
            [pscustomobject] @{
                Identity = Get-TkMachineIdentity
                Bios     = Get-TkBiosStatus
            }
        } `
        -OnComplete {
            param($result)

            $part = @($result.Output) | Select-Object -First 1

            if ($part) {
                $script:TkSystemSnapshot.Identity = $part.Identity
                $script:TkSystemSnapshot.Bios     = $part.Bios
            }

            Write-TkSystemIdentity -Identity $script:TkSystemSnapshot.Identity -Bios $script:TkSystemSnapshot.Bios

            Set-TkCardLoading -Name 'SystemIdentity' -Loading $false
            Set-TkCardLoading -Name 'SystemFirmware' -Loading $false
        }

    Invoke-TkBackgroundAction -StatusText 'Reading the operating system...' `
        -ScriptBlock { Get-TkOperatingSystemInfo } `
        -OnComplete {
            param($result)

            $part = @($result.Output) | Select-Object -First 1

            if ($part) {
                $script:TkSystemSnapshot.OS = $part
            }

            Write-TkSystemOs -OS $script:TkSystemSnapshot.OS
            Set-TkCardLoading -Name 'SystemOs' -Loading $false
        }

    Invoke-TkBackgroundAction -StatusText 'Reading processors, memory, disks and volumes...' `
        -ScriptBlock {
            [pscustomobject] @{
                Hardware = Get-TkHardwareInfo
                Volumes  = @(Get-TkVolumeUsage)
            }
        } `
        -OnComplete {
            param($result)

            $part = @($result.Output) | Select-Object -First 1

            if ($part) {
                $script:TkSystemSnapshot.Hardware = $part.Hardware
                $script:TkSystemSnapshot.Volumes  = @($part.Volumes)
            }

            Write-TkSystemHardware -Hardware $script:TkSystemSnapshot.Hardware -Volume @($script:TkSystemSnapshot.Volumes)
            Set-TkCardLoading -Name 'SystemHardware' -Loading $false
        }

    Invoke-TkBackgroundAction -StatusText 'Reading the platform security...' `
        -ScriptBlock { Get-TkPlatformSecurityInfo } `
        -OnComplete {
            param($result)

            $part = @($result.Output) | Select-Object -First 1

            if ($part) {
                $script:TkSystemSnapshot.Security = $part
            }

            Write-TkSystemSecurity -Security $script:TkSystemSnapshot.Security
            Set-TkCardLoading -Name 'SystemSecurity' -Loading $false
        }
}

<#
.SYNOPSIS
    Writes a whole inventory snapshot at once, for a console session or a
    render.

.PARAMETER Snapshot
    Anything with Identity, Bios, OS, Hardware, Volumes and Security.
#>
function Write-TkSystemPageFields {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        $Snapshot
    )

    Write-TkSystemIdentity -Identity $Snapshot.Identity -Bios $Snapshot.Bios
    Write-TkSystemOs       -OS $Snapshot.OS
    Write-TkSystemHardware -Hardware $Snapshot.Hardware -Volume @($Snapshot.Volumes)
    Write-TkSystemSecurity -Security $Snapshot.Security

    foreach ($card in @('SystemIdentity', 'SystemFirmware', 'SystemOs', 'SystemHardware', 'SystemSecurity')) {
        Set-TkCardLoading -Name $card -Loading $false
    }
}

<#
.SYNOPSIS
    Writes a placeholder into fields whose part could not be read.

.PARAMETER Name
    Control names.
#>
function Set-TkSystemFieldsUnavailable {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string[]] $Name
    )

    $field = @{}

    foreach ($item in $Name) {
        $field[$item] = 'Not available'
    }

    Set-TkFieldText -Field $field
}

<#
.SYNOPSIS
    Fills the Identity and Firmware cards, and the buttons that depend on them.

.PARAMETER Identity
    Output of Get-TkMachineIdentity, or null.

.PARAMETER Bios
    Output of Get-TkBiosStatus, or null.
#>
function Write-TkSystemIdentity {
    [CmdletBinding()]
    param(
        [Parameter()]
        $Identity,

        [Parameter()]
        $Bios
    )

    if ($Identity) {

        Set-TkFieldText -Field @{
            'ValManufacturer' = $Identity.Manufacturer
            'ValModel'        = $Identity.Model
            'ValSerial'       = $Identity.SerialNumber
            'ValAssetTag'     = $Identity.AssetTag
            'ValChassis'      = if ($Identity.IsVirtual) { '{0} (virtual machine)' -f $Identity.ChassisType }
                                else { $Identity.ChassisType }
            'ValBoard'        = $Identity.BaseBoard
            'ValDomain'       = if ($Identity.PartOfDomain) { '{0} (joined)' -f $Identity.Domain }
                                else { '{0} (workgroup)' -f $Identity.Domain }
            'ValUser'         = $Identity.LoggedOnUser
        }
    }
    else {
        Set-TkSystemFieldsUnavailable -Name @('ValManufacturer', 'ValModel', 'ValSerial', 'ValAssetTag',
                                              'ValChassis', 'ValBoard', 'ValDomain', 'ValUser')
    }

    if ($Bios) {

        Set-TkFieldText -Field @{
            'ValBiosVendor'  = $Bios.Vendor
            'ValBiosVersion' = $Bios.Version
            'ValBiosDate'    = $Bios.ReleaseDate
            'ValBiosAge'     = if ($null -ne $Bios.AgeDays) { '{0} days' -f $Bios.AgeDays } else { 'Unknown' }
            'ValBiosAdvice'  = $Bios.Recommendation
        }
    }
    else {
        Set-TkSystemFieldsUnavailable -Name @('ValBiosVendor', 'ValBiosVersion', 'ValBiosDate', 'ValBiosAge')
    }

    # A board that never recorded a serial number reports the placeholder.
    # Copying it would put the words "Not available" on the clipboard, and a
    # warranty lookup would search for them, so both buttons stand down. They
    # start disabled in the markup for the same reason, until this has run.
    $hasSerial = ($null -ne $Identity) -and
                 -not [string]::IsNullOrWhiteSpace($Identity.SerialNumber) -and
                 $Identity.SerialNumber -ne (Format-TkValue $null)

    foreach ($name in @('BtnCopySerial', 'BtnVendorWarranty')) {

        $button = Get-TkControl -Name $name

        if ($button) {
            $button.IsEnabled = $hasSerial
        }
    }

    Update-TkVendorToolButton -Identity $Identity
}

<#
.SYNOPSIS
    Fills the Operating system card.

.PARAMETER OS
    Output of Get-TkOperatingSystemInfo, or null.
#>
function Write-TkSystemOs {
    [CmdletBinding()]
    param(
        [Parameter()]
        $OS
    )

    if ($null -eq $OS) {
        Set-TkSystemFieldsUnavailable -Name @('ValOsCaption', 'ValOsVersion', 'ValOsBuild', 'ValActivation',
                                              'ValInstalled', 'ValUptime', 'ValTimeZone', 'ValPowerShell')
        return
    }

    Set-TkFieldText -Field @{
        'ValOsCaption'  = $OS.Caption
        'ValOsVersion'  = $OS.DisplayVersion
        'ValOsBuild'    = $OS.Build
        'ValActivation' = $OS.Activation
        'ValInstalled'  = if ($OS.InstallDate) { ([datetime] $OS.InstallDate).ToString('yyyy-MM-dd') } else { 'Unknown' }
        'ValUptime'     = $OS.UptimeText
        'ValTimeZone'   = $OS.TimeZone
        'ValPowerShell' = $OS.PowerShell
    }
}

<#
.SYNOPSIS
    Fills the Hardware card: processors, memory, graphics, volumes and disks.

.PARAMETER Hardware
    Output of Get-TkHardwareInfo, or null.

.PARAMETER Volume
    Output of Get-TkVolumeUsage.
#>
function Write-TkSystemHardware {
    [CmdletBinding()]
    param(
        [Parameter()]
        $Hardware,

        [Parameter()]
        [AllowEmptyCollection()]
        [object[]] $Volume = @()
    )

    if ($Hardware) {

        Set-TkFieldText -Field @{
            'ValCpu'    = $Hardware.CpuName
            'ValCores'  = '{0} cores / {1} threads' -f $Hardware.CpuCores, $Hardware.CpuThreads
            'ValMemory' = '{0} in {1} module(s)' -f $Hardware.TotalMemory, @($Hardware.MemoryModules).Count
            'ValGpu'    = (@($Hardware.Graphics | ForEach-Object { $_.Name }) -join ', ')
        }
    }
    else {
        Set-TkSystemFieldsUnavailable -Name @('ValCpu', 'ValCores', 'ValMemory', 'ValGpu')
    }

    Write-TkSystemVolumeList -Volume $Volume

    Set-TkObjectTable -ControlName 'DocDisks' -InputObject @(if ($Hardware) { $Hardware.Disks }) `
        -Property @('Name', 'Size', 'MediaType', 'BusType', 'Health') `
        -Column   @('Model', 'Size', 'Type', 'Bus', 'Health') `
        -Weight   @(3.0, 1.0, 0.9, 0.9, 0.9) `
        -EmptyText 'No physical disk was returned.'
}

<#
.SYNOPSIS
    Fills the Platform security card.

.PARAMETER Security
    Output of Get-TkPlatformSecurityInfo, or null.
#>
function Write-TkSystemSecurity {
    [CmdletBinding()]
    param(
        [Parameter()]
        $Security
    )

    if ($null -eq $Security) {
        Set-TkSystemFieldsUnavailable -Name @('ValSecureBoot', 'ValTpm', 'ValBitLocker', 'ValFirewall',
                                              'ValAntivirus', 'ValDefender')
        return
    }

    Set-TkFieldText -Field @{
        'ValSecureBoot' = $Security.SecureBoot
        'ValTpm'        = $Security.Tpm
        'ValBitLocker'  = $Security.BitLocker
        'ValFirewall'   = $Security.Firewall
        'ValAntivirus'  = $Security.Antivirus
        'ValDefender'   = $Security.Defender
    }
}

<#
.SYNOPSIS
    Draws one row per fixed volume: its name, its figures and a fill bar.

.DESCRIPTION
    Every volume at once, the system drive first. The earlier selector showed
    one drive at a time, and the one filling up was rarely the one selected.

.PARAMETER Volume
    Output of Get-TkVolumeUsage.
#>
function Write-TkSystemVolumeList {
    [CmdletBinding()]
    param(
        [Parameter()]
        [AllowEmptyCollection()]
        [AllowNull()]
        [object[]] $Volume = @()
    )

    $list = Get-TkControl -Name 'SystemVolumeList'

    if ($null -eq $list) {
        return
    }

    $list.Children.Clear()

    $volumes = @(Get-TkVolumeDisplayOrder -Volume @($Volume))

    if ($volumes.Count -eq 0) {

        $empty = New-Object System.Windows.Controls.TextBlock
        $empty.Text = 'No fixed volume was returned.'
        $empty.SetResourceReference([System.Windows.Controls.TextBlock]::StyleProperty, 'Muted')

        [void] $list.Children.Add($empty)
        return
    }

    foreach ($item in $volumes) {
        [void] $list.Children.Add((New-TkVolumeRow -Volume $item))
    }
}

<#
.SYNOPSIS
    Builds the row for one volume.

.PARAMETER Volume
    One record from Get-TkVolumeUsage.
#>
function New-TkVolumeRow {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [pscustomobject] $Volume
    )

    $row = New-Object System.Windows.Controls.StackPanel
    $row.Margin = New-Object System.Windows.Thickness(0, 0, 0, 12)

    # --- Name on the left, figures on the right ----------------------------
    $header = New-Object System.Windows.Controls.DockPanel
    $header.LastChildFill = $true

    # A whole percentage: formatted in the local culture, a decimal reads
    # 46,6 on a French Windows beside sizes printed as 1.99 TB.
    $figures = New-Object System.Windows.Controls.TextBlock
    $figures.Text              = '{0}% used, {1} free of {2}' -f [math]::Round($Volume.UsedPercent), $Volume.Free, $Volume.Size
    $figures.FontSize          = 12
    $figures.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $figures.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, 'TextMuted')

    [System.Windows.Controls.DockPanel]::SetDock($figures, [System.Windows.Controls.Dock]::Right)

    $role = if ([string] $Volume.Drive -eq $env:SystemDrive) { ', system drive' } else { '' }

    $name = New-Object System.Windows.Controls.TextBlock
    $name.Text              = '{0}  {1}, {2}{3}' -f $Volume.Drive, $Volume.Label, $Volume.FileSystem, $role
    $name.FontSize          = 13
    $name.FontWeight        = [System.Windows.FontWeights]::SemiBold
    $name.VerticalAlignment = [System.Windows.VerticalAlignment]::Center
    $name.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, 'TextPrimary')

    [void] $header.Children.Add($figures)
    [void] $header.Children.Add($name)
    [void] $row.Children.Add($header)

    # --- The bar -----------------------------------------------------------
    $bar = New-TkUsageBar -Percent ([double] $Volume.UsedPercent) -Severity $Volume.Severity -Height 8
    $bar.Margin = New-Object System.Windows.Thickness(0, 6, 0, 0)

    [void] $row.Children.Add($bar)

    # --- What a warning means, in the colour of the warning ------------------
    if ($Volume.Note) {

        $note = New-Object System.Windows.Controls.TextBlock
        $note.Text         = $Volume.Note
        $note.FontSize     = 11
        $note.TextWrapping = [System.Windows.TextWrapping]::Wrap
        $note.Margin       = New-Object System.Windows.Thickness(0, 4, 0, 0)
        $note.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty,
            (Get-TkSeverityBrushKey -Severity $Volume.Severity))

        [void] $row.Children.Add($note)
    }

    return $row
}

<#
.SYNOPSIS
    Shows the firmware utility button only when the catalog knows one.

.DESCRIPTION
    A button that answers "no utility is known for this manufacturer" after
    being pressed is a button that should not have been there. The hint beside
    it says what happens either way.

.PARAMETER Identity
    The machine identity from the inventory.
#>
function Update-TkVendorToolButton {
    [CmdletBinding()]
    param(
        [Parameter()]
        $Identity
    )

    $vendor = if ($Identity) { Get-TkVendorProfile -Manufacturer $Identity.Manufacturer } else { $null }
    $known  = ($null -ne $vendor -and -not [string]::IsNullOrWhiteSpace($vendor.updateToolPackage))

    $button = Get-TkControl -Name 'BtnVendorTool'

    if ($button) {

        $button.Visibility = if ($known) { [System.Windows.Visibility]::Visible }
                             else { [System.Windows.Visibility]::Collapsed }

        if ($known) {
            $button.Content = 'Install {0}' -f $vendor.updateToolName
        }
    }

    $hint = Get-TkControl -Name 'ValVendorToolHint'

    if ($hint) {
        $hint.Text = if ($known) {
                         'The toolkit never flashes firmware itself: it installs {0}, which takes over from there.' -f $vendor.updateToolName
                     }
                     else {
                         'No firmware utility is known for this manufacturer. The support site, beside the manufacturer above, has the downloads.'
                     }
    }
}

<#
.SYNOPSIS
    Asks for a destination and writes the inventory report.
#>
function Export-TkSystemReportFromUi {
    [CmdletBinding()]
    param()

    $dialog = New-Object Microsoft.Win32.SaveFileDialog
    $dialog.Title      = 'Export the system report'
    $dialog.Filter     = 'JSON report (*.json)|*.json|Text report (*.txt)|*.txt'
    $dialog.FileName   = '{0}-inventory-{1}.json' -f $env:COMPUTERNAME, (Get-Date -Format 'yyyyMMdd')

    if (-not $dialog.ShowDialog()) {
        return
    }

    $path   = $dialog.FileName
    $format = if ($path -like '*.txt') { 'Text' } else { 'Json' }

    $written = Export-TkSystemReport -Path $path -Format $format -Confirm:$false

    if ($written) {
        Set-TkStatus -Text ('Report written to {0}' -f $written)
    }
    else {
        Set-TkStatus -Text 'The report could not be written.'
    }
}


# ==========================================================================
# Source: src/UI/Pages/SoftwarePage.ps1
# ==========================================================================

<#
    Toolkit - UI / Software page

    Renders the application catalog with a search box and a category filter,
    and drives winget in the background.

    Filtering uses the collection view rather than rebuilding the item source,
    so a selection made before typing in the search box survives the filter.
#>

$script:TkApplicationItems = $null
$script:TkApplicationView  = $null

# Path geometries are parsed once and reused. Parsing is the expensive part,
# and the list rebuilds its items on every filter change.
$script:TkAppIconCache = $null

<#
.SYNOPSIS
    Returns the brand icon for a package, or nothing when there is none.

.DESCRIPTION
    Real publisher icons, drawn as vector outlines rather than bitmaps. An
    outline is a few hundred characters of path data, so the whole set costs
    about ninety kilobytes in the single file build, and it stays sharp at
    any scale and on any display. A set of bitmaps would be several megabytes
    for a worse result.

    They are drawn in one colour on the category tile rather than in the
    brand colours. That is a deliberate choice: a hundred and forty brand
    palettes cannot all stay legible against both themes, and a consistent
    silhouette reads faster in a long list than a wall of competing colours.

    The catalogue is deliberately incomplete. Simple Icons carries no icon
    for most Windows utilities, so roughly a third of the applications have
    none. Those fall back to the icon for their category, which is why this
    returns nothing rather than a placeholder.

.OUTPUTS
    System.Windows.Media.Geometry, or $null.
#>
function Get-TkAppIconGeometry {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string] $PackageId
    )

    if ([string]::IsNullOrWhiteSpace($PackageId)) {
        return $null
    }

    if ($null -eq $script:TkAppIconCache) {

        $script:TkAppIconCache = @{}

        $catalog = Import-TkCatalog -Name 'app-icons'

        if ($catalog -and $catalog.icons) {

            foreach ($entry in $catalog.icons.PSObject.Properties) {

                try {
                    $geometry = [System.Windows.Media.Geometry]::Parse($entry.Value.path)

                    # Frozen so the same geometry can be shared by every
                    # element that draws it, across threads, without copying.
                    $geometry.Freeze()

                    $script:TkAppIconCache[$entry.Name] = $geometry
                }
                catch {
                    Write-TkLog -Level Warning -Category 'UI' -Message (
                        'The icon for {0} could not be parsed and was skipped: {1}' -f
                            $entry.Name, $_.Exception.Message
                    )
                }
            }
        }
    }

    if ($script:TkAppIconCache.ContainsKey($PackageId)) {
        return $script:TkAppIconCache[$PackageId]
    }

    return $null
}

<#
.SYNOPSIS
    Returns the icon character shown on an application tile.

.DESCRIPTION
    The fallback for an application with no brand icon, and the icon used
    everywhere outside the software list. Drawn from the Windows icon font,
    which costs nothing to ship: it is part of the operating system, so there
    is no file to bundle and nothing to download.

    This one says what kind of application it is rather than which one, and
    the tile colour separates the categories. Where a real publisher icon
    exists, Get-TkAppIconGeometry supplies it instead.

    Every code point below was chosen by rendering the font and looking at
    it. An unverified one draws an empty box.

.OUTPUTS
    System.String
#>
function Get-TkCategoryGlyph {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string] $Key
    )

    $glyphs = @{
        'browsers'      = 0xE774  # globe
        'communication' = 0xE8BD  # speech bubble
        'documents'     = 0xE8A5  # page
        'development'   = 0xE943  # braces
        'games'         = 0xE7FC  # game controller
        'microsoft'     = 0xECAA  # window panes
        'multimedia'    = 0xEC4F  # note
        'protools'      = 0xE719  # briefcase
        'networking'    = 0xEC05  # antenna
        'security'      = 0xEA18  # shield
        'selfhosted'    = 0xE968  # server
        'utilities'     = 0xEC7A  # crossed tools
    }

    $point = if ($Key -and $glyphs.ContainsKey($Key)) { $glyphs[$Key] } else { 0xECA5 }

    return [string] [char] $point
}

<#
.SYNOPSIS
    Returns the tile colour for a category.

.DESCRIPTION
    One colour per category, so the eye can group a filtered list without
    reading it. Deliberately fixed rather than themed: these are identity
    colours, and they have to stay recognisable in both palettes. Every one is
    dark enough to carry a white glyph.

.OUTPUTS
    System.Windows.Media.SolidColorBrush
#>
function Get-TkTileBrush {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string] $Key
    )

    $palette = @{
        'browsers'      = '#2F6FD0'
        'communication' = '#2E8B7A'
        'documents'     = '#8A5AA8'
        'development'   = '#3B6EA5'
        'games'         = '#A8484F'
        'microsoft'     = '#2C7BB6'
        'multimedia'    = '#B06A2C'
        'protools'      = '#5B6B8C'
        'networking'    = '#2E7D6B'
        'security'      = '#9B3B4A'
        'selfhosted'    = '#4A7A46'
        'utilities'     = '#6B6B7B'

        # Used by the Tweaks and Fixes lists, which share the tile.
        'tweak'         = '#4A5A8C'
        'fix-low'       = '#4A7A46'
        'fix-medium'    = '#B06A2C'
        'fix-high'      = '#9B3B4A'
    }

    $colour = if ($Key -and $palette.ContainsKey($Key)) { $palette[$Key] } else { '#5B6B8C' }

    $converter = New-Object System.Windows.Media.BrushConverter
    $brush     = $converter.ConvertFromString($colour)

    $brush.Freeze()

    return $brush
}

<#
.SYNOPSIS
    Wires the Software page and loads the catalog.
#>
function Initialize-TkSoftwarePage {
    [CmdletBinding()]
    param()

    $catalog = Import-TkCatalog -Name 'applications'

    if (-not $catalog) {
        Set-TkOutput -ControlName 'WingetStatusText' -Text 'The application catalog could not be loaded.'
        return
    }

    # --- Item source ------------------------------------------------------
    $items = New-Object 'System.Collections.ObjectModel.ObservableCollection[object]'

    $categoryNames = @{}

    foreach ($category in $catalog.categories) {
        $categoryNames[$category.id] = $category.name
    }

    foreach ($application in $catalog.applications) {

        $iconGeometry = Get-TkAppIconGeometry -PackageId $application.packageId

        $items.Add([pscustomobject]@{
            IsSelected   = $false
            Id           = $application.id
            Name         = $application.name
            Description  = $application.description
            PackageId    = $application.packageId
            Category     = $application.category
            CategoryName = $categoryNames[$application.category]
            StateText    = ''

            # The real publisher icon where one exists, and the icon for the
            # category where it does not. The template shows whichever of the
            # two is present, so both have to be here.
            IconGeometry = $iconGeometry
            HasIcon      = ($null -ne $iconGeometry)
            Glyph        = Get-TkCategoryGlyph -Key $application.category
            TileBrush    = Get-TkTileBrush     -Key $application.category
        })
    }

    $script:TkApplicationItems = $items

    $list = Get-TkControl -Name 'SoftwareList'

    if ($list) {
        $list.ItemsSource = $items
    }

    $script:TkApplicationView = [System.Windows.Data.CollectionViewSource]::GetDefaultView($items)
    $script:TkApplicationView.Filter = [Predicate[object]] {
        param($item)
        Test-TkApplicationVisible -Item $item
    }

    # --- Category filter --------------------------------------------------
    $combo = Get-TkControl -Name 'SoftwareCategory'

    if ($combo) {

        [void] $combo.Items.Add('All categories')

        foreach ($category in ($catalog.categories | Sort-Object -Property name)) {
            [void] $combo.Items.Add($category.name)
        }

        $combo.SelectedIndex = 0
        $combo.Add_SelectionChanged({ $script:TkApplicationView.Refresh() })
    }

    $search = Get-TkControl -Name 'SoftwareSearch'

    if ($search) {
        $search.Add_TextChanged({ $script:TkApplicationView.Refresh() })
    }

    # --- Actions ----------------------------------------------------------
    Register-TkClick -Name 'BtnInstallSelected'   -Action { Invoke-TkSoftwareAction -Action 'Install' }
    Register-TkClick -Name 'BtnUninstallSelected' -Action { Invoke-TkSoftwareAction -Action 'Uninstall' }
    Register-TkClick -Name 'BtnRefreshInstalled'  -Action { Update-TkInstalledState }
    Register-TkClick -Name 'BtnUpgradeAll'        -Action { Invoke-TkUpgradeAll }

    Register-TkClick -Name 'BtnClearSelection' -Action {

        foreach ($item in $script:TkApplicationItems) {
            $item.IsSelected = $false
        }

        $script:TkApplicationView.Refresh()
        Set-TkStatus -Text 'Selection cleared.'
    }

    # Two columns when the window is wide enough for two.
    if ($list) {
        $list.Add_SizeChanged({ Update-TkSoftwareColumns })
    }

    # Read what is already on the machine the first time the page is opened.
    # Without this the list claims every application is available until
    # somebody presses Refresh, which is a wrong answer rather than a missing
    # one.
    Register-TkFirstShow -PageName 'Software' -Action { Update-TkInstalledState }

    Update-TkWingetStatusText
}

<#
.SYNOPSIS
    Sets the application list to one or two columns for the current width.

.DESCRIPTION
    Two columns halve the scrolling through a hundred and forty entries, but
    only while each card still has room for a name and a line of description.
    Below the threshold the second column would turn both into ellipses, so
    the list drops back to one.

    The panel is found through the visual tree because it is declared in an
    ItemsPanelTemplate and so has no name the window can resolve.
#>
function Update-TkSoftwareColumns {
    [CmdletBinding()]
    param()

    $list = Get-TkControl -Name 'SoftwareList'

    if ($null -eq $list) {
        return
    }

    $panel = Find-TkVisualChild -Parent $list -TypeName 'UniformGrid'

    if ($null -eq $panel) {
        return
    }

    # Measured against the card contents: below this a two column card cannot
    # show a description without trimming it to nothing.
    $columns = if ($list.ActualWidth -ge 860) { 2 } else { 1 }

    if ($panel.Columns -ne $columns) {
        $panel.Columns = $columns
    }
}

<#
.SYNOPSIS
    Decides whether a catalog entry passes the current filters.

.OUTPUTS
    System.Boolean
#>
function Test-TkApplicationVisible {
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [Parameter(Mandatory)]
        $Item
    )

    # A selected item stays visible whatever the filter, so the user can see
    # what is about to be installed.
    if ($Item.IsSelected) {
        return $true
    }

    $combo = Get-TkControl -Name 'SoftwareCategory'

    if ($combo -and $combo.SelectedIndex -gt 0) {

        if ($Item.CategoryName -ne [string] $combo.SelectedItem) {
            return $false
        }
    }

    $search = Get-TkControl -Name 'SoftwareSearch'

    if ($search -and -not [string]::IsNullOrWhiteSpace($search.Text)) {

        $term = $search.Text.Trim()

        $haystack = '{0} {1} {2}' -f $Item.Name, $Item.Description, $Item.PackageId

        if ($haystack -notlike ('*{0}*' -f $term)) {
            return $false
        }
    }

    return $true
}

<#
.SYNOPSIS
    Reports whether winget is usable, in the page header.
#>
function Update-TkWingetStatusText {
    [CmdletBinding()]
    param()

    Invoke-TkBackgroundAction -StatusText 'Checking winget...' `
        -ScriptBlock { Get-TkWingetStatus } `
        -OnComplete {
            param($result)

            $status  = @($result.Output) | Select-Object -First 1
            $control = Get-TkControl -Name 'WingetStatusText'

            if (-not $control -or -not $status) {
                return
            }

            if ($status.Available) {
                $control.Text = 'winget {0} - installs come from the official Microsoft source only.' -f $status.Version
            }
            else {
                $control.Text = $status.Message
            }
        }
}

<#
.SYNOPSIS
    Installs or removes the selected applications.

.PARAMETER Action
    Install or Uninstall.
#>
function Invoke-TkSoftwareAction {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [ValidateSet('Install', 'Uninstall')]
        [string] $Action
    )

    $selected = @($script:TkApplicationItems | Where-Object { $_.IsSelected })

    if ($selected.Count -eq 0) {
        Set-TkStatus -Text 'Nothing is selected.'
        return
    }

    # The warning used to say the opposite, that installs need elevation and
    # will fail without it. That is not how winget works: it is meant to run
    # as the signed in user, Windows raises its own prompt for an installer
    # that needs rights, and a package that installs into the user profile
    # needs none at all. Requiring elevation only hid those prompts and shut
    # standard users out of installs they were entitled to make.
    if (Test-TkIsElevated) {

        Write-TkLog -Level Information -Category 'Software' -Message (
            'Installing from an elevated instance, so Windows will not prompt for rights. ' +
            'Anything installed now goes in machine wide where the package allows it.'
        )
    }

    $names = ($selected | ForEach-Object { $_.Name }) -join ', '

    $confirmed = Confirm-TkAction -Title ('{0} {1} application(s)' -f $Action, $selected.Count) -Message (
        "{0}:`n`n{1}`n`nContinue?" -f $Action, $names
    )

    if (-not $confirmed) {
        return
    }

    $packageIds = @($selected | ForEach-Object { $_.PackageId })

    # Named parameters, not a positional list: a positional @($ids, $verb) is
    # flattened by PowerShell into one argument per identifier followed by the
    # verb, and the script block then binds a single identifier to $ids.
    Invoke-TkBackgroundAction -StatusText ('{0}ing {1} application(s)...' -f $Action, $packageIds.Count) `
        -ParameterList @{ ids = $packageIds; verb = $Action } `
        -ScriptBlock {
            param($ids, $verb)

            $results = @()

            foreach ($id in $ids) {

                if ($verb -eq 'Install') {
                    $ok = Install-TkWingetPackage -PackageId $id -Confirm:$false
                }
                else {
                    $ok = Uninstall-TkWingetPackage -PackageId $id -Confirm:$false
                }

                $results += [pscustomobject]@{ PackageId = $id; Success = $ok }
            }

            return $results
        } `
        -OnComplete {
            param($result)

            $rows      = @($result.Output)
            $succeeded = @($rows | Where-Object { $_.Success }).Count

            Set-TkStatus -Text ('{0} of {1} package(s) completed successfully.' -f $succeeded, $rows.Count)

            Update-TkInstalledState
        }
}

<#
.SYNOPSIS
    Upgrades every package winget reports as upgradable.
#>
function Invoke-TkUpgradeAll {
    [CmdletBinding()]
    param()

    $confirmed = Confirm-TkAction -Title 'Upgrade everything' -Message (
        "Upgrade every package winget reports as out of date?`n`nThis can restart applications and takes a while on a machine that has not been updated recently."
    )

    if (-not $confirmed) {
        return
    }

    Invoke-TkBackgroundAction -StatusText 'Upgrading packages...' `
        -ScriptBlock {

            $upgradable = Get-TkUpgradablePackage

            if ($upgradable.Count -eq 0) {
                return 'Everything is up to date.'
            }

            $results = Install-TkPackageBatch -PackageId @($upgradable | ForEach-Object { $_.Id }) -Confirm:$false

            return ('{0} of {1} package(s) upgraded.' -f
                @($results | Where-Object { $_.Success }).Count, $results.Count)
        } `
        -OnComplete {
            param($result)

            Set-TkStatus -Text ([string] (@($result.Output) | Select-Object -Last 1))
            Update-TkInstalledState
        }
}

<#
.SYNOPSIS
    Marks catalog entries that are already installed.
#>
function Update-TkInstalledState {
    [CmdletBinding()]
    param()

    Invoke-TkBackgroundAction -StatusText 'Reading installed packages...' `
        -ScriptBlock {

            # HashSet does not survive the runspace boundary well; return a
            # plain array and rebuild the lookup on the UI thread.
            return @(Get-TkInstalledPackageId)
        } `
        -OnComplete {
            param($result)

            $installed = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)

            foreach ($id in @($result.Output)) {

                if ($id) {
                    [void] $installed.Add([string] $id)
                }
            }

            foreach ($item in $script:TkApplicationItems) {

                $item.StateText = if ($installed.Contains($item.PackageId)) { 'Installed' } else { '' }
            }

            # ItemsSource is reassigned because the item objects do not raise
            # change notifications on their own.
            $list = Get-TkControl -Name 'SoftwareList'

            if ($list) {
                $list.Items.Refresh()
            }

            Set-TkStatus -Text ('{0} installed package(s) detected.' -f $installed.Count)
        }
}


