<#
.SYNOPSIS
    Shows the devices Device Manager flags.
#>
function Show-TkDeviceReport {
    [CmdletBinding()]
    param()

    Invoke-TkBackgroundAction -StatusText 'Reading the devices...' `
        -ScriptBlock { Get-TkDeviceProblem } `
        -OnComplete {
            param($result)

            $rows = @($result.Output | Where-Object { $_ })
            Set-TkLastDiagnostic -Name 'devices' -Data $rows

            $document = New-TkFlowDocument

            Add-TkHeading   -Document $document -Text 'Devices' -Level 1
            Add-TkParagraph -Document $document -Muted -Text (
                '"My headset does not work" is a device with a problem code far more often than anything the user can describe. Each code says a different thing: a missing driver, a device Windows stopped, one waiting for a restart.'
            )

            if ($rows.Count -eq 0) {
                Add-TkSeverityLine -Document $document -Severity 'Pass' -Heading 'No device reports a problem'
            }

            foreach ($row in $rows) {

                # Informational codes, such as a device disabled on purpose,
                # need no button.
                $remediation = if ($row.Severity -ne 'Info') { 'open-device-manager' } else { '' }

                Add-TkSeverityLine -Document $document -Severity $row.Severity -Heading $row.Name `
                    -Detail ('Code {0}' -f $row.Code) `
                    -Note ((@($row.Meaning, $row.Hint) | Where-Object { $_ }) -join ' ') `
                    -Action $row.Action -RemediationId $remediation
            }

            if ($rows.Count -gt 0) {

                Add-TkHeading -Document $document -Text 'Identifiers' -Level 2
                Add-TkParagraph -Document $document -Muted -Text (
                    'The hardware identifier is what to search for on the manufacturer site when a driver is missing: VEN or VID is the vendor, DEV or PID the product.'
                )

                Add-TkTable -Document $document -Column @('Device', 'Code', 'Class', 'Hardware identifier') `
                    -Weight @(1.8, 0.5, 0.7, 2.2) `
                    -Row @($rows | ForEach-Object { , @($_.Name, [string] $_.Code, $_.Class, $_.DeviceId) })
            }

            Set-TkDocument -ControlName 'DiagnosticsOutput' -Document $document
        }
}

<#
.SYNOPSIS
    Shows whether the machine is waiting for a restart.
#>
function Show-TkRebootStatus {
    [CmdletBinding()]
    param()

    Invoke-TkBackgroundAction -StatusText 'Checking for a pending reboot...' `
        -ScriptBlock { Get-TkPendingRebootStatus } `
        -OnComplete {
            param($result)

            $status = @($result.Output) | Select-Object -First 1

            Set-TkLastDiagnostic -Name 'pending-reboot' -Data $status

            $document = New-TkFlowDocument

            Add-TkHeading -Document $document -Text 'Pending reboot' -Level 1

            Add-TkSeverityLine -Document $document `
                -Severity $(if ($status.Pending) { 'Warning' } else { 'Pass' }) `
                -Heading $(if ($status.Pending) { 'A restart is pending' } else { 'No restart pending' }) `
                -Detail ('up {0}' -f $status.Uptime) `
                -Note 'Windows records a pending reboot in several unrelated places and no single one is authoritative, which is why "have you restarted it" so often produces "yes" and no improvement.'

            foreach ($reason in $status.Reasons) {
                Add-TkSeverityLine -Document $document -Severity 'Info' -Heading $reason
            }

            Set-TkDocument -ControlName 'DiagnosticsOutput' -Document $document
        }
}

<#
.SYNOPSIS
    Shows what the machine is doing, what starts with it, and how long start
    up takes.
#>
function Show-TkPerformanceReport {
    [CmdletBinding()]
    param()

    Invoke-TkBackgroundAction -StatusText 'Measuring what the machine is doing...' `
        -ScriptBlock {
            [pscustomobject] @{
                Snapshot = Get-TkPerformanceSnapshot
                Startup  = @(Get-TkStartupProgram)
                Boot     = Get-TkBootPerformance -Days 30
            }
        } `
        -OnComplete {
            param($result)

            $report = @($result.Output) | Where-Object { $_ -and $_.PSObject.Properties['Snapshot'] } | Select-Object -First 1

            if (-not $report) {
                return
            }

            Set-TkLastDiagnostic -Name 'performance' -Data $report

            $document = New-TkFlowDocument

            Add-TkHeading   -Document $document -Text 'Performance' -Level 1
            Add-TkParagraph -Document $document -Muted -Text (
                '"The machine is slow" has an answer once it is split up: what is using the processor, the memory and the disks right now, what starts with Windows, and how long start up takes and what slows it.'
            )

            foreach ($finding in @(Get-TkPerformanceFinding -Snapshot $report.Snapshot -Startup @($report.Startup) -Boot $report.Boot)) {
                Add-TkSeverityLine -Document $document -Severity $finding.Severity -Heading $finding.Heading `
                    -Detail $finding.Detail -Note $finding.Note
            }

            $applications = @($report.Snapshot.Applications | Sort-Object -Property @{ Expression = 'CpuPercent'; Descending = $true },
                                                                                   @{ Expression = 'MemoryMB'; Descending = $true } |
                              Select-Object -First 12)

            if ($applications.Count -gt 0) {

                Add-TkHeading -Document $document -Text 'Applications using the most right now' -Level 2

                Add-TkTable -Document $document -Column @('Application', 'Processes', 'CPU %', 'Memory MB', 'Disk KB/s') `
                    -Weight @(2.2, 0.8, 0.7, 0.9, 0.9) `
                    -Row @($applications | ForEach-Object {
                        , @($_.Name, [string] $_.Instances, [string] $_.CpuPercent, [string] $_.MemoryMB, [string] $_.IoKBps)
                    })
            }

            $startup = @($report.Startup | Where-Object { $_ })

            if ($startup.Count -gt 0) {

                Add-TkHeading -Document $document -Text 'Programs that start with Windows' -Level 2

                Add-TkTable -Document $document -Column @('Program', 'For', 'State', 'Command') `
                    -Weight @(1.6, 0.8, 0.7, 3.0) `
                    -Row @($startup | ForEach-Object {
                        , @($_.Name, $_.Scope, $(if ($_.Enabled) { 'Runs' } else { 'Disabled' }), $_.Command)
                    })
            }

            Set-TkDocument -ControlName 'DiagnosticsOutput' -Document $document
        }
}

<#
.SYNOPSIS
    Shows the Wi-Fi connection: signal, band, rate, security and drops.
#>
function Show-TkWifiReport {
    [CmdletBinding()]
    param()

    Invoke-TkBackgroundAction -StatusText 'Reading the Wi-Fi connection...' `
        -ScriptBlock { Get-TkWifiStatus -Days 7 } `
        -OnComplete {
            param($result)

            $status = @($result.Output) | Where-Object { $_ -and $_.PSObject.Properties['Interfaces'] } | Select-Object -First 1

            if (-not $status) {
                return
            }

            Set-TkLastDiagnostic -Name 'wifi' -Data $status

            $document = New-TkFlowDocument

            Add-TkHeading   -Document $document -Text 'Wi-Fi' -Level 1
            Add-TkParagraph -Document $document -Muted -Text (
                '"The Wi-Fi is bad" covers causes that look alike from the chair: a weak signal, a crowded 2.4 GHz channel, a low link rate, an old standard, or a connection that keeps dropping. Read from the Wi-Fi API rather than netsh, so the display language does not matter.'
            )

            foreach ($finding in @(Get-TkWifiFinding -Status $status)) {
                Add-TkSeverityLine -Document $document -Severity $finding.Severity -Heading $finding.Heading `
                    -Detail $finding.Detail -Note $finding.Note -RemediationId $finding.RemediationId
            }

            foreach ($adapter in @($status.Interfaces | Where-Object { $_ })) {

                $connected = if ($adapter.Connection) { $adapter.Connection.Bssid } else { '' }
                $networks  = @($adapter.Networks | Sort-Object -Property Rssi -Descending | Select-Object -First 20)

                if ($networks.Count -gt 0) {

                    Add-TkHeading -Document $document -Text 'Networks in range' -Level 2
                    Add-TkParagraph -Document $document -Muted -Text (
                        'As last seen by the adapter. Above -67 dBm is good for calls, below -80 dBm is barely usable. Several rows with one name are the bands and access points of one network.'
                    )

                    Add-TkTable -Document $document -Column @('Network', 'Signal', 'Band', 'Channel', 'Standard', 'Access point') `
                        -Weight @(1.9, 0.7, 0.7, 0.6, 1.2, 1.3) `
                        -Row @($networks | ForEach-Object {
                            $name = if ($_.Ssid) { $_.Ssid } else { '(hidden)' }

                            , @($(if ($_.Bssid -eq $connected) { $name + ' (connected)' } else { $name }),
                                ('{0} dBm' -f [string] $_.Rssi), $_.Band, [string] $_.Channel, $_.Standard, $_.Bssid)
                        })
                }

                $recent = @($adapter.Events | Where-Object { $_ -and $_.Kind -ne 'Connected' } |
                            Sort-Object -Property When -Descending | Select-Object -First 12)

                if ($recent.Count -gt 0) {

                    Add-TkHeading -Document $document -Text 'Recent disconnections and failed attempts' -Level 2

                    Add-TkTable -Document $document -Column @('When', 'Event', 'Network', 'Reason') `
                        -Weight @(1.1, 0.8, 1.2, 3.0) `
                        -Row @($recent | ForEach-Object {
                            , @(([datetime] $_.When).ToString('yyyy-MM-dd HH:mm'),
                                $(if ($_.Expected) { $_.Kind + ' (expected)' } else { $_.Kind }), $_.Ssid, $_.Reason)
                        })
                }
            }

            Set-TkDocument -ControlName 'DiagnosticsOutput' -Document $document
        }
}

<#
.SYNOPSIS
    Shows the three proxy settings, whether each one answers, and what
    automatic detection finds.
#>
function Show-TkProxyReport {
    [CmdletBinding()]
    param()

    Invoke-TkBackgroundAction -StatusText 'Reading the proxy settings and checking they answer...' `
        -ScriptBlock {
            $setting = Get-TkProxySetting

            [pscustomobject] @{
                Setting = $setting
                Probe   = Invoke-TkProxyProbe -Setting $setting
            }
        } `
        -OnComplete {
            param($result)

            $report = @($result.Output) | Where-Object { $_ -and $_.PSObject.Properties['Setting'] } | Select-Object -First 1

            if (-not $report) {
                return
            }

            Set-TkLastDiagnostic -Name 'proxy' -Data $report

            $document = New-TkFlowDocument

            Add-TkHeading   -Document $document -Text 'Proxy' -Level 1
            Add-TkParagraph -Document $document -Muted -Text (
                'Windows keeps three proxy settings and each program reads one of them. A difference between them is why the web works while Windows Update fails, or the browser works while git does not.'
            )

            foreach ($finding in @(Get-TkProxyFinding -Setting $report.Setting -Probe $report.Probe)) {
                Add-TkSeverityLine -Document $document -Severity $finding.Severity -Heading $finding.Heading `
                    -Detail $finding.Detail -Note $finding.Note -RemediationId $finding.RemediationId
            }

            Add-TkHeading -Document $document -Text 'Where each program looks' -Level 2

            $rows = @(
                , @('Applications (WinINET)', 'Browsers, Office, most applications', (Format-TkProxyDescription -Setting $report.Setting.User))
                , @('Services (WinHTTP)', 'Windows Update, BITS, Defender, Intune', (Format-TkProxyDescription -Setting $report.Setting.Machine))
            )

            foreach ($variable in @($report.Setting.Environment | Where-Object { $_ })) {
                $rows += , @(('{0} ({1})' -f $variable.Name, $variable.Scope), 'git, curl, Python, Node', $variable.Value)
            }

            Add-TkTable -Document $document -Column @('Setting', 'Read by', 'Value') -Weight @(1.2, 1.5, 2.6) -Row $rows

            $targets = @($report.Probe.Targets | Where-Object { $_ })

            if ($targets.Count -gt 0) {

                Add-TkHeading -Document $document -Text 'Checked' -Level 2

                Add-TkTable -Document $document -Column @('Address', 'Answers', 'Time') -Weight @(2.4, 0.8, 0.8) `
                    -Row @($targets | ForEach-Object {
                        , @($_.Address, $(if ($_.Open) { 'Yes' } else { 'No' }), ('{0} ms' -f [string] $_.ResponseMs))
                    })
            }

            Set-TkDocument -ControlName 'DiagnosticsOutput' -Document $document
        }
}

<#
.SYNOPSIS
    Shows how the device is joined and managed, and whether sign-in can work.
#>
function Show-TkIdentityReport {
    [CmdletBinding()]
    param()

    Invoke-TkBackgroundAction -StatusText 'Reading sign-in and management...' `
        -ScriptBlock { Get-TkIdentityHealth } `
        -OnComplete {
            param($result)

            $rows = @($result.Output | Where-Object { $_ })
            Set-TkLastDiagnostic -Name 'sign-in' -Data $rows

            $document = New-TkFlowDocument

            Add-TkHeading   -Document $document -Text 'Sign-in and management' -Level 1
            Add-TkParagraph -Document $document -Muted -Text (
                '"I cannot sign in", "Outlook keeps asking for my password" and "the policy never arrived" are answered here: how the device is joined, its single sign-on token, the domain controller it reaches, the clock Kerberos depends on, and whether an MDM manages it.'
            )

            foreach ($row in $rows) {

                Add-TkSeverityLine -Document $document -Severity $row.Severity `
                    -Heading ('{0}: {1}' -f $row.Kind, $row.Value) `
                    -Note $row.Detail -RemediationId $row.RemediationId
            }

            Set-TkDocument -ControlName 'DiagnosticsOutput' -Document $document
        }
}

<#
.SYNOPSIS
    Shows disk health and free space.
#>
function Show-TkStorageHealth {
    [CmdletBinding()]
    param()

    Invoke-TkBackgroundAction -StatusText 'Reading disk health...' `
        -ScriptBlock { Get-TkStorageHealth } `
        -OnComplete {
            param($result)

            $rows = @($result.Output)
            Set-TkLastDiagnostic -Name 'storage' -Data $rows

            $document = New-TkFlowDocument

            Add-TkHeading   -Document $document -Text 'Storage health' -Level 1
            Add-TkParagraph -Document $document -Muted -Text (
                '"The machine is slow" is answered by a failing disk or a full volume far more often than by anything else.'
            )

            foreach ($row in ($rows | Where-Object { $_.Severity -ne 'Pass' })) {

                # A full volume has one safe first move: clear the temporary
                # files and measure again.
                $remediation = if ($row.Kind -eq 'Volume') { 'clear-temp' } else { '' }

                Add-TkSeverityLine -Document $document -Severity $row.Severity `
                    -Heading ('{0}: {1}' -f $row.Kind, $row.Name) `
                    -Detail $row.Health -Note $row.Notes -RemediationId $remediation
            }

            Add-TkHeading -Document $document -Text 'Every drive and volume' -Level 2

            Add-TkTable -Document $document `
                -Column @('Kind', 'Name', 'Size', 'Type', 'State', 'Wear %', 'Temp C') `
                -Weight @(0.7, 1.8, 0.9, 0.7, 1.4, 0.6, 0.6) `
                -Row @($rows | ForEach-Object {
                    , @($_.Kind, $_.Name, $_.Size, $_.MediaType, $_.Health, $_.WearPercent, $_.TemperatureC)
                })

            Set-TkDocument -ControlName 'DiagnosticsOutput' -Document $document
        }
}

<#
.SYNOPSIS
    Shows crashes, bug checks and unexpected shutdowns.
#>
function Show-TkStabilityReport {
    [CmdletBinding()]
    param()

    Invoke-TkBackgroundAction -StatusText 'Reading the crash history...' `
        -ScriptBlock {
            [pscustomobject] @{
                Stability = @(Get-TkStabilityReport -Days 14)
                Crashes   = @(Get-TkCrashHistory -Days 90)
            }
        } `
        -OnComplete {
            param($result)

            $report = @($result.Output) | Select-Object -First 1

            if (-not $report) {
                return
            }

            $rows    = @($report.Stability | Where-Object { $_ })
            $crashes = @($report.Crashes   | Where-Object { $_ })
            $blue    = @($crashes | Where-Object { $_.Code -ne 0 })
            $resets  = @($crashes | Where-Object { $_.Code -eq 0 })

            Set-TkLastDiagnostic -Name 'stability' -Data $report

            $document = New-TkFlowDocument

            Add-TkHeading   -Document $document -Text 'Stability' -Level 1
            Add-TkParagraph -Document $document -Muted -Text (
                'Three different questions behind "it keeps crashing": did Windows itself stop, did one application stop, or did the machine simply lose power. Each has a different cause.'
            )

            # --- Blue screens and hard resets --------------------------------
            Add-TkHeading -Document $document -Text 'Blue screens and hard resets, last 90 days' -Level 2

            if ($crashes.Count -eq 0) {
                Add-TkSeverityLine -Document $document -Severity 'Pass' -Heading 'No blue screen or hard reset in 90 days'
            }

            $recurring = @(Get-TkRecurringCrashDriver -Crash $crashes)

            if ($recurring.Count -gt 0) {

                Add-TkSeverityLine -Document $document -Severity 'Warning' `
                    -Heading 'Kernel drivers registered before several blue screens' `
                    -Detail ((@($recurring | ForEach-Object { '{0} ({1} of {2})' -f $_.Name, $_.Crashes, $blue.Count })) -join ', ') `
                    -Note 'The same driver in front of several crashes is the first one to update or uninstall. It is a correlation, not a proof: monitoring and overclocking tools register their driver every time they start.'
            }

            foreach ($crash in $blue) {

                $info    = $crash.Info
                $drivers = @($crash.Drivers | Where-Object { $_ })

                $note = @(
                    $info.Meaning
                    $(if ($info.KindName) { 'Usual cause: {0}.' -f $info.KindName.ToLowerInvariant() })
                    $(if ($drivers.Count -gt 0) { 'Kernel drivers registered in the 7 days before: {0}.' -f ((@($drivers | ForEach-Object { $_.Name })) -join ', ') })
                    $(if ($crash.DumpPath) { 'Dump: {0}. Reading it needs administrator rights and WinDbg (winget install Microsoft.WinDbg), then !analyze -v.' -f $crash.DumpPath })
                ) | Where-Object { $_ }

                Add-TkSeverityLine -Document $document -Severity $crash.Severity `
                    -Heading ('{0} {1}' -f $info.CodeHex, $info.Name) `
                    -Detail ('{0}, {1}' -f $crash.Kind, ([datetime] $crash.When).ToString('yyyy-MM-dd HH:mm')) `
                    -Note ($note -join ' ') `
                    -Action (@($info.Steps) -join ' ')
            }

            if ($resets.Count -gt 0) {

                Add-TkSeverityLine -Document $document -Severity 'Warning' `
                    -Heading ('{0} hard reset(s) or power loss(es)' -f $resets.Count) `
                    -Detail ('last on {0}' -f ([datetime] $resets[0].When).ToString('yyyy-MM-dd HH:mm')) `
                    -Note 'The session ended with no shutdown and no stop code: the power was lost, the power button was held, or the machine froze and had to be reset.'
            }

            # --- The other signals -------------------------------------------
            Add-TkHeading -Document $document -Text 'Other signals, last 14 days' -Level 2

            # Blue screens are described above, with more than a line each.
            foreach ($row in ($rows | Where-Object { $_.Kind -ne 'Bug check' })) {

                Add-TkSeverityLine -Document $document -Severity $row.Severity `
                    -Heading ('{0}{1}' -f $row.Kind, $(if ($row.Source) { ': ' + $row.Source } else { '' })) `
                    -Detail $(if ($row.When) { ([datetime] $row.When).ToString('yyyy-MM-dd HH:mm') } else { '' }) `
                    -Note $row.Detail
            }

            Set-TkDocument -ControlName 'DiagnosticsOutput' -Document $document
        }
}

<#
.SYNOPSIS
    Shows the recent Windows Update history.
#>
function Show-TkUpdateHistory {
    [CmdletBinding()]
    param()

    Invoke-TkBackgroundAction -StatusText 'Reading the update history...' `
        -ScriptBlock { Get-TkUpdateHistory -Count 40 } `
        -OnComplete {
            param($result)

            $rows = @($result.Output)
            Set-TkLastDiagnostic -Name 'updates' -Data $rows

            $document = New-TkFlowDocument

            Add-TkHeading   -Document $document -Text 'Update history' -Level 1
            Add-TkParagraph -Document $document -Muted -Text (
                'Read through the update session interface rather than Get-HotFix, which only reports servicing packages and misses driver and feature updates entirely. Those are the ones that break things.'
            )

            $failures = @($rows | Where-Object { $_.Severity -in @('Fail', 'Warning') })

            foreach ($row in $failures) {

                # The code explained from the reference, and where to read what
                # to try for it.
                $note = @(
                    ('{0} on {1}.' -f $row.Code, ([datetime] $row.When).ToString('yyyy-MM-dd'))
                    $(if ($row.PSObject.Properties['Meaning'] -and $row.Meaning) { $row.Meaning })
                    'Knowledge base, Windows codes says what to try for this code.'
                ) | Where-Object { $_ }

                Add-TkSeverityLine -Document $document -Severity $row.Severity `
                    -Heading $row.Title -Detail $row.Outcome `
                    -Note ($note -join ' ')
            }

            if ($failures.Count -eq 0) {
                Add-TkSeverityLine -Document $document -Severity 'Pass' -Heading 'No failed update in the recent history'
            }

            Add-TkHeading -Document $document -Text 'Recent updates' -Level 2

            Add-TkTable -Document $document -Column @('Date', 'Outcome', 'Update') `
                -Weight @(0.9, 0.9, 3.2) `
                -Row @($rows | ForEach-Object {
                    , @(([datetime] $_.When).ToString('yyyy-MM-dd'), $_.Outcome, $_.Title)
                })

            Set-TkDocument -ControlName 'DiagnosticsOutput' -Document $document
        }
}

<#
.SYNOPSIS
    Shows the printing subsystem.
#>
function Show-TkPrintingReport {
    [CmdletBinding()]
    param()

    Invoke-TkBackgroundAction -StatusText 'Reading the printing subsystem...' `
        -ScriptBlock { Get-TkPrintingReport } `
        -OnComplete {
            param($result)

            $rows = @($result.Output)
            Set-TkLastDiagnostic -Name 'printing' -Data $rows

            $document = New-TkFlowDocument

            Add-TkHeading   -Document $document -Text 'Printing' -Level 1
            Add-TkParagraph -Document $document -Muted -Text (
                '"It will not print" is nearly always one of four things: the printer is offline, the queue is jammed, the port points somewhere unreachable, or the spooler has stopped.'
            )

            foreach ($row in $rows) {

                # The spooler is the one printing problem with a safe one step
                # correction, so it is the one that gets a button.
                $remediation = if ($row.Kind -eq 'Spooler' -and $row.Severity -eq 'Fail') { 'start-spooler' } else { '' }

                Add-TkSeverityLine -Document $document -Severity $row.Severity `
                    -Heading ('{0}: {1}' -f $row.Kind, $row.Name) `
                    -Detail $row.Status -Note $row.Detail -RemediationId $remediation
            }

            Set-TkDocument -ControlName 'DiagnosticsOutput' -Document $document
        }
}

<#
.SYNOPSIS
    Shows profiles, mapped drives, domain state and logon timing.
#>
function Show-TkUserContext {
    [CmdletBinding()]
    param()

    Invoke-TkBackgroundAction -StatusText 'Reading profiles and policy, this measures profile sizes...' `
        -ScriptBlock { Get-TkUserContextReport } `
        -OnComplete {
            param($result)

            $rows = @($result.Output)
            Set-TkLastDiagnostic -Name 'user-context' -Data $rows

            $document = New-TkFlowDocument

            Add-TkHeading   -Document $document -Text 'Profiles and policy' -Level 1
            Add-TkParagraph -Document $document -Muted -Text (
                'The context of a support call: who is signed in, how large their profile is, what is mapped, and how long policy takes to apply. A roaming profile of twelve gigabytes explains a slow logon better than any amount of network testing.'
            )

            foreach ($row in $rows) {

                Add-TkSeverityLine -Document $document -Severity $row.Severity `
                    -Heading ('{0}: {1}' -f $row.Kind, $row.Name) `
                    -Detail $row.Value -Note $row.Detail
            }

            Set-TkDocument -ControlName 'DiagnosticsOutput' -Document $document
        }
}

<#
.SYNOPSIS
    Runs every diagnostic in the order a call is normally worked.
#>
function Invoke-TkDiagnosticOverview {
    [CmdletBinding()]
    param()

    Invoke-TkBackgroundAction -StatusText 'Running the full check, this takes a minute...' `
        -ScriptBlock {

            [pscustomobject]@{
                Reboot    = Get-TkPendingRebootStatus
                Storage   = Get-TkStorageHealth
                Devices   = @(Get-TkDeviceProblem)
                Stability = Get-TkStabilityReport -Days 14
                Crashes   = @(Get-TkCrashHistory -Days 30)
                Printing  = Get-TkPrintingReport
                Wifi      = Get-TkWifiStatus -Days 7
                Proxy     = & {
                                $setting = Get-TkProxySetting
                                [pscustomobject] @{ Setting = $setting; Probe = Invoke-TkProxyProbe -Setting $setting }
                            }
                Context   = Get-TkUserContextReport
            }
        } `
        -OnComplete {
            param($result)

            $report = @($result.Output) | Select-Object -First 1

            if (-not $report) {
                return
            }

            Set-TkLastDiagnostic -Name 'full-check' -Data $report

            $document = New-TkFlowDocument

            Add-TkHeading   -Document $document -Text ('Diagnostics for {0}' -f $env:COMPUTERNAME) -Level 1
            Add-TkParagraph -Document $document -Muted -Text (
                'In the order a call is normally worked. A machine waiting for a reboot, or with a full disk, explains most complaints before anything else is worth looking at.'
            )

            # --- Reboot -------------------------------------------------
            Add-TkHeading -Document $document -Text '1. Is it waiting for a restart' -Level 2

            Add-TkSeverityLine -Document $document `
                -Severity $(if ($report.Reboot.Pending) { 'Warning' } else { 'Pass' }) `
                -Heading $(if ($report.Reboot.Pending) { 'A restart is pending' } else { 'No restart pending' }) `
                -Detail ('up {0}' -f $report.Reboot.Uptime) `
                -Note (($report.Reboot.Reasons -join ' ') )

            # --- Storage ------------------------------------------------
            Add-TkHeading -Document $document -Text '2. Storage' -Level 2

            $storageProblems = @($report.Storage | Where-Object { $_.Severity -ne 'Pass' })

            if ($storageProblems.Count -eq 0) {
                Add-TkSeverityLine -Document $document -Severity 'Pass' -Heading 'Every drive healthy, every volume with room'
            }
            else {
                foreach ($row in $storageProblems) {
                    Add-TkSeverityLine -Document $document -Severity $row.Severity `
                        -Heading ('{0}: {1}' -f $row.Kind, $row.Name) -Detail $row.Health -Note $row.Notes
                }
            }

            # --- Devices ------------------------------------------------
            Add-TkHeading -Document $document -Text '3. Devices' -Level 2

            $deviceProblems = @($report.Devices | Where-Object { $_ -and $_.Severity -ne 'Info' })

            if ($deviceProblems.Count -eq 0) {
                Add-TkSeverityLine -Document $document -Severity 'Pass' -Heading 'No device reports a problem'
            }
            else {
                foreach ($row in $deviceProblems) {
                    Add-TkSeverityLine -Document $document -Severity $row.Severity -Heading $row.Name `
                        -Detail ('Code {0}' -f $row.Code) -Note $row.Meaning -Action $row.Action `
                        -RemediationId 'open-device-manager'
                }
            }

            # --- Stability ----------------------------------------------
            Add-TkHeading -Document $document -Text '4. Stability' -Level 2

            foreach ($crash in @($report.Crashes | Where-Object { $_ -and $_.Code -ne 0 })) {
                Add-TkSeverityLine -Document $document -Severity 'Fail' `
                    -Heading ('{0} {1}' -f $crash.Info.CodeHex, $crash.Info.Name) `
                    -Detail ([datetime] $crash.When).ToString('yyyy-MM-dd HH:mm') `
                    -Note ('{0} The Crashes report lists the drivers registered before it.' -f $crash.Info.Meaning)
            }

            foreach ($row in @($report.Stability | Where-Object { $_.Kind -ne 'Bug check' } | Select-Object -First 6)) {
                Add-TkSeverityLine -Document $document -Severity $row.Severity `
                    -Heading ('{0}{1}' -f $row.Kind, $(if ($row.Source) { ': ' + $row.Source } else { '' })) `
                    -Note $row.Detail
            }

            # --- Printing -----------------------------------------------
            Add-TkHeading -Document $document -Text '5. Printing' -Level 2

            $printProblems = @($report.Printing | Where-Object { $_.Severity -ne 'Pass' })

            if ($printProblems.Count -eq 0) {
                Add-TkSeverityLine -Document $document -Severity 'Pass' -Heading 'Spooler running, no printer reporting a problem'
            }
            else {
                foreach ($row in $printProblems) {
                    Add-TkSeverityLine -Document $document -Severity $row.Severity `
                        -Heading ('{0}: {1}' -f $row.Kind, $row.Name) -Detail $row.Status -Note $row.Detail
                }
            }

            # --- Network access -----------------------------------------
            Add-TkHeading -Document $document -Text '6. Wi-Fi and proxy' -Level 2

            $accessProblems = @(@(Get-TkWifiFinding -Status $report.Wifi) + @(Get-TkProxyFinding -Setting $report.Proxy.Setting -Probe $report.Proxy.Probe) |
                                Where-Object { $_ -and $_.Severity -in @('Warning', 'Fail') })

            if ($accessProblems.Count -eq 0) {
                Add-TkSeverityLine -Document $document -Severity 'Pass' -Heading 'Nothing wrong with the Wi-Fi or the proxy'
            }
            else {
                foreach ($row in $accessProblems) {
                    Add-TkSeverityLine -Document $document -Severity $row.Severity -Heading $row.Heading `
                        -Detail $row.Detail -Note $row.Note -RemediationId $row.RemediationId
                }
            }

            # --- Context ------------------------------------------------
            Add-TkHeading -Document $document -Text '7. Profiles, drives and policy' -Level 2

            foreach ($row in $report.Context) {
                Add-TkSeverityLine -Document $document -Severity $row.Severity `
                    -Heading ('{0}: {1}' -f $row.Kind, $row.Name) -Detail $row.Value -Note $row.Detail
            }

            Set-TkDocument -ControlName 'DiagnosticsOutput' -Document $document
            Set-TkStatus -Text 'Full check finished.'
        }
}


<#
.SYNOPSIS
    Writes the last rendered report to a JSON file.

.PARAMETER ControlName
    Only used to keep the two export buttons distinguishable in the log.
#>
function Export-TkDiagnosticReport {
    [CmdletBinding()]
    param(
        [Parameter()]
        [string] $ControlName = ''
    )

    if (-not $script:TkLastDiagnostic) {
        Set-TkStatus -Text 'Run a check first.'
        return
    }

    $dialog = New-Object Microsoft.Win32.SaveFileDialog
    $dialog.Title    = 'Export the report'
    $dialog.Filter   = 'JSON report (*.json)|*.json'
    $dialog.FileName = '{0}-{1}-{2}.json' -f $env:COMPUTERNAME, $script:TkLastDiagnosticName, (Get-Date -Format 'yyyyMMdd')

    if (-not $dialog.ShowDialog()) {
        return
    }

    try {
        [pscustomobject]@{
            Computer    = $env:COMPUTERNAME
            Report      = $script:TkLastDiagnosticName
            GeneratedAt = (Get-Date).ToString('s')
            Toolkit     = (Get-TkContext).Version
            Data        = $script:TkLastDiagnostic
        } | ConvertTo-Json -Depth 6 |
            Set-Content -LiteralPath $dialog.FileName -Encoding UTF8 -ErrorAction Stop

        Set-TkStatus -Text ('Report written to {0}' -f $dialog.FileName)
    }
    catch {
        Write-TkLog -Level Error -Category 'Diagnostics' -Message (
            'The report could not be written: {0}' -f $_.Exception.Message
        )
    }
}


# ==========================================================================
# Source: src/UI/Pages/HardwarePage.ps1
# ==========================================================================

<#
    Toolkit - UI / Hardware tests

    The interactive checks, in the Hardware tests tab of the Diagnostics page.
    The reports beside them read the machine; these ask the operator to look,
    listen and press, because that is the only way to answer "is this key dead".

    The keyboard test reads keys only while its own window has focus and its
    panel is on screen. Start-TkKeyboardTest explains why it reads WPF key
    events rather than window messages.
#>

# Which keys have been seen, keyed by physical identity, and the blocks drawn
# for them. Held here rather than on the controls so the test survives a
# redraw: changing the layout rebuilds the board but keeps the results.
$script:TkKeyboardSeen    = @{}
$script:TkKeyboardButtons = @{}
$script:TkKeyboardPressed = @{}
$script:TkKeyboardRunning = $false
$script:TkKeyboardDownHandler = $null
$script:TkKeyboardUpHandler   = $null
$script:TkKeyboardLayout  = 'FR AZERTY (French)'
$script:TkLastEscape      = [datetime]::MinValue

# Where WPF keeps the physical key on a key event. Looked up once, on the first
# key, because reflection on every keystroke would be wasted work.
$script:TkKeyScanCodeProperty = $null
$script:TkKeyExtendedProperty = $null

<#
.SYNOPSIS
    Wires the Hardware tests tab of the Diagnostics page.
#>
function Initialize-TkHardwarePage {
    [CmdletBinding()]
    param()

    $chooser = Get-TkControl -Name 'HardwareChoices'

    if ($chooser) {

        $chooser.SelectedIndex = 0

        $chooser.Add_SelectionChanged({

            $list = Get-TkControl -Name 'HardwareChoices'

            if ($list) {
                Show-TkHardwarePanel -Index $list.SelectedIndex
            }
        })
    }

    # --- Keyboard ---------------------------------------------------------
    # No start button: the test runs as soon as its panel is open. Pressing a
    # key is the only thing it ever needed the operator to do.
    Register-TkClick -Name 'BtnKeyboardReset' -Action { Reset-TkKeyboardTest }

    $layoutBox = Get-TkControl -Name 'KeyboardLayout'

    if ($layoutBox) {

        foreach ($name in (Get-TkKeyboardLayoutName)) {
            [void] $layoutBox.Items.Add($name)
        }

        # Selected before the handler is attached, so filling the list does not
        # fire a redraw of a board that does not exist yet.
        $layoutBox.SelectedItem = $script:TkKeyboardLayout

        $layoutBox.Add_SelectionChanged({

            $box = Get-TkControl -Name 'KeyboardLayout'

            if ($box -and $box.SelectedItem) {

                $script:TkKeyboardLayout = [string] $box.SelectedItem

                # The board is redrawn, the results are not thrown away: the
                # identity of a key is its physical position, which does not
                # move when the legend changes.
                Build-TkKeyboardSurface
            }
        })
    }

    # --- Display ----------------------------------------------------------
    Register-TkClick -Name 'BtnDisplayColours'  -Action { Show-TkDisplayTest -Mode 'Colours' }
    Register-TkClick -Name 'BtnDisplayGradient' -Action { Show-TkDisplayTest -Mode 'Gradient' }
    Register-TkClick -Name 'BtnDisplayGrid'     -Action { Show-TkDisplayTest -Mode 'Grid' }

    # --- Sound ------------------------------------------------------------
    Register-TkClick -Name 'BtnToneLeft'  -Action { Invoke-TkToneFromUi -Channel 'Left' }
    Register-TkClick -Name 'BtnToneRight' -Action { Invoke-TkToneFromUi -Channel 'Right' }
    Register-TkClick -Name 'BtnToneBoth'  -Action { Invoke-TkToneFromUi -Channel 'Both' }
    Register-TkClick -Name 'BtnToneSweep' -Action { Invoke-TkToneSweepFromUi }

    # --- Battery ----------------------------------------------------------
    Register-TkClick -Name 'BtnBatteryRefresh' -Action { Update-TkBatteryPanel }
    Register-TkClick -Name 'BtnBatteryReport'  -Action { Invoke-TkBatteryReportFromUi }

    # --- Memory -----------------------------------------------------------
    Register-TkClick -Name 'BtnMemoryRefresh' -Action { Update-TkMemoryPanel }

    Register-TkClick -Name 'BtnMemoryDiagnostic' -Action {

        # mdsched asks its own question about when to restart, so the toolkit
        # does not need to and must not answer it on the operator's behalf.
        try {
            Start-Process -FilePath 'mdsched.exe' -ErrorAction Stop
            Set-TkStatus -Text 'The Windows memory tool is open. It will ask when to restart.'
        }
        catch {
            Set-TkStatus -Text ('The Windows memory tool could not be started: {0}' -f $_.Exception.Message)
        }
    }

    Build-TkKeyboardSurface

    # Reading modules and panels costs a WMI call each, so it waits until
    # somebody opens the page.
    #
    # The hardware tests are a tab of the Diagnostics page now, so they load
    # with it.
    Register-TkFirstShow -PageName 'Diagnostics' -Action {
        Update-TkMemoryPanel
        Update-TkBatteryPanel
        Update-TkAudioPanel
    }

    # The keyboard test runs exactly while its panel is on screen. IsVisible
    # turns false as soon as anything above the panel hides it: another test
    # chosen in the list, the Reports tab, or another page. One signal covers
    # every route. Following the chooser missed the panel selected at start up,
    # and following the page missed the tabs, so the test either never started
    # or kept swallowing keys on a screen that no longer showed it.
    $keyboardPanel = Get-TkControl -Name 'PanelKeyboard'

    if ($keyboardPanel) {

        $keyboardPanel.Add_IsVisibleChanged({
            param($panelSource, $visibleArgs)

            if ($visibleArgs.NewValue) {
                Start-TkKeyboardTest
            }
            else {
                Stop-TkKeyboardTest
            }
        })
    }
}

<#
.SYNOPSIS
    Shows one hardware panel and hides the others.

.PARAMETER Index
    Position in the chooser list.
#>
function Show-TkHardwarePanel {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [int] $Index
    )

    $panels = @('Keyboard', 'Display', 'Sound', 'Battery', 'Memory')

    for ($i = 0; $i -lt $panels.Count; $i++) {

        $panel = Get-TkControl -Name ('Panel{0}' -f $panels[$i])

        if ($null -eq $panel) {
            continue
        }

        $panel.Visibility = if ($i -eq $Index) { [System.Windows.Visibility]::Visible }
                            else { [System.Windows.Visibility]::Collapsed }
    }

    # Nothing to start or stop here: the keyboard test follows the visibility
    # of its panel, which the loop above has just changed.
}

<#
.SYNOPSIS
    Draws the virtual keyboard.

.DESCRIPTION
    Three blocks side by side, as on a real board: the main block, the
    navigation cluster and the numeric keypad. The earlier version stacked all
    three as plain rows, which read as a heap of keys rather than a keyboard.

    Each key is a bordered block with a thicker bottom edge, which is what
    gives it the look of a keycap seen slightly from above; pressing it
    collapses that edge and drops the block two pixels.

    Blocks are indexed by physical identity, not by label, so redrawing for
    another layout keeps every result: the same piece of plastic stays the same
    key whatever is printed on it.
#>
function Build-TkKeyboardSurface {
    [CmdletBinding()]
    param()

    $surface = Get-TkControl -Name 'KeyboardSurface'

    if ($null -eq $surface) {
        return
    }

    $surface.Children.Clear()
    $script:TkKeyboardButtons = @{}
    $script:TkKeyboardPressed = @{}

    $map = Get-TkKeyboardMap -Layout $script:TkKeyboardLayout

    $board = New-Object System.Windows.Controls.Grid

    foreach ($width in @(0, 1, 2)) {

        $column = New-Object System.Windows.Controls.ColumnDefinition
        $column.Width = [System.Windows.GridLength]::Auto

        $board.ColumnDefinitions.Add($column)
    }

    $blocks = @(
        @{ Rows = $map.Main;       Column = 0; Margin = 0 },
        @{ Rows = $map.Navigation; Column = 1; Margin = 18 },
        @{ Rows = $map.Numpad;     Column = 2; Margin = 12 }
    )

    foreach ($block in $blocks) {

        $stack = New-Object System.Windows.Controls.StackPanel
        $stack.Margin            = New-Object System.Windows.Thickness($block.Margin, 0, 0, 0)
        $stack.VerticalAlignment = [System.Windows.VerticalAlignment]::Top

        foreach ($row in $block.Rows) {
            [void] $stack.Children.Add((New-TkKeyboardRow -Row $row))
        }

        [System.Windows.Controls.Grid]::SetColumn($stack, $block.Column)
        [void] $board.Children.Add($stack)
    }

    [void] $surface.Children.Add($board)

    # Re-light whatever was already pressed. Rebuilding made fresh grey blocks,
    # and Set-TkKeySeen refuses a key it has already recorded, so without this
    # a layout change would grey out results that can never come back.
    foreach ($identity in $script:TkKeyboardSeen.Keys) {

        if ($script:TkKeyboardButtons.ContainsKey($identity)) {
            Set-TkKeyBlockSeen -Block $script:TkKeyboardButtons[$identity] -Animate $false
        }
    }

    Update-TkKeyboardProgress
}

<#
.SYNOPSIS
    Builds one row of keys.

.DESCRIPTION
    An empty row still produces a spacer of the usual height, which is what
    puts the gap above the arrow keys where a real board has one.

.OUTPUTS
    System.Windows.Controls.StackPanel
#>
function New-TkKeyboardRow {
    [CmdletBinding()]
    [OutputType([System.Windows.Controls.StackPanel])]
    param(
        [Parameter(Mandatory)]
        [AllowEmptyCollection()]
        [object[]] $Row
    )

    $unit = 38

    $panel = New-Object System.Windows.Controls.StackPanel
    $panel.Orientation = [System.Windows.Controls.Orientation]::Horizontal
    $panel.Margin      = New-Object System.Windows.Thickness(0, 0, 0, 4)
    $panel.Height      = $unit - 4

    foreach ($key in $Row) {

        $block = New-Object System.Windows.Controls.Border
        $block.Width        = ($unit * $key.Width) - 4
        $block.Height       = $unit - 4
        $block.CornerRadius = New-Object System.Windows.CornerRadius(4)
        $block.Margin       = New-Object System.Windows.Thickness(0, 0, 4, 0)

        # A thicker bottom edge reads as the side of a keycap. Collapsing it on
        # press is cheaper than a drop shadow on a hundred and five elements.
        $block.BorderThickness = New-Object System.Windows.Thickness(1, 1, 1, 3)

        Set-TkKeyBlockRest -Block $block

        # Held so the press animation has something to move.
        $block.RenderTransform = New-Object System.Windows.Media.TranslateTransform

        $text = New-Object System.Windows.Controls.TextBlock
        $text.Text                = $key.Label
        $text.FontSize            = if ($key.Label.Length -gt 3) { 9.5 } else { 12 }
        $text.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
        $text.VerticalAlignment   = [System.Windows.VerticalAlignment]::Center
        $text.TextTrimming        = [System.Windows.TextTrimming]::CharacterEllipsis

        $text.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, 'TextPrimary')

        $block.Child = $text

        [void] $panel.Children.Add($block)

        $script:TkKeyboardButtons[$key.Key] = $block
    }

    return $panel
}

<#
.SYNOPSIS
    Starts the keyboard test.

.DESCRIPTION
    Two WPF handlers on the window, one for key down and one for key up,
    registered to receive events that are already handled, so no control can
    hide a key from the test. Each marks its key handled in turn, which keeps
    Tab from moving the focus, Space from pressing whatever button has it and
    Alt from entering access key mode while the test runs.

    The physical key comes from the event itself: WPF keeps the scan code and
    the extended flag of the key message on the event arguments. See
    Get-TkKeyEventPosition.

    An earlier version read them from a window message hook, HwndSource.AddHook,
    and never saw a single key. WPF handles keyboard messages in its message
    pump, before they are dispatched to the window procedure, and a message
    handled there is never dispatched. The handler that stops Tab and Space
    marked every key handled, so the hook listened on a window procedure that
    keyboard messages no longer reached. Microsoft documents this in "Sharing
    Message Loops Between Win32 and WPF".

    Neither handler is a system wide hook. Both belong to this window and see
    only the keys Windows delivers to it while it has the focus.
#>
function Start-TkKeyboardTest {
    [CmdletBinding()]
    param()

    if ($script:TkKeyboardRunning) {
        return
    }

    $ctx = Get-TkContext

    if ($null -eq $ctx.Window) {
        return
    }

    $script:TkKeyboardRunning = $true
    $script:TkLastEscape      = [datetime]::MinValue

    $down = [System.Windows.Input.KeyEventHandler] {
        param($sourceControl, $keyArgs)

        $keyArgs.Handled = $true

        Update-TkKeyboardFromKeyEvent -KeyArgs $keyArgs -Down $true
    }

    $up = [System.Windows.Input.KeyEventHandler] {
        param($sourceControl, $keyArgs)

        $keyArgs.Handled = $true

        Update-TkKeyboardFromKeyEvent -KeyArgs $keyArgs -Down $false
    }

    $ctx.Window.AddHandler([System.Windows.UIElement]::PreviewKeyDownEvent, $down, $true)
    $ctx.Window.AddHandler([System.Windows.UIElement]::PreviewKeyUpEvent, $up, $true)

    $script:TkKeyboardDownHandler = $down
    $script:TkKeyboardUpHandler   = $up

    # The verdict belongs to the run that produced it.
    Set-TkOutput -ControlName 'KeyboardResult' -Text ''

    Update-TkKeyboardProgress

    Set-TkStatus -Text 'Keyboard test running. Press every key. Escape twice to stop.'
}

<#
.SYNOPSIS
    Stops the keyboard test and hands the keyboard back.
#>
function Stop-TkKeyboardTest {
    [CmdletBinding()]
    param()

    if (-not $script:TkKeyboardRunning) {
        return
    }

    $ctx = Get-TkContext

    if ($ctx.Window) {

        if ($script:TkKeyboardDownHandler) {
            $ctx.Window.RemoveHandler([System.Windows.UIElement]::PreviewKeyDownEvent, $script:TkKeyboardDownHandler)
        }

        if ($script:TkKeyboardUpHandler) {
            $ctx.Window.RemoveHandler([System.Windows.UIElement]::PreviewKeyUpEvent, $script:TkKeyboardUpHandler)
        }
    }

    # Any key still held when the test stops would stay visually depressed.
    foreach ($identity in @($script:TkKeyboardPressed.Keys)) {
        Set-TkKeyPressed -Identity $identity -Down $false
    }

    $script:TkKeyboardDownHandler = $null
    $script:TkKeyboardUpHandler   = $null
    $script:TkKeyboardRunning     = $false

    Update-TkKeyboardProgress

    Set-TkStatus -Text 'Keyboard test stopped.'
}

<#
.SYNOPSIS
    Forgets which keys have been pressed.
#>
function Reset-TkKeyboardTest {
    [CmdletBinding()]
    param()

    $script:TkKeyboardSeen    = @{}
    $script:TkKeyboardPressed = @{}

    foreach ($identity in $script:TkKeyboardButtons.Keys) {

        $block = $script:TkKeyboardButtons[$identity]

        Set-TkKeyBlockRest -Block $block

        # A key held across the reset would otherwise stay sunk for good.
        $block.RenderTransform.Y = 0
        $block.BorderThickness   = New-Object System.Windows.Thickness(1, 1, 1, 3)
    }

    Update-TkKeyboardProgress

    Set-TkOutput -ControlName 'KeyboardResult' -Text ''
}

<#
.SYNOPSIS
    Reads which physical key a WPF key event is about.

.DESCRIPTION
    KeyEventArgs carries the scan code and the extended flag of the key message
    that raised it, in two properties WPF does not make public: ScanCode and
    IsExtendedKey. They are read by reflection because the public Key cannot
    replace them. It reports the keypad Enter and the main Enter as the same
    value, and it moves with the Windows layout, so a layout selector built on
    it would match nothing once another layout is picked.

    The virtual key is read from the key WPF actually means: Alt arrives as
    Key.System with the real key in SystemKey, and the same holds for keys
    taken by an input method or a dead key.

    A missing property, should a future WPF rename one, leaves a scan code of 0.
    Resolve-TkKeyIdentity then recovers the position from the virtual key, so
    the test degrades to losing the keypad Enter rather than every key.

.PARAMETER KeyArgs
    The event arguments of a key down or key up event.

.OUTPUTS
    An object with ScanCode, Extended and VirtualKey.
#>
function Get-TkKeyEventPosition {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)]
        [System.Windows.Input.KeyEventArgs] $KeyArgs
    )

    if ($null -eq $script:TkKeyScanCodeProperty) {

        $flags = [System.Reflection.BindingFlags] 'Instance, Public, NonPublic'
        $type  = [System.Windows.Input.KeyEventArgs]

        $script:TkKeyScanCodeProperty = $type.GetProperty('ScanCode', $flags)
        $script:TkKeyExtendedProperty = $type.GetProperty('IsExtendedKey', $flags)
    }

    $key = $KeyArgs.Key

    switch ($key) {
        ([System.Windows.Input.Key]::System)            { $key = $KeyArgs.SystemKey }
        ([System.Windows.Input.Key]::ImeProcessed)      { $key = $KeyArgs.ImeProcessedKey }
        ([System.Windows.Input.Key]::DeadCharProcessed) { $key = $KeyArgs.DeadCharProcessedKey }
    }

    $scanCode = 0
    $extended = $false

    if ($script:TkKeyScanCodeProperty) {
        $scanCode = [int] $script:TkKeyScanCodeProperty.GetValue($KeyArgs, $null)
    }

    if ($script:TkKeyExtendedProperty) {
        $extended = [bool] $script:TkKeyExtendedProperty.GetValue($KeyArgs, $null)
    }

    return [pscustomobject] @{
        ScanCode   = $scanCode
        Extended   = $extended
        VirtualKey = [System.Windows.Input.KeyInterop]::VirtualKeyFromKey($key)
    }
}

<#
.SYNOPSIS
    Names the key a press belongs to, the way the keyboard map names it.

.DESCRIPTION
    The map names a key by scan code and extended flag, and adds the virtual
    key only for the pair that shares a scan code: Pause and Num Lock.

    Tried in order:
    - scan code, extended flag and virtual key, for that pair;
    - scan code and extended flag, for every other key;
    - scan code and virtual key whatever the extended flag, so Num Lock still
      matches on a board or driver that reports it extended.

    An injected key, and some remote desktop sessions and software keyboards,
    report no scan code at all. Asking Windows which key produces the virtual
    key recovers it.

.PARAMETER ScanCode
    Scan code reported with the key, 0 when none was.

.PARAMETER Extended
    Extended flag reported with the key.

.PARAMETER VirtualKey
    Virtual key code.

.PARAMETER Known
    The identities drawn on the board, as keys of a hashtable.

.OUTPUTS
    System.String, empty when the key has no position at all.
#>
function Resolve-TkKeyIdentity {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter()]
        [int] $ScanCode = 0,

        [Parameter()]
        [bool] $Extended = $false,

        [Parameter()]
        [int] $VirtualKey = 0,

        [Parameter(Mandatory)]
        [AllowEmptyCollection()]
        [hashtable] $Known
    )

    if ($ScanCode -eq 0 -and $VirtualKey -gt 0) {
        $ScanCode = Get-TkScanCodeForVirtualKey -VirtualKey $VirtualKey
    }

    if ($ScanCode -eq 0) {
        return ''
    }

    $full = '{0}:{1}:{2}' -f $ScanCode, [int] $Extended, $VirtualKey

    if ($Known.ContainsKey($full)) {
        return $full
    }

    $short = '{0}:{1}' -f $ScanCode, [int] $Extended

    if ($Known.ContainsKey($short)) {
        return $short
    }

    $other = '{0}:{1}:{2}' -f $ScanCode, [int] (-not $Extended), $VirtualKey

    if ($VirtualKey -gt 0 -and $Known.ContainsKey($other)) {
        return $other
    }

    # Not drawn on the board: a media key, a vendor button. Still worth a name,
    # because "this key sends something" is an answer.
    return $short
}

<#
.SYNOPSIS
    Handles one key event while the keyboard test runs.

.PARAMETER KeyArgs
    The event arguments.

.PARAMETER Down
    True for a key down event, false for a key up event.
#>
function Update-TkKeyboardFromKeyEvent {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [System.Windows.Input.KeyEventArgs] $KeyArgs,

        [Parameter(Mandatory)]
        [bool] $Down
    )

    # Runs inside a WPF event handler: an exception escaping here would reach
    # the dispatcher, so it is logged instead.
    try {
        $position = Get-TkKeyEventPosition -KeyArgs $KeyArgs

        $identity = Resolve-TkKeyIdentity -ScanCode $position.ScanCode -Extended $position.Extended `
                                          -VirtualKey $position.VirtualKey -Known $script:TkKeyboardButtons

        if (-not $identity) {
            return
        }

        if (-not $Down) {

            # Print Screen sends no key down at all, only its release, so a
            # release of a key that was never seen going down counts as a press.
            $wasHeld = $script:TkKeyboardPressed.ContainsKey($identity)

            Set-TkKeyPressed -Identity $identity -Down $false

            if (-not $wasHeld) {
                Set-TkKeySeen -Identity $identity
            }

            return
        }

        Set-TkKeyPressed -Identity $identity -Down $true

        # Escape twice in quick succession is the way out. One press cannot be,
        # because Escape is a key the test has to cover.
        if ($position.VirtualKey -eq 0x1B -and -not $KeyArgs.IsRepeat) {

            $now = Get-Date

            if (($now - $script:TkLastEscape).TotalMilliseconds -lt 1000) {

                Set-TkKeySeen -Identity $identity
                Stop-TkKeyboardTest
                return
            }

            $script:TkLastEscape = $now
        }

        Set-TkKeySeen -Identity $identity
    }
    catch {
        Write-TkLog -Level Warning -Category 'Hardware' -Message (
            'A key event could not be read by the keyboard test: {0}' -f $_.Exception.Message
        )
    }
}

<#
.SYNOPSIS
    Shows a key as held down, or lets it back up.

.DESCRIPTION
    A held key is filled orange and drops two pixels with its bottom edge
    collapsing, which is what a keycap does. The orange applies whether or not
    the key has already been validated: it answers "the board is reading the
    key under my finger", which is a different question from "has this key been
    covered", and a key that were already green would answer nothing.

    Letting go settles the key: green if it has been validated, back to the
    resting colour otherwise. That is why the fade to green happens here rather
    than in Set-TkKeySeen, which would be overpainted by the press.
#>
function Set-TkKeyPressed {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string] $Identity,

        [Parameter(Mandatory)]
        [bool] $Down
    )

    if (-not $script:TkKeyboardButtons.ContainsKey($Identity)) {
        return
    }

    $block = $script:TkKeyboardButtons[$Identity]

    if ($Down) {

        if ($script:TkKeyboardPressed.ContainsKey($Identity)) {
            return
        }

        $script:TkKeyboardPressed[$Identity] = $true

        $block.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, 'Warning')
        $block.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, 'Warning')

        $block.RenderTransform.Y = 2
        $block.BorderThickness   = New-Object System.Windows.Thickness(1, 1, 1, 1)

        return
    }

    $script:TkKeyboardPressed.Remove($Identity)

    $block.RenderTransform.Y = 0
    $block.BorderThickness   = New-Object System.Windows.Thickness(1, 1, 1, 3)

    if ($script:TkKeyboardSeen.ContainsKey($Identity)) {
        Set-TkKeyBlockSeen -Block $block -Animate $true
    }
    else {
        Set-TkKeyBlockRest -Block $block
    }
}

<#
.SYNOPSIS
    Paints one block as untested.

.DESCRIPTION
    Resource references rather than brushes, so a resting key follows a theme
    change. Only a validated or a held key is painted explicitly.
#>
function Set-TkKeyBlockRest {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [System.Windows.Controls.Border] $Block
    )

    $Block.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, 'SurfaceRaised')
    $Block.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, 'BorderSubtle')
}

<#
.SYNOPSIS
    Records a key as tested and colours it.
#>
function Set-TkKeySeen {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string] $Identity
    )

    if ($script:TkKeyboardSeen.ContainsKey($Identity)) {
        return
    }

    # A key the board does not draw: a media key, a vendor button, or a board
    # with more keys than a standard one. Worth recording rather than dropping,
    # because "this key sends something" is the answer.
    $script:TkKeyboardSeen[$Identity] = $true

    if (-not $script:TkKeyboardButtons.ContainsKey($Identity)) {
        return
    }

    # While the key is held it stays orange. Releasing it paints the green,
    # which is also what makes the fade visible instead of instantaneous.
    if (-not $script:TkKeyboardPressed.ContainsKey($Identity)) {
        Set-TkKeyBlockSeen -Block $script:TkKeyboardButtons[$Identity] -Animate $true
    }

    Update-TkKeyboardProgress
}

<#
.SYNOPSIS
    Paints one block as tested.

.DESCRIPTION
    Fades to the success colour over two hundred milliseconds when the key was
    just pressed, and switches straight to it when the board is being redrawn
    for another layout, where a hundred simultaneous fades would only look like
    a fault.

    A validated block gets a brush of its own rather than a resource reference,
    which is what makes the animation possible and what stops it following a
    later theme change. Redrawing the board repaints them from the current
    palette.
#>
function Set-TkKeyBlockSeen {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [System.Windows.Controls.Border] $Block,

        [Parameter()]
        [bool] $Animate = $true
    )

    $ctx = Get-TkContext

    $target = if ($ctx.Window) { $ctx.Window.Resources['Success'] } else { $null }

    if ($null -eq $target) {
        $Block.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, 'Success')
        $Block.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, 'Success')
        return
    }

    $Block.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, 'Success')

    if (-not $Animate) {
        $Block.Background = $target
        return
    }

    # Read from the block rather than assumed, because the fade now starts
    # from the orange of a key being released, not only from the resting
    # colour. A new brush every time: animating the palette's own brush would
    # turn every surface in the window green.
    $from = if ($Block.Background -is [System.Windows.Media.SolidColorBrush]) {
                $Block.Background.Color
            }
            else {
                $target.Color
            }

    $brush = New-Object System.Windows.Media.SolidColorBrush($from)
    $Block.Background = $brush

    $fade = New-Object System.Windows.Media.Animation.ColorAnimation
    $fade.To       = $target.Color
    $fade.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(200))

    $brush.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty, $fade)
}

<#
.SYNOPSIS
    Updates the counter and, when the test is over, the list of missing keys.
#>
function Update-TkKeyboardProgress {
    [CmdletBinding()]
    param()

    $total = $script:TkKeyboardButtons.Count

    if ($total -eq 0) {
        return
    }

    $missing = @()

    foreach ($identity in $script:TkKeyboardButtons.Keys) {

        if (-not $script:TkKeyboardSeen.ContainsKey($identity)) {
            $missing += $script:TkKeyboardButtons[$identity].Child.Text
        }
    }

    $seen = $total - $missing.Count

    Set-TkOutput -ControlName 'KeyboardProgress' -Text ('{0} of {1} keys' -f $seen, $total)

    if ($script:TkKeyboardRunning -or $seen -eq 0) {
        return
    }

    if ($missing.Count -eq 0) {

        Set-TkOutput -ControlName 'KeyboardResult' -Text (
            'Every key on the board registered. ' + ((Get-TkUntestableKeyNote)[0])
        )

        return
    }

    $names = @($missing | Sort-Object -Unique)

    # Stopping after two keys would otherwise list the hundred you had not got
    # to yet, which buries the two that matter.
    $shown = if ($names.Count -gt 24) {
                 '{0} and {1} more' -f (($names | Select-Object -First 24) -join ', '), ($names.Count - 24)
             }
             else {
                 $names -join ', '
             }

    Set-TkOutput -ControlName 'KeyboardResult' -Text (
        ('Not seen ({0}): {1}.' -f $names.Count, $shown) +
        ' A key that never registers is either faulty, remapped in the keyboard, or not present on this board. ' +
        ((Get-TkUntestableKeyNote)[0])
    )
}

<#
.SYNOPSIS
    Enables or disables a named control, tolerating a missing one.
#>
function Set-TkControlEnabled {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string] $Name,

        [Parameter(Mandatory)]
        [bool] $Enabled
    )

    $control = Get-TkControl -Name $Name

    if ($control) {
        $control.IsEnabled = $Enabled
    }
}

<#
.SYNOPSIS
    Shows a full screen display test.

.DESCRIPTION
    A borderless window on top of everything, because a dead pixel under the
    task bar is still a dead pixel. Any key or click moves on, Escape leaves.

.PARAMETER Mode
    Colours, Gradient or Grid.
#>
function Show-TkDisplayTest {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [ValidateSet('Colours', 'Gradient', 'Grid')]
        [string] $Mode
    )

    $ctx = Get-TkContext

    $window = New-Object System.Windows.Window
    $window.WindowStyle           = [System.Windows.WindowStyle]::None
    $window.WindowState           = [System.Windows.WindowState]::Maximized
    $window.ResizeMode            = [System.Windows.ResizeMode]::NoResize
    $window.Topmost               = $true
    $window.ShowInTaskbar         = $false
    $window.Owner                 = $ctx.Window
    $window.Cursor                = [System.Windows.Input.Cursors]::None
    $window.Background            = [System.Windows.Media.Brushes]::Black

    $surface = New-Object System.Windows.Controls.Grid
    $window.Content = $surface

    $hint = New-Object System.Windows.Controls.TextBlock
    $hint.FontSize            = 13
    $hint.Margin              = New-Object System.Windows.Thickness(18)
    $hint.VerticalAlignment   = [System.Windows.VerticalAlignment]::Bottom
    $hint.HorizontalAlignment = [System.Windows.HorizontalAlignment]::Center
    $hint.Foreground          = New-Object System.Windows.Media.SolidColorBrush(
                                    [System.Windows.Media.Color]::FromArgb(150, 128, 128, 128))

    $state = @{ Step = 0 }

    switch ($Mode) {

        'Colours' {

            $colours = @(
                @('White',   [System.Windows.Media.Colors]::White),
                @('Black',   [System.Windows.Media.Colors]::Black),
                @('Red',     [System.Windows.Media.Colors]::Red),
                @('Green',   [System.Windows.Media.Colors]::Lime),
                @('Blue',    [System.Windows.Media.Colors]::Blue),
                @('Grey 50', ([System.Windows.Media.Color]::FromRgb(128, 128, 128)))
            )

            $state.Colours = $colours

            $window.Background = New-Object System.Windows.Media.SolidColorBrush($colours[0][1])

            $hint.Text = '{0}. Any key or click for the next, Escape to leave.' -f $colours[0][0]
        }

        'Gradient' {

            $brush = New-Object System.Windows.Media.LinearGradientBrush
            $brush.StartPoint = New-Object System.Windows.Point(0, 0)
            $brush.EndPoint   = New-Object System.Windows.Point(1, 0)

            $brush.GradientStops.Add((New-Object System.Windows.Media.GradientStop(
                [System.Windows.Media.Colors]::Black, 0.0)))
            $brush.GradientStops.Add((New-Object System.Windows.Media.GradientStop(
                [System.Windows.Media.Colors]::White, 1.0)))

            $window.Background = $brush

            $hint.Text = 'Look for steps rather than a smooth ramp. Escape to leave.'
        }

        'Grid' {

            $window.Background = [System.Windows.Media.Brushes]::Black

            $drawing = New-Object System.Windows.Controls.Canvas
            [void] $surface.Children.Add($drawing)

            # Drawn on load, when the real size is known.
            $window.Add_ContentRendered({

                $drawing.Children.Clear()

                for ($x = 0; $x -lt $drawing.ActualWidth; $x += 32) {

                    $line = New-Object System.Windows.Shapes.Line
                    $line.X1 = $x; $line.X2 = $x
                    $line.Y1 = 0;  $line.Y2 = $drawing.ActualHeight
                    $line.Stroke = [System.Windows.Media.Brushes]::White
                    $line.StrokeThickness = 1

                    [void] $drawing.Children.Add($line)
                }

                for ($y = 0; $y -lt $drawing.ActualHeight; $y += 32) {

                    $line = New-Object System.Windows.Shapes.Line
                    $line.X1 = 0;  $line.X2 = $drawing.ActualWidth
                    $line.Y1 = $y; $line.Y2 = $y
                    $line.Stroke = [System.Windows.Media.Brushes]::White
                    $line.StrokeThickness = 1

                    [void] $drawing.Children.Add($line)
                }
            }.GetNewClosure())

            $hint.Text = 'Lines should be crisp and evenly spaced. Escape to leave.'
        }
    }

    [void] $surface.Children.Add($hint)

    $advance = {
        param($shown, $advanceArgs)

        if ($Mode -ne 'Colours') {
            $window.Close()
            return
        }

        $state.Step++

        if ($state.Step -ge $state.Colours.Count) {
            $window.Close()
            return
        }

        $entry = $state.Colours[$state.Step]

        $window.Background = New-Object System.Windows.Media.SolidColorBrush($entry[1])
        $hint.Text = '{0}. Any key or click for the next, Escape to leave.' -f $entry[0]

        # The caption has to stay legible on both ends of the range.
        $hint.Foreground = if ($entry[0] -eq 'White') {
                               New-Object System.Windows.Media.SolidColorBrush(
                                   [System.Windows.Media.Color]::FromArgb(150, 60, 60, 60))
                           }
                           else {
                               New-Object System.Windows.Media.SolidColorBrush(
                                   [System.Windows.Media.Color]::FromArgb(150, 128, 128, 128))
                           }
    }.GetNewClosure()

    $window.Add_KeyDown({
        param($shown, $keyArgs)

        if ($keyArgs.Key -eq [System.Windows.Input.Key]::Escape) {
            $window.Close()
            return
        }

        & $advance $shown $keyArgs
    }.GetNewClosure())

    $window.Add_MouseLeftButtonDown($advance)

    Write-TkLog -Level Information -Category 'Hardware' -Message ('Display test: {0}.' -f $Mode)

    $window.ShowDialog() | Out-Null
}

<#
.SYNOPSIS
    Plays one test tone and reports what to listen for.
#>
function Invoke-TkToneFromUi {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [ValidateSet('Left', 'Right', 'Both')]
        [string] $Channel
    )

    Set-TkOutput -ControlName 'SoundStatus' -Text ('Playing the {0} channel...' -f $Channel.ToLowerInvariant())

    Invoke-TkBackgroundAction -StatusText ('Playing a tone: {0}...' -f $Channel) `
        -ParameterList @{ channel = $Channel } `
        -ScriptBlock {
            param($channel)

            return (Invoke-TkTonePlayback -Channel $channel)
        } `
        -OnComplete {
            param($result)

            $played = (@($result.Output) -contains $true)

            Set-TkOutput -ControlName 'SoundStatus' -Text $(
                if ($played) {
                    'Tone finished. If one channel is quieter or silent, that side is the problem: check the balance in Windows before blaming the speaker.'
                }
                else {
                    'The tone could not be played. Check that an output device is selected in Windows.'
                }
            )
        }
}

<#
.SYNOPSIS
    Plays a rising sweep.

.DESCRIPTION
    Steps through the range rather than gliding, because a stepped sweep makes
    it obvious which pitch a rattle starts at.
#>
function Invoke-TkToneSweepFromUi {
    [CmdletBinding()]
    param()

    Set-TkOutput -ControlName 'SoundStatus' -Text 'Sweeping from low to high...'

    Invoke-TkBackgroundAction -StatusText 'Playing a frequency sweep...' `
        -ScriptBlock {

            foreach ($frequency in @(120, 250, 500, 1000, 2000, 4000, 8000)) {
                $null = Invoke-TkTonePlayback -Channel 'Both' -Frequency $frequency
            }

            return $true
        } `
        -OnComplete {
            param($result)

            Set-TkOutput -ControlName 'SoundStatus' -Text (
                'Sweep finished: 120 Hz to 8 kHz in seven steps. A buzz at one step and not the others is ' +
                'usually a loose driver or a panel resonating, not the amplifier.'
            )
        }
}

<#
.SYNOPSIS
    Reads the battery and fills the panel.
#>
function Update-TkBatteryPanel {
    [CmdletBinding()]
    param()

    Invoke-TkBackgroundAction -StatusText 'Reading the battery...' `
        -ScriptBlock { Get-TkBatteryState } `
        -OnComplete {
            param($result)

            $batteries = ConvertTo-TkArray $result.Output

            Set-TkObjectTable -ControlName 'DocBattery' -InputObject $batteries `
                -Property @('Name', 'Charge', 'Health', 'FullCapacity', 'DesignCapacity') `
                -Column   @('Battery', 'Charge', 'Health', 'Holds now', 'Built to hold') `
                -Weight   @(2.0, 0.8, 0.8, 1.2, 1.2) `
                -EmptyText 'No battery is present. This is a desktop, or the pack is not reporting.'

            Set-TkStatus -Text ('{0} batter(y/ies) reported.' -f $batteries.Count)
        }
}

<#
.SYNOPSIS
    Builds the Windows battery report and opens it.
#>
function Invoke-TkBatteryReportFromUi {
    [CmdletBinding()]
    param()

    Invoke-TkBackgroundAction -StatusText 'Building the battery report...' `
        -ScriptBlock { New-TkBatteryReport } `
        -OnComplete {
            param($result)

            $path = @($result.Output) | Where-Object { $_ } | Select-Object -Last 1

            if (-not $path) {
                Set-TkStatus -Text 'No battery report was produced. This machine has no battery.'
                return
            }

            Set-TkStatus -Text ('Battery report written to {0}' -f $path)

            try {
                Start-Process -FilePath $path -ErrorAction Stop
            }
            catch {
                Write-TkLog -Level Warning -Category 'Hardware' -Message (
                    'The report was written but could not be opened: {0}' -f $_.Exception.Message
                )
            }
        }
}

<#
.SYNOPSIS
    Reads the memory modules and the attached panels.
#>
function Update-TkMemoryPanel {
    [CmdletBinding()]
    param()

    Invoke-TkBackgroundAction -StatusText 'Reading the memory modules...' `
        -ScriptBlock { Get-TkMemoryModule } `
        -OnComplete {
            param($result)

            $modules = ConvertTo-TkArray $result.Output

            Set-TkObjectTable -ControlName 'DocMemory' -InputObject $modules `
                -Property @('Slot', 'Capacity', 'Speed', 'Manufacturer', 'PartNumber') `
                -Column   @('Slot', 'Capacity', 'Speed', 'Maker', 'Part number') `
                -Weight   @(1.2, 0.9, 0.9, 1.2, 1.8) `
                -EmptyText 'The memory modules could not be read.'

            Set-TkStatus -Text ('{0} memory module(s).' -f $modules.Count)
        }

    Invoke-TkBackgroundAction -StatusText 'Reading the displays...' `
        -ScriptBlock { Get-TkDisplayPanel } `
        -OnComplete {
            param($result)

            Set-TkObjectTable -ControlName 'DocDisplays' -InputObject $result.Output `
                -Property @('Name', 'Manufacturer', 'Serial', 'Year') `
                -Column   @('Panel', 'Maker', 'Detail', 'Year') `
                -Weight   @(2.0, 1.2, 2.0, 0.6) `
                -EmptyText 'No display information was returned.'
        }
}

